def _local_em_weight_points(points, radius=4.0, max_anchors=2048):
  """Bounded, spatially stratified neighborhoods, independent of map box and atom order."""
  import numpy as np
  radius = float(radius)
  if not math.isfinite(radius) or not .5 <= radius <= 20:
    raise ValueError("Use a local sampling radius between 0.5 and 20 A.")
  points = np.asarray(points, dtype=float).reshape((-1, 3))
  if not len(points) or not np.isfinite(points).all():
    raise ValueError("No finite occupied heavy-atom coordinates are available.")
  points = np.unique(points, axis=0)
  cells = np.floor((points-points.min(axis=0))/4.).astype(np.int64)
  _, inverse, counts = np.unique(cells, axis=0, return_inverse=True, return_counts=True)
  centres = np.column_stack([np.bincount(inverse, weights=points[:, axis])/counts for axis in range(3)])
  # Stable ties (especially two-atom bins) must not change after a coordinate translation.
  distance_sq = np.round(np.sum((points-centres[inverse])**2, axis=1), 10)
  order = np.lexsort((points[:, 2], points[:, 1], points[:, 0], distance_sq, inverse))
  first = np.r_[True, np.diff(inverse[order]) != 0]
  anchors = points[order[first]]
  if len(anchors) > max_anchors:
    keep = np.random.default_rng(1729).choice(len(anchors), max_anchors, replace=False)
    anchors = anchors[np.sort(keep)]
  # Equal-volume radii and low-discrepancy directions sample signal and nearby solvent.
  n = max(32, int(math.ceil(512/len(anchors))))
  i = np.arange(n)+.5
  r = radius*(i/n)**(1/3)
  z = 1-2*np.mod(i*.7548776662466927, 1.)
  theta = 2*math.pi*np.mod(i*.5698402909980532, 1.)
  xy = np.sqrt(1-z*z)
  offsets = r[:, None]*np.column_stack((xy*np.cos(theta), xy*np.sin(theta), z))
  samples = (anchors[:, None, :]+offsets).reshape((-1, 3))
  return samples, len(anchors)


def _local_em_weight_statistics(values, reference_values=None):
  """Normalize map units once, then attenuate weak regions instead of amplifying them."""
  import numpy as np
  values = np.asarray(values, dtype=float)
  if len(values) < 32 or not np.isfinite(values).all():
    raise ValueError("Insufficient finite density samples near the model; weight unchanged.")
  sigma, mean = float(values.std()), float(values.mean())
  if sigma <= np.finfo(float).eps*max(float(np.max(np.abs(values))), np.finfo(float).tiny)*32:
    raise ValueError("The density near the model is flat or unavailable; weight unchanged.")
  reference = None if reference_values is None else _local_em_weight_statistics(reference_values)
  reference_sigma = sigma if reference is None else reference["sigma"]
  baseline_weight = 5.25/reference_sigma
  # Local contrast is a support heuristic, not an independent units calibration
  # or a measured SNR. Never compensate for a weak region with a larger weight.
  local_factor = min(1., max(.1, sigma/reference_sigma))
  weight = baseline_weight*local_factor
  if not math.isfinite(weight) or not 0 < weight <= np.finfo(np.float32).max:
    raise ValueError("The estimated weight is outside Coot's numeric range; weight unchanged.")
  return dict(weight=weight, sigma=sigma, mean=mean, samples=len(values), calibration=5.25,
              reference_sigma=reference_sigma, baseline_weight=baseline_weight, local_factor=local_factor,
              reference_samples=len(values) if reference is None else reference["samples"])


def _local_em_resolution_scale(resolution=None, lowpass_resolution=0.):
  """Quartic attenuation also counters rising inverse-sigma weights on smoother maps."""
  cutoff = float(lowpass_resolution or 0.)
  if not math.isfinite(cutoff) or not 0 <= cutoff <= 500:
    raise ValueError('Use a low-pass cutoff between 0 and 500 A (0 = unfiltered).')
  if resolution is None:
    return dict(resolution=None, effective_resolution=None, resolution_factor=1., lowpass_resolution=cutoff)
  try:
    value = float(resolution)
  except (TypeError, ValueError, OverflowError):
    raise ValueError('Enter a numeric map resolution between 0.1 and 500 A; voxel spacing is not resolution.') from None
  if not math.isfinite(value) or not .1 <= value <= 500:
    raise ValueError('Enter a map resolution between 0.1 and 500 A; voxel spacing is not resolution.')
  effective = max(value, cutoff)
  return dict(resolution=value, effective_resolution=effective,
              resolution_factor=min(1., (3./effective)**4), lowpass_resolution=cutoff)


def _local_em_resolution_identity(map_id):
  if not coot.is_valid_map_molecule(map_id):
    raise ValueError('The map is no longer available.')
  return (str(coot.molecule_name(map_id)), tuple(coot.cell_py(map_id)))


def _local_em_map_resolution(map_id):
  """Session-only, per-open-map resolution; never infer it from voxel spacing."""
  saved = globals().get('_LOCAL_EM_MAP_RESOLUTIONS', {}).get(map_id)
  if saved is None:
    return None
  try:
    if saved[0] == _local_em_resolution_identity(map_id):
      return saved[1]
  except Exception:
    pass
  globals()['_LOCAL_EM_MAP_RESOLUTIONS'].pop(map_id, None)
  return None


def _remember_local_em_map_resolution(map_id, resolution):
  value = _local_em_resolution_scale(resolution)['resolution']
  identity = _local_em_resolution_identity(map_id)
  globals().setdefault('_LOCAL_EM_MAP_RESOLUTIONS', {})[map_id] = (identity, value)


def estimate_local_em_map_weight(mol_id=None, map_id=None, radius=4.0, apply=True, residue_specs=None,
                                 reference_map_id=None, resolution=None, lowpass_resolution=0.):
  """Set an EM starting weight from near-model density, not whole-map padding.

  Explicit IDs allow inspection without changing state via apply=False. Only the
  selected refinement map can be used when applying the global refinement weight.
  Optional residue_specs use regional contrast to reduce the model-wide baseline
  weight; they do not independently renormalize weak density to full strength.
  For a filtered map, reference_map_id anchors calibration to the unfiltered map
  in the same density units; lost contrast reduces, rather than increases, weight.
  A supplied (or session-configured) resolution adds min(1, (3/d)^4) once,
  using d=max(source resolution, known low-pass cutoff) for filtered stages.
  """
  if mol_id is None:
    active = _active_residue_or_status()
    if not active:
      raise ValueError("Choose an active model first.")
    mol_id = active[0]
  if map_id is None:
    map_id = coot.imol_refinement_map()
  if not valid_model_molecule_qm(mol_id) or not coot.is_valid_map_molecule(map_id):
    raise ValueError("Choose a valid model and selected refinement map first.")
  if callable(getattr(coot, "map_is_difference_map", None)) and coot.map_is_difference_map(map_id):
    raise ValueError("Use the EM reconstruction, not a difference map.")
  reference_map_id = map_id if reference_map_id is None else reference_map_id
  if not coot.is_valid_map_molecule(reference_map_id):
    raise ValueError("Choose a valid original reference map for weight estimation.")
  if callable(getattr(coot, "map_is_difference_map", None)) and coot.map_is_difference_map(reference_map_id):
    raise ValueError("Use a reconstruction, not a difference reference map.")
  if apply and (coot.refinement_already_ongoing_p() or coot.imol_refinement_map() != map_id):
    raise ValueError("Accept/cancel refinement and select this refinement map before changing its weight.")
  if resolution is None:
    resolution = _local_em_map_resolution(reference_map_id)
  resolution_info = _local_em_resolution_scale(resolution, lowpass_resolution)
  snapshot = _model_coordinate_snapshot(mol_id)
  specs = list(snapshot) if residue_specs is None else list(dict.fromkeys(tuple(s) for s in residue_specs))
  if not specs or any(spec not in snapshot for spec in specs):
    raise ValueError("Select existing residues for local map-weight estimation.")
  points, reference_points = [], []
  selected = set(specs)
  for spec, record in snapshot.items():
    if str(record["name"]).strip().upper() in ("HOH", "WAT", "DOD"):
      continue
    for atom in _tq_residue_atom_records(mol_id, spec, snapshot=snapshot):
      if atom["occupancy"] > 0:
        reference_points.append(atom["xyz"])
        if spec in selected:
          points.append(atom["xyz"])
  samples, anchors = _local_em_weight_points(points, radius)
  values = [float(coot.density_at_point(map_id, *map(float, point))) for point in samples]
  reference_values = None
  if len(specs) != len(snapshot) or reference_map_id != map_id:
    reference_samples = samples if len(specs) == len(snapshot) else _local_em_weight_points(reference_points, radius)[0]
    reference_values = [float(coot.density_at_point(reference_map_id, *map(float, point))) for point in reference_samples]
  result = _local_em_weight_statistics(values, reference_values)
  result['density_weight'] = result['weight']
  result.update(resolution_info)
  result['weight'] *= result['resolution_factor']
  result.update(model=mol_id, map=map_id, reference_map=reference_map_id, radius=float(radius), anchors=anchors, atoms=len(points),
                region_residues=len(specs), applied=False)
  if apply:
    previous = float(coot.matrix_state())
    try:
      coot.set_matrix(result["weight"])
      actual = float(coot.matrix_state())
      if not math.isfinite(actual) or not math.isclose(actual, result["weight"], rel_tol=1e-5):
        raise RuntimeError("Coot did not accept the estimated refinement weight.")
    except Exception:
      coot.set_matrix(previous)
      raise
    result.update(previous_weight=previous, applied=True)
  return result


def _apply_local_em_refinement_weight(resolution, mol_id=None, map_id=None):
  """Apply once, remembering an explicitly entered resolution only after success."""
  add_status_bar_text("Estimating EM refinement weight from density near the active model...")
  try:
    resolution = _local_em_resolution_scale(resolution)['resolution']
    if resolution is None:
      raise ValueError('Enter the nominal map resolution first.')
    # Capture map identity before changing any state, so failed metadata access
    # cannot leave a half-applied resolution preference.
    selected = coot.imol_refinement_map() if map_id is None else map_id
    identity = _local_em_resolution_identity(selected)
    result = estimate_local_em_map_weight(mol_id, selected, resolution=resolution)
    globals().setdefault('_LOCAL_EM_MAP_RESOLUTIONS', {})[selected] = (identity, resolution)
    message = (f"EM refinement weight: {result['previous_weight']:.4g} -> {result['weight']:.4g} | "
               f"Model #{result['model']}, map #{result['map']} | local sigma {result['sigma']:.4g} "
               f"within {result['radius']:g} A | {resolution:g} A resolution x {result['resolution_factor']:.4g} "
               f"({result['samples']} samples).")
    add_status_bar_text(message)
    print(message + " Starting estimate, not geometry-optimized; ordinary B-factors and contour level are not used.")
    return result
  except Exception as error:
    info_dialog(f"Could not estimate a local EM refinement weight.\n\n{error}")
    return None


def set_local_em_refinement_weight(resolution=None):
  """Prompt for nominal resolution; explicit console calls can supply it directly."""
  if resolution is not None:
    return _apply_local_em_refinement_weight(resolution)
  try:
    active = _active_residue_or_status()
    if not active:
      return None
    model, map_id = active[0], coot.imol_refinement_map()
    if not valid_model_molecule_qm(model) or not coot.is_valid_map_molecule(map_id):
      raise ValueError('Choose an active model and refinement map first.')
    if globals().get('Gtk') is None:
      raise ValueError('The resolution prompt needs GTK; use set_local_em_refinement_weight(resolution=3.5) in the console.')
    window = Gtk.Window(title='EM refinement weight')
    window.set_default_size(480, -1)
    box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=10)
    for edge in ('top', 'bottom', 'start', 'end'):
      getattr(box, 'set_margin_'+edge)(12)
    window.set_child(box)
    identity = Gtk.Label(label=f"Model #{model}: {os.path.basename(str(coot.molecule_name(model)))}\n"
                               f"Refinement map #{map_id}: {os.path.basename(str(coot.molecule_name(map_id)))}", xalign=0)
    identity.set_wrap(True)
    identity.set_max_width_chars(64)
    box.append(identity)
    row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
    row.append(Gtk.Label(label='Map resolution (A)'))
    entry = Gtk.Entry()
    entry.set_width_chars(7)
    entry.set_max_width_chars(9)
    entry.set_placeholder_text('e.g. 3.5')
    entry.set_tooltip_text('Map resolution in Angstroms, not voxel size. Remembered for this map during this session.')
    previous = _local_em_map_resolution(map_id)
    entry.set_text(f'{previous if previous is not None else 3.:g}')
    row.append(entry)
    box.append(row)
    explanation = Gtk.Label(label='Use map resolution, not voxel size.', xalign=0)
    explanation.set_wrap(True)
    explanation.set_max_width_chars(64)
    box.append(explanation)
    status = Gtk.Label(label='', xalign=0)
    status.set_wrap(True)
    status.set_max_width_chars(64)
    status.set_visible(False)
    box.append(status)
    buttons = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
    apply, close = Gtk.Button(label='Estimate and apply'), Gtk.Button(label='Close')
    buttons.append(apply)
    buttons.append(close)
    box.append(buttons)
    state = dict(result=None)
    def calculate(*_args):
      status.set_visible(True)
      try:
        value = _local_em_resolution_scale(entry.get_text())['resolution']
      except (TypeError, ValueError) as error:
        status.set_text(str(error))
        return
      result = _apply_local_em_refinement_weight(value, model, map_id)
      state['result'] = result
      if result is not None:
        status.set_text(f"Weight: {result['previous_weight']:.4g} -> {result['weight']:.4g}")
      else:
        status.set_text('Weight unchanged.')
    apply.connect('clicked', calculate)
    close.connect('clicked', lambda *_: window.close())
    window.local_em_weight_widgets = dict(resolution=entry, apply=apply, close=close, status=status, state=state)
    window.present()
    return window
  except Exception as error:
    info_dialog(f'Could not open EM weight estimation.\n\n{error}')
    return None


def _tq_map_sigma(map_id):
  try:
    sigma_value = float(map_sigma_py(map_id))
    if math.isfinite(sigma_value) and sigma_value > 0.0:
      return sigma_value
  except Exception:
    pass
  try:
    contour_absolute = float(get_contour_level_absolute(map_id))
    contour_sigma = float(get_contour_level_in_sigma(map_id))
    if math.isfinite(contour_absolute) and math.isfinite(contour_sigma) and abs(contour_sigma) > 1.0e-9:
      sigma_value = abs(contour_absolute / contour_sigma)
      if sigma_value > 0.0:
        return sigma_value
  except Exception:
    pass
  return None


def _tq_valid_model_molecule(mol_id):
  checker = globals().get("valid_model_molecule_qm")
  if callable(checker):
    try:
      return checker(mol_id) == 1 or checker(mol_id) is True
    except Exception:
      pass
  return mol_id in model_molecule_list()


def _tq_valid_map_molecule(map_id):
  checker = globals().get("valid_map_molecule_qm")
  if callable(checker):
    try:
      return checker(map_id) == 1 or checker(map_id) is True
    except Exception:
      pass
  return map_id in map_molecule_list()


def _tq_chain_ids(mol_id):
  getter = globals().get("chain_ids")
  if callable(getter):
    try:
      return getter(mol_id) or []
    except Exception:
      pass
  return []


def _tq_post_map_level_status(map_id, prefix="set to"):
  _post_map_level_status(map_id, prefix)


def _tq_active_residue_target():
  residue = _active_residue_or_status()
  if not residue or len(residue) < 4:
    return None
  parsed = _coot_residue_spec_from_spec(residue[1:4])
  if parsed is None:
    _tq_status("Thresholded Q-residue: could not parse the active residue")
    return None
  return (residue[0], parsed[0], parsed[1], parsed[2])


def _tq_is_heavy_atom(atom_name, element):
  element = _coot_text_arg(element).strip().upper()
  atom_name = _coot_text_arg(atom_name).strip().upper()
  if element:
    return element not in _THRESHOLDED_Q_HYDROGEN_ELEMENTS
  return not atom_name.startswith("H")


def _tq_residue_label(chain_id, resno, ins_code, residue_name_here=""):
  residue_id = f"{chain_id}:{resno}{ins_code or ''}"
  if residue_name_here:
    return f"{residue_id} {_display_residue_name(residue_name_here)}"
  return residue_id


def _tq_gaussian_enclosed_mass_fraction(radius_over_sigma):
  if radius_over_sigma <= 0.0:
    return 0.0
  scaled_radius = radius_over_sigma / math.sqrt(2.0)
  return (
    math.erf(scaled_radius)
    - math.sqrt(2.0 / math.pi) * radius_over_sigma * math.exp(-(radius_over_sigma ** 2) / 2.0)
  )


@lru_cache(maxsize=64)
def _tq_support_radius(sigma, enclosed_mass_percent):
  target_fraction = max(0.0, min(0.999999, float(enclosed_mass_percent) / 100.0))
  if target_fraction <= 0.0:
    return 0.0
  if target_fraction >= 0.999999:
    return 5.0 * float(sigma)
  low = 0.0
  high = 8.0
  for _ in range(60):
    mid = 0.5 * (low + high)
    if _tq_gaussian_enclosed_mass_fraction(mid) < target_fraction:
      low = mid
    else:
      high = mid
  return 0.5 * (low + high) * float(sigma)


def _tq_residue_atom_records(mol_id, residue_spec, heavy_atoms_only=True, snapshot=None):
  parsed = _coot_residue_spec_from_spec(residue_spec)
  if parsed is None:
    return []
  chain_id, resno, ins_code = parsed
  cached = snapshot.get(parsed) if snapshot is not None else None
  residue_name_here = cached["name"] if cached is not None else _tq_residue_name(mol_id, chain_id, resno, ins_code)
  atom_records = []
  atoms = cached["atoms"] if cached is not None else _tq_residue_info(mol_id, chain_id, resno, ins_code)
  for atom in atoms:
    try:
      atom_name = _coot_text_arg(atom[0][0]).strip()
      alt_conf = _coot_text_arg(atom[0][1]).strip()
      occupancy = float(atom[1][0])
      b_factor = atom[1][1]
      element = _coot_text_arg(atom[1][2]).strip().upper()
      xyz = [float(atom[2][0]), float(atom[2][1]), float(atom[2][2])]
    except Exception:
      continue
    if not atom_name:
      continue
    if not math.isfinite(occupancy) or not all(math.isfinite(value) for value in xyz):
      raise RuntimeError(f"Invalid atom coordinates or occupancy at {chain_id}:{resno}{ins_code}.")
    if heavy_atoms_only and not _tq_is_heavy_atom(atom_name, element):
      continue
    atom_records.append(
      {
        "residue_spec": parsed,
        "residue_name": residue_name_here,
        "name": atom_name,
        "alt_conf": alt_conf,
        "atom_key": (parsed, atom_name, alt_conf),
        "occupancy": occupancy,
        "b_factor": b_factor,
        "element": element,
        "xyz": xyz,
      }
    )
  return atom_records


def _tq_score_atom_records(atom_records, backbone_only=False):
  if not backbone_only:
    return list(atom_records)
  return [atom for atom in atom_records if atom["name"] in _THRESHOLDED_Q_BACKBONE_ATOM_NAMES]


def _tq_chain_residue_specs(mol_id, chain_id):
  residue_specs = []
  seen_specs = set()
  try:
    n_residues = chain_n_residues(chain_id, mol_id)
  except Exception:
    return residue_specs
  for serial_number in range(n_residues):
    try:
      resno = seqnum_from_serial_number(mol_id, chain_id, serial_number)
      ins_code = _coot_text_arg(insertion_code_from_serial_number(mol_id, chain_id, serial_number))
    except Exception:
      continue
    residue_spec = _coot_residue_spec_tuple(chain_id, resno, ins_code)
    if residue_spec[1] is None or residue_spec in seen_specs:
      continue
    residue_specs.append(residue_spec)
    seen_specs.add(residue_spec)
  return residue_specs


def _tq_residue_specs_near_residue_centres(
    mol_id,
    seed_residue_specs,
    radius=THRESHOLDED_Q_LOCAL_RADIUS,
    max_residues=THRESHOLDED_Q_LOCAL_MAX_RESIDUES,
    snapshot=None,
):
  snapshot = _model_coordinate_snapshot(mol_id) if snapshot is None else snapshot
  centres = _coordinate_snapshot_centres(snapshot)
  seed_specs = []
  seed_centres = []
  for residue_spec in seed_residue_specs:
    parsed = _coot_residue_spec_from_spec(residue_spec)
    if parsed is None:
      continue
    seed_specs.append(parsed)
    centre = centres.get(parsed)
    if centre is not None:
      seed_centres.append(centre)
  if not seed_specs:
    return []
  if not seed_centres:
    return list(seed_specs)

  radius_sq = float(radius) * float(radius)
  nearby_entries = []
  seen_specs = set(seed_specs)
  for seed_spec in seed_specs:
    nearby_entries.append((0.0, seed_spec))

  centre_index = _spatial_index(centres.items(), lambda item: item[1], max(float(radius), 1.0))
  for seed_centre in seed_centres:
    for residue_spec, centre in _spatial_query(centre_index, seed_centre, float(radius)):
      if residue_spec not in seen_specs:
        nearest_seed_distance_sq = min(_distance_sq(centre, point) for point in seed_centres)
        nearby_entries.append((nearest_seed_distance_sq, residue_spec))
        seen_specs.add(residue_spec)

  nearby_entries.sort(key=lambda item: (item[0], item[1][0], item[1][1], item[1][2]))
  return [entry[1] for entry in (nearby_entries if max_residues is None else nearby_entries[:int(max_residues)])]


def _tq_context_atom_records(mol_id, score_residue_specs, context_radius, snapshot=None,
                             influence_radius=0.0):
  snapshot = _model_coordinate_snapshot(mol_id) if snapshot is None else snapshot
  context_residue_specs = _tq_residue_specs_near_residue_centres(
    mol_id,
    score_residue_specs,
    radius=context_radius,
    max_residues=None,
    snapshot=snapshot,
  )
  selected = set(context_residue_specs)
  score_points = [atom[2] for spec in score_residue_specs for atom in snapshot.get(tuple(spec), {}).get("atoms", [])]
  if score_points and influence_radius > 0:
    centre = tuple(sum(point[axis] for point in score_points) / len(score_points) for axis in range(3))
    bound_sq = (max(math.sqrt(_distance_sq(point, centre)) for point in score_points) + influence_radius)**2
    selected.update(spec for spec, record in snapshot.items()
                    if any(_distance_sq(atom[2], centre) <= bound_sq for atom in record["atoms"]))
  atom_records = []
  for residue_spec in sorted(selected):
    atom_records.extend(_tq_residue_atom_records(mol_id, residue_spec, heavy_atoms_only=True, snapshot=snapshot))
  return atom_records


def _tq_prune_context_atoms(score_atom_records, context_atom_records, sigma, sample_radius):
  influence_radius = float(sample_radius) + float(sigma) * THRESHOLDED_Q_CONTEXT_ATOM_INFLUENCE_SIGMA
  index = _spatial_index(enumerate(context_atom_records), lambda item: item[1]["xyz"], influence_radius)
  keep = {i for atom in score_atom_records for i, _record in _spatial_query(index, atom["xyz"], influence_radius)}
  pruned_context_atoms = [record for i, record in enumerate(context_atom_records) if i in keep]
  return pruned_context_atoms or list(context_atom_records)


def _tq_candidate_grid_indices(score_atom_records, sample_radius, grid_spacing):
  sample_radius_sq = sample_radius * sample_radius
  candidate_indices = set()
  for atom_record in score_atom_records:
    atom_x, atom_y, atom_z = atom_record["xyz"]
    x_index_range = range(
      int(math.floor((atom_x - sample_radius) / grid_spacing)),
      int(math.ceil((atom_x + sample_radius) / grid_spacing)) + 1,
    )
    y_index_range = range(
      int(math.floor((atom_y - sample_radius) / grid_spacing)),
      int(math.ceil((atom_y + sample_radius) / grid_spacing)) + 1,
    )
    z_index_range = range(
      int(math.floor((atom_z - sample_radius) / grid_spacing)),
      int(math.ceil((atom_z + sample_radius) / grid_spacing)) + 1,
    )
    for ix in x_index_range:
      x = ix * grid_spacing
      dx_sq = (x - atom_x) * (x - atom_x)
      if dx_sq > sample_radius_sq:
        continue
      for iy in y_index_range:
        y = iy * grid_spacing
        dxy_sq = dx_sq + (y - atom_y) * (y - atom_y)
        if dxy_sq > sample_radius_sq:
          continue
        for iz in z_index_range:
          z = iz * grid_spacing
          distance_sq = dxy_sq + (z - atom_z) * (z - atom_z)
          if distance_sq > sample_radius_sq:
            continue
          candidate_indices.add((ix, iy, iz))
  return sorted(candidate_indices)


def _tq_numpy_module():
  module = globals().get("_THRESHOLDED_Q_NUMPY", False)
  if module is False:
    try:
      import numpy as module
    except ImportError:
      module = None
    globals()["_THRESHOLDED_Q_NUMPY"] = module
  return module


def _tq_sample_density(map_id, x, y, z):
  try:
    value = float(density_at_point(map_id, x, y, z))
    if not math.isfinite(value):
      raise ValueError("non-finite density")
    return value
  except Exception as error:
    raise RuntimeError(
      f"Map #{map_id} density sampling failed at ({x:.3f}, {y:.3f}, {z:.3f}): {error}"
    ) from error


def _tq_residue_point_records_numpy(np, map_id, score_atoms, context_atoms, sigma, radius, spacing, density_cache=None):
  indices = _tq_candidate_grid_indices(score_atoms, radius, spacing)
  coordinates = np.asarray([atom["xyz"] for atom in context_atoms], dtype=float)
  occupancies = np.asarray([atom.get("occupancy", 1.0) for atom in context_atoms], dtype=float)
  score_keys = {atom["atom_key"] for atom in score_atoms}
  owners = np.asarray([atom["atom_key"] in score_keys for atom in context_atoms], dtype=bool)
  # Bound temporary point-by-atom matrices, even in very crowded regions.
  batch_size = max(1, min(512, 262144 // len(context_atoms)))
  records = []
  for start in range(0, len(indices), batch_size):
    points = np.asarray(indices[start:start+batch_size], dtype=float) * spacing
    distances = np.zeros((len(points), len(context_atoms)), dtype=float)
    for axis in range(3):
      delta = points[:, axis, None] - coordinates[None, :, axis]
      distances += delta * delta
    keep = owners[np.argmin(distances, axis=1)]
    points = points[keep]
    distances = distances[keep]
    distances *= -1.0 / (2.0 * sigma * sigma)
    np.exp(distances, out=distances)
    distances *= occupancies
    ideals = distances.sum(axis=1)
    values = (_analysis_density_values(map_id, points, density_cache) if density_cache is not None else
              [_tq_sample_density(map_id, *map(float, point)) for point in points])
    for value, ideal in zip(values, ideals):
      records.append({"experimental_density": value,
                      "ideal_density": float(ideal)})
  return records


def _tq_residue_point_records(map_id, score_atom_records, context_atom_records, sigma, sample_radius, grid_spacing, density_cache=None):
  if not score_atom_records or not context_atom_records:
    return []
  np = _tq_numpy_module()
  if np is not None:
    return _tq_residue_point_records_numpy(np, map_id, score_atom_records, context_atom_records,
                                            sigma, sample_radius, grid_spacing, density_cache)

  score_atom_keys = {atom_record["atom_key"] for atom_record in score_atom_records}
  context_atom_data = [
    (*context_atom["xyz"], context_atom["atom_key"])
    for context_atom in context_atom_records
  ]
  occupancies = [float(atom.get("occupancy", 1.0)) for atom in context_atom_records]
  distances = [0.0] * len(context_atom_data)
  gaussian_denominator = 2.0 * sigma * sigma
  exp = math.exp
  point_records = []
  candidate_indices = _tq_candidate_grid_indices(score_atom_records, sample_radius, grid_spacing)

  for ix, iy, iz in candidate_indices:
    x = ix * grid_spacing
    y = iy * grid_spacing
    z = iz * grid_spacing
    # Every candidate is already inside a scoring atom's sampling sphere.
    nearest_context_atom_key = None
    nearest_context_distance_sq = None
    for index, (atom_x, atom_y, atom_z, context_atom_key) in enumerate(context_atom_data):
      dx, dy, dz = x-atom_x, y-atom_y, z-atom_z
      distance_sq = dx*dx + dy*dy + dz*dz
      distances[index] = distance_sq
      if nearest_context_distance_sq is None or distance_sq < nearest_context_distance_sq:
        nearest_context_distance_sq = distance_sq
        nearest_context_atom_key = context_atom_key

    if nearest_context_atom_key is None or nearest_context_atom_key not in score_atom_keys:
      continue

    ideal_density = 0.0
    for distance_sq, occupancy in zip(distances, occupancies):
      ideal_density += occupancy * exp(-distance_sq / gaussian_denominator)

    experimental_density = _tq_sample_density(map_id, x, y, z)

    point_records.append(
      {
        "experimental_density": experimental_density,
        "ideal_density": ideal_density,
      }
    )

  return point_records


def _tq_ideal_density_threshold(point_records, ideal_enclosed_mass_percent):
  positive_densities = sorted(
    (point_record["ideal_density"] for point_record in point_records if point_record["ideal_density"] > 0.0),
    reverse=True,
  )
  if not positive_densities:
    return 0.0
  total_mass = sum(positive_densities)
  target_mass = total_mass * max(0.0, min(100.0, float(ideal_enclosed_mass_percent))) / 100.0
  if target_mass <= 0.0:
    return positive_densities[0] + 1.0e-6
  cumulative_mass = 0.0
  threshold = positive_densities[-1]
  for density_value in positive_densities:
    cumulative_mass += density_value
    threshold = density_value
    if cumulative_mass >= target_mass:
      break
  return threshold


def _tq_residue_region_score(point_records, contour_level, ideal_density_threshold):
  ideal_points = 0
  experimental_points = 0
  overlap_points = 0
  for point_record in point_records:
    ideal_on = point_record["ideal_density"] >= ideal_density_threshold and point_record["ideal_density"] > 0.0
    experimental_on = point_record["experimental_density"] >= contour_level
    if ideal_on:
      ideal_points += 1
    if experimental_on:
      experimental_points += 1
    if ideal_on and experimental_on:
      overlap_points += 1

  denominator = ideal_points + experimental_points
  score = 0.0 if denominator <= 0 else (2.0 * overlap_points) / float(denominator)
  return {
    "score": score,
    "ideal_points": ideal_points,
    "experimental_points": experimental_points,
    "overlap_points": overlap_points,
    "n_points": len(point_records),
  }


def _tq_residue_region_sweep_data(point_records, ideal_density_threshold):
  ideal_flags = [
    (point_record["ideal_density"] >= ideal_density_threshold and point_record["ideal_density"] > 0.0)
    for point_record in point_records
  ]
  ideal_points = sum(1 for ideal_on in ideal_flags if ideal_on)
  sorted_pairs = sorted(
    zip((point_record["experimental_density"] for point_record in point_records), ideal_flags),
    key=lambda pair: pair[0],
  )
  experimental_densities = [pair[0] for pair in sorted_pairs]
  overlap_suffix = [0] * (len(sorted_pairs) + 1)
  for index in range(len(sorted_pairs) - 1, -1, -1):
    overlap_suffix[index] = overlap_suffix[index + 1] + (1 if sorted_pairs[index][1] else 0)
  return {
    "ideal_points": ideal_points,
    "n_points": len(point_records),
    "experimental_densities": experimental_densities,
    "overlap_suffix": overlap_suffix,
  }


def _tq_residue_region_score_from_sweep_data(sweep_data, contour_level):
  experimental_densities = sweep_data["experimental_densities"]
  idx = bisect_left(experimental_densities, contour_level)
  experimental_points = len(experimental_densities) - idx
  overlap_points = sweep_data["overlap_suffix"][idx]
  ideal_points = sweep_data["ideal_points"]
  denominator = ideal_points + experimental_points
  score = 0.0 if denominator <= 0 else (2.0 * overlap_points) / float(denominator)
  return {
    "score": score,
    "ideal_points": ideal_points,
    "experimental_points": experimental_points,
    "overlap_points": overlap_points,
    "n_points": sweep_data["n_points"],
  }


def _tq_prepare_scored_residues(
    map_id,
    mol_id,
    residue_specs,
    sigma=THRESHOLDED_Q_GAUSSIAN_SIGMA,
    ideal_enclosed_mass_percent=THRESHOLDED_Q_IDEAL_ENCLOSED_MASS_PERCENT,
    grid_spacing=THRESHOLDED_Q_GRID_SPACING,
    sample_shell_padding=THRESHOLDED_Q_SAMPLE_SHELL_PADDING,
    context_radius=None,
    backbone_only=False,
    snapshot=None,
):
  try:
    sigma = float(sigma)
    grid_spacing = float(grid_spacing)
    sample_shell_padding = float(sample_shell_padding)
    ideal_enclosed_mass_percent = float(ideal_enclosed_mass_percent)
  except Exception:
    return None
  if not all(math.isfinite(value) for value in (sigma, grid_spacing, sample_shell_padding, ideal_enclosed_mass_percent)) or sigma <= 0.0 or grid_spacing <= 0.0 or sample_shell_padding < 0.0 or not 0 <= ideal_enclosed_mass_percent <= 100:
    return None

  score_residue_specs = []
  for residue_spec in residue_specs:
    parsed = _coot_residue_spec_from_spec(residue_spec)
    if parsed is not None and parsed not in score_residue_specs:
      score_residue_specs.append(parsed)
  if not score_residue_specs:
    return None

  support_radius = _tq_support_radius(sigma, float(ideal_enclosed_mass_percent))
  sample_radius = sigma * THRESHOLDED_Q_SAMPLE_RADIUS_SIGMA + sample_shell_padding
  if context_radius is None:
    context_radius = THRESHOLDED_Q_LOCAL_RADIUS
  context_radius = max(float(context_radius), float(sample_radius))
  snapshot = _model_coordinate_snapshot(mol_id) if snapshot is None else snapshot
  influence_radius = sample_radius + sigma * THRESHOLDED_Q_CONTEXT_ATOM_INFLUENCE_SIGMA
  context_atom_records = _tq_context_atom_records(mol_id, score_residue_specs, context_radius,
                                                snapshot=snapshot, influence_radius=influence_radius)
  if not context_atom_records:
    return None

  prepared_residues = []
  density_cache = _analysis_density_open(map_id, (atom["xyz"] for atom in context_atom_records), padding=sample_radius+4.,
                                         expected_samples=len(score_residue_specs)*4000)
  try:
    for residue_spec in score_residue_specs:
      score_atom_records = _tq_score_atom_records(
        _tq_residue_atom_records(mol_id, residue_spec, heavy_atoms_only=True, snapshot=snapshot),
        backbone_only=backbone_only,
      )
      if not score_atom_records:
        continue
      residue_context_atoms = _tq_prune_context_atoms(score_atom_records, context_atom_records, sigma, sample_radius)
      point_records = _tq_residue_point_records(
        map_id, score_atom_records, residue_context_atoms, sigma, sample_radius, grid_spacing, density_cache)
      if not point_records:
        continue
      residue_name_here = score_atom_records[0]["residue_name"]
      ideal_density_threshold = _tq_ideal_density_threshold(point_records, ideal_enclosed_mass_percent)
      prepared_residues.append(
        {
          "residue_spec": residue_spec,
          "residue_name": residue_name_here,
          "label": _tq_residue_label(residue_spec[0], residue_spec[1], residue_spec[2], residue_name_here),
          "n_atoms": len(score_atom_records),
          "n_points": len(point_records),
          "ideal_density_threshold": ideal_density_threshold,
          "region_sweep_data": _tq_residue_region_sweep_data(point_records, ideal_density_threshold),
        }
      )
  finally:
    _analysis_density_close(density_cache)

  if not prepared_residues:
    return None

  return {
    "map_id": map_id,
    "mol_id": mol_id,
    "score_residue_specs": score_residue_specs,
    "support_radius": support_radius,
    "sample_radius": sample_radius,
    "sigma": float(sigma),
    "ideal_enclosed_mass_percent": float(ideal_enclosed_mass_percent),
    "prepared_residues": prepared_residues,
  }


def _tq_prepare_scored_residues_or_status(*args, quiet=False, **kwargs):
  try:
    prepared = _tq_prepare_scored_residues(*args, **kwargs)
    if prepared is None and not quiet:
      _tq_status("Thresholded Q-residue: no scorable atoms or invalid sampling parameters")
    return prepared
  except (RuntimeError, ValueError, TypeError, OverflowError) as error:
    # Never optimize against a partially sampled map or fabricated zero density.
    if not quiet:
      _tq_status(f"Thresholded Q-residue: calculation aborted. {error}")
    return None


def thresholded_q_residues(
    map_id,
    mol_id,
    residue_specs,
    contour_level=None,
    sigma=THRESHOLDED_Q_GAUSSIAN_SIGMA,
    ideal_enclosed_mass_percent=THRESHOLDED_Q_IDEAL_ENCLOSED_MASS_PERCENT,
    grid_spacing=THRESHOLDED_Q_GRID_SPACING,
    sample_shell_padding=THRESHOLDED_Q_SAMPLE_SHELL_PADDING,
    context_radius=None,
    backbone_only=False,
    quiet=False,
):
  map_id = _tq_map_id_or_default(map_id)
  try:
    sigma = float(sigma)
    grid_spacing = float(grid_spacing)
    sample_shell_padding = float(sample_shell_padding)
    if context_radius is not None:
      context_radius = float(context_radius)
  except Exception:
    message = "Thresholded Q-residue: invalid numeric parameter"
    if not quiet:
      _tq_status(message)
    return None
  if sigma <= 0.0 or grid_spacing <= 0.0 or sample_shell_padding < 0.0:
    message = "Thresholded Q-residue: sigma/grid spacing must be > 0 and shell padding must be >= 0"
    if not quiet:
      _tq_status(message)
    return None
  if not _tq_valid_map_molecule(map_id):
    message = f"Thresholded Q-residue: invalid map #{map_id}"
    if not quiet:
      _tq_status(message)
    return None
  if not _tq_valid_model_molecule(mol_id):
    message = f"Thresholded Q-residue: invalid model molecule #{mol_id}"
    if not quiet:
      _tq_status(message)
    return None
  if contour_level is None:
    try:
      contour_level = float(get_contour_level_absolute(map_id))
    except Exception:
      contour_level = None
  if contour_level is None:
    contour_level = 0.0
  try:
    contour_level = float(contour_level)
    if not math.isfinite(contour_level):
      raise ValueError("non-finite contour")
  except (TypeError, ValueError, OverflowError):
    if not quiet:
      _tq_status("Thresholded Q-residue: invalid contour level")
    return None

  prepared = _tq_prepare_scored_residues_or_status(
    map_id,
    mol_id,
    residue_specs,
    sigma=sigma,
    ideal_enclosed_mass_percent=ideal_enclosed_mass_percent,
    grid_spacing=grid_spacing,
    sample_shell_padding=sample_shell_padding,
    context_radius=context_radius,
    backbone_only=backbone_only,
    quiet=quiet,
  )
  if prepared is None:
    return None

  residue_scores = []
  for prepared_residue in prepared["prepared_residues"]:
    region_score = _tq_residue_region_score_from_sweep_data(
      prepared_residue["region_sweep_data"],
      contour_level,
    )
    residue_scores.append(
      {
        "residue_spec": prepared_residue["residue_spec"],
        "residue_name": prepared_residue["residue_name"],
        "label": prepared_residue["label"],
        "score": region_score["score"],
        "n_atoms": prepared_residue["n_atoms"],
        "n_points": region_score["n_points"],
        "ideal_points": region_score["ideal_points"],
        "experimental_points": region_score["experimental_points"],
        "overlap_points": region_score["overlap_points"],
        "ideal_density_threshold": prepared_residue["ideal_density_threshold"],
      }
    )

  overall_score = 0.0
  if residue_scores:
    overall_score = sum(residue_score["score"] for residue_score in residue_scores) / float(len(residue_scores))

  result = {
    "map_id": map_id,
    "mol_id": mol_id,
    "contour_level": contour_level,
    "score": overall_score,
    "residue_scores": residue_scores,
    "support_radius": prepared["support_radius"],
    "sample_radius": prepared["sample_radius"],
    "sigma": prepared["sigma"],
    "ideal_enclosed_mass_percent": prepared["ideal_enclosed_mass_percent"],
  }

  if not quiet:
    labels = ", ".join(residue_score["label"] for residue_score in residue_scores[:4])
    if len(residue_scores) > 4:
      labels += ", ..."
    _tq_status(
      "Thresholded Q-residue at level {0:.4f}: score {1:.3f} for {2} residue(s) in {3} [{4}]".format(
        contour_level,
        overall_score,
        len(residue_scores),
        _molecule_id_name_label(mol_id),
        labels or "no labels",
      )
    )
  return result


def thresholded_q_residue(map_id, mol_id, residue_spec, **kwargs):
  result = thresholded_q_residues(map_id, mol_id, [residue_spec], **kwargs)
  if result is None:
    return None
  if result["residue_scores"]:
    result["residue_score"] = result["residue_scores"][0]
  else:
    result["residue_score"] = None
  return result


def thresholded_q_active_residue(
    map_id=None,
    ideal_enclosed_mass_percent=THRESHOLDED_Q_IDEAL_ENCLOSED_MASS_PERCENT,
    **kwargs,
):
  target = _tq_active_residue_target()
  if target is None:
    message = "Thresholded Q-residue: no active residue"
    _tq_status(message)
    return None
  mol_id, chain_id, resno, ins_code = target
  return thresholded_q_residue(
    _tq_map_id_or_default(map_id),
    mol_id,
    (chain_id, resno, ins_code),
    ideal_enclosed_mass_percent=ideal_enclosed_mass_percent,
    **kwargs,
  )


def optimize_local_threshold_by_thresholded_q(
    map_id,
    mol_id,
    residue_specs,
    contour_min=None,
    contour_max=None,
    contour_min_sigma=None,
    contour_max_sigma=None,
    n_steps=THRESHOLDED_Q_SWEEP_STEPS,
    sigma=THRESHOLDED_Q_GAUSSIAN_SIGMA,
    ideal_enclosed_mass_percent=THRESHOLDED_Q_IDEAL_ENCLOSED_MASS_PERCENT,
    grid_spacing=THRESHOLDED_Q_GRID_SPACING,
    sample_shell_padding=THRESHOLDED_Q_SAMPLE_SHELL_PADDING,
    context_radius=None,
    backbone_only=False,
    apply_contour=False,
    quiet=False,
    snapshot=None,
):
  map_id = _tq_map_id_or_default(map_id)
  try:
    sigma = float(sigma)
    grid_spacing = float(grid_spacing)
    sample_shell_padding = float(sample_shell_padding)
    n_steps = int(n_steps)
    ideal_enclosed_mass_percent = float(ideal_enclosed_mass_percent)
    if not all(math.isfinite(value) for value in (sigma, grid_spacing, sample_shell_padding, ideal_enclosed_mass_percent)):
      raise ValueError("Non-finite sampling parameter")
    if not 0.0 < ideal_enclosed_mass_percent <= 100.0:
      raise ValueError("Enclosed mass must be in (0, 100]")
    contour_min = float(contour_min) if contour_min is not None else None
    contour_max = float(contour_max) if contour_max is not None else None
    contour_min_sigma = float(contour_min_sigma) if contour_min_sigma is not None else None
    contour_max_sigma = float(contour_max_sigma) if contour_max_sigma is not None else None
    if not all(math.isfinite(value) for value in (contour_min, contour_max, contour_min_sigma, contour_max_sigma) if value is not None):
      raise ValueError("Non-finite contour bound")
    if context_radius is not None:
      context_radius = float(context_radius)
      if not math.isfinite(context_radius) or context_radius <= 0:
        raise ValueError("Invalid context radius")
  except Exception:
    message = "Thresholded Q-residue optimizer: invalid numeric parameter"
    if not quiet:
      _tq_status(message)
    return None
  if sigma <= 0.0 or grid_spacing <= 0.0 or sample_shell_padding < 0.0:
    message = "Thresholded Q-residue optimizer: sigma/grid spacing must be > 0 and shell padding must be >= 0"
    if not quiet:
      _tq_status(message)
    return None
  if not _tq_valid_map_molecule(map_id):
    message = f"Thresholded Q-residue optimizer: invalid map #{map_id}"
    if not quiet:
      _tq_status(message)
    return None
  if not _tq_valid_model_molecule(mol_id):
    message = f"Thresholded Q-residue optimizer: invalid model molecule #{mol_id}"
    if not quiet:
      _tq_status(message)
    return None
  try:
    current_contour = float(get_contour_level_absolute(map_id))
  except Exception:
    current_contour = 0.0
  try:
    current_contour_sigma = float(get_contour_level_in_sigma(map_id))
  except Exception:
    current_contour_sigma = None
  map_sigma = _tq_map_sigma(map_id)

  if contour_min is None and contour_max is None and map_sigma is not None:
    if contour_min_sigma is None:
      contour_min_sigma = THRESHOLDED_Q_SWEEP_MIN_SIGMA
    if contour_max_sigma is None:
      contour_max_sigma = THRESHOLDED_Q_SWEEP_MAX_SIGMA
    contour_min = float(contour_min_sigma) * map_sigma
    contour_max = float(contour_max_sigma) * map_sigma
  else:
    if contour_min is None:
      contour_min = float(contour_min_sigma) * map_sigma if contour_min_sigma is not None and map_sigma is not None else current_contour
    if contour_max is None:
      contour_max = float(contour_max_sigma) * map_sigma if contour_max_sigma is not None and map_sigma is not None else current_contour
  contour_min = float(contour_min)
  contour_max = float(contour_max)
  if contour_max < contour_min:
    contour_min, contour_max = contour_max, contour_min
  n_steps = max(2, n_steps)

  prepared = _tq_prepare_scored_residues_or_status(
    map_id,
    mol_id,
    residue_specs,
    sigma=sigma,
    ideal_enclosed_mass_percent=ideal_enclosed_mass_percent,
    grid_spacing=grid_spacing,
    sample_shell_padding=sample_shell_padding,
    context_radius=context_radius,
    backbone_only=backbone_only,
    quiet=quiet,
    snapshot=snapshot,
  )
  if prepared is None:
    return None

  contour_levels = [contour_min] if contour_max == contour_min else [
    contour_min + (contour_max - contour_min) * (index / float(n_steps - 1))
    for index in range(n_steps)
  ]

  sweep_results = []
  best_result = None
  for contour_level in contour_levels:
    residue_scores = []
    for prepared_residue in prepared["prepared_residues"]:
      region_score = _tq_residue_region_score_from_sweep_data(
        prepared_residue["region_sweep_data"],
        contour_level,
      )
      residue_scores.append(region_score["score"])
    mean_score = sum(residue_scores) / float(len(residue_scores)) if residue_scores else 0.0
    sweep_result = {
      "contour_level": contour_level,
      "score": mean_score,
      "n_residues": len(residue_scores),
    }
    if map_sigma is not None and map_sigma > 0.0:
      sweep_result["contour_sigma"] = contour_level / map_sigma
    sweep_results.append(sweep_result)
    if best_result is None:
      best_result = sweep_result
    elif mean_score > best_result["score"] + 1.0e-9:
      best_result = sweep_result
    elif abs(mean_score - best_result["score"]) <= 1.0e-9 and contour_level > best_result["contour_level"]:
      best_result = sweep_result

  result = {
    "map_id": map_id,
    "mol_id": mol_id,
    "current_contour": current_contour,
    "current_contour_sigma": current_contour_sigma,
    "map_sigma": map_sigma,
    "best_contour_level": best_result["contour_level"],
    "best_score": best_result["score"],
    "sweep_results": sweep_results,
    "residue_specs": prepared["score_residue_specs"],
    "support_radius": prepared["support_radius"],
    "sample_radius": prepared["sample_radius"],
    "ideal_enclosed_mass_percent": prepared["ideal_enclosed_mass_percent"],
  }
  if map_sigma is not None and map_sigma > 0.0:
    result["best_contour_sigma"] = result["best_contour_level"] / map_sigma

  if not quiet:
    if "best_contour_sigma" in result:
      _tq_status(
        "Thresholded Q-residue local optimum: level {0:.4f}, {1:.2f} sigma (score {2:.3f}) for {3} residue(s) in {4}".format(
          result["best_contour_level"],
          result["best_contour_sigma"],
          result["best_score"],
          len(result["residue_specs"]),
          _molecule_id_name_label(mol_id),
        )
      )
    else:
      _tq_status(
        "Thresholded Q-residue local optimum: level {0:.4f} (score {1:.3f}) for {2} residue(s) in {3}".format(
          result["best_contour_level"],
          result["best_score"],
          len(result["residue_specs"]),
          _molecule_id_name_label(mol_id),
        )
      )

  if apply_contour:
    try:
      set_contour_level_absolute(map_id, result["best_contour_level"])
      _tq_post_map_level_status(map_id, "set to")
    except Exception as error:
      _tq_status(f"Thresholded Q-residue optimizer: failed to apply contour ({error!r})")
  return result


def optimize_local_threshold_by_thresholded_q_current_view(
    map_id=None,
    mol_id=None,
    residue_specs=None,
    radius=THRESHOLDED_Q_LOCAL_RADIUS,
    max_residues=THRESHOLDED_Q_LOCAL_MAX_RESIDUES,
    apply_contour=True,
    **kwargs,
):
  map_id = _tq_map_id_or_default(map_id)
  try:
    radius = float(radius)
    max_residues = int(max_residues)
  except Exception:
    _tq_status("Thresholded Q-residue optimizer: invalid radius/max_residues")
    return None
  if not math.isfinite(radius) or radius <= 0.0:
    _tq_status("Thresholded Q-residue optimizer: radius must be > 0")
    return None
  if max_residues <= 0:
    _tq_status("Thresholded Q-residue optimizer: max_residues must be > 0")
    return None
  if residue_specs is None:
    target = _tq_active_residue_target()
    if target is None:
      _tq_status("Thresholded Q-residue optimizer: no active residue")
      return None
    mol_id = target[0]
    residue_specs = [(target[1], target[2], target[3])]
  elif mol_id is None:
    target = _tq_active_residue_target()
    if target is not None:
      mol_id = target[0]
  if mol_id is None:
    _tq_status("Thresholded Q-residue optimizer: no target molecule")
    return None

  try:
    snapshot = _model_coordinate_snapshot(mol_id)
    score_residue_specs = _tq_residue_specs_near_residue_centres(
      mol_id, residue_specs, radius=radius, max_residues=max_residues, snapshot=snapshot)
  except (RuntimeError, ValueError, TypeError) as error:
    _tq_status(f"Thresholded Q-residue optimizer: calculation aborted. {error}")
    return None
  if not score_residue_specs:
    _tq_status("Thresholded Q-residue optimizer: no local residues to score")
    return None
  context_radius = kwargs.pop("context_radius", radius + THRESHOLDED_Q_CONTEXT_RADIUS_PADDING)
  if context_radius is None:
    context_radius = radius + THRESHOLDED_Q_CONTEXT_RADIUS_PADDING
  try:
    context_radius = float(context_radius)
    if not math.isfinite(context_radius) or context_radius <= 0:
      raise ValueError("context radius must be finite and positive")
  except (ValueError, TypeError) as error:
    _tq_status(f"Thresholded Q-residue optimizer: {error}")
    return None
  return optimize_local_threshold_by_thresholded_q(
    map_id,
    mol_id,
    score_residue_specs,
    context_radius=max(radius, context_radius),
    apply_contour=apply_contour,
    snapshot=snapshot,
    **kwargs,
  )


def _step_map_sigma(mol_id, delta):
  """Adjust contour sigma in coarse 0.1 steps within the usual trimmings range."""
  current_level = get_contour_level_in_sigma(mol_id)
  if 0.1 <= current_level <= 10.0:
    new_level = current_level + delta
  elif current_level < 0.1:
    new_level = 0.1
  else:
    new_level = 10.0
  set_contour_level_in_sigma(mol_id, new_level)
  _post_map_level_status(mol_id, "set to")


def step_map_coarse_up(mol_id):
  _step_map_sigma(mol_id, 0.1)


def step_map_coarse_down(mol_id):
  _step_map_sigma(mol_id, -0.1)


def set_current_map_sigma(level):
  map_id = _scrollable_map_or_status()
  if map_id is None:
    return None
  set_contour_level_in_sigma(map_id, level)
  _post_map_level_status(map_id, "set to")


def step_current_map_coarse_up():
  map_id = _scrollable_map_or_status()
  if map_id is None:
    return None
  step_map_coarse_up(map_id)


def step_current_map_coarse_down():
  map_id = _scrollable_map_or_status()
  if map_id is None:
    return None
  step_map_coarse_down(map_id)


def _map_brightness_scale_would_clip(map_id, scale_factor):
  """Return True if a brighten/darken step would trigger Coot's colour clamp."""
  try:
    current_colour = map_colour_components_py(map_id)
  except Exception:
    return False
  if not isinstance(current_colour, (list, tuple)):
    return False
  try:
    for component in current_colour:
      proposed = float(component) * float(scale_factor)
      if proposed < MAP_BRIGHTNESS_MIN_COMPONENT or proposed > MAP_BRIGHTNESS_MAX_COMPONENT:
        return True
  except Exception:
    return False
  return False


def _scale_scrollable_map_brightness(scale_factor, status_message, clipped_message):
  """Brighten or darken only the current scrollable map."""
  map_id = _scrollable_map_or_status()
  if map_id is None:
    return None
  if _map_brightness_scale_would_clip(map_id, scale_factor):
    add_status_bar_text(clipped_message)
    return None
  coot_utils.brighten_map(map_id, scale_factor)
  add_status_bar_text(status_message)
  return map_id


def brighten_scrollable_map():
  return _scale_scrollable_map_brightness(
    MAP_BRIGHTEN_SCALE_FACTOR,
    "Brightened current map",
    "Skipped brightening current map to avoid hitting map-colour limits",
  )


def darken_scrollable_map():
  return _scale_scrollable_map_brightness(
    MAP_DARKEN_SCALE_FACTOR,
    "Darkened current map",
    "Skipped darkening current map to avoid hitting map-colour limits",
  )


def start_measure_distance():
  add_status_bar_text("Pick 2 atoms to measure distance")
  do_distance_define()


def _map_looks_em_like(map_id):
  if not is_valid_map_molecule(map_id):
    return False
  try:
    cell = map_cell(map_id)
  except Exception:
    cell = None
  if cell and len(cell) >= 6:
    alpha, beta, gamma = cell[3], cell[4], cell[5]
    if (
      abs(alpha - 90.0) < 0.5
      and abs(beta - 90.0) < 0.5
      and abs(gamma - 90.0) < 0.5
    ):
      return True
  for path in _candidate_map_file_paths(map_id):
    if path.lower().endswith((".mrc", ".map", ".ccp4")):
      return True
  return False


def _candidate_map_file_paths(map_id):
  name = molecule_name(map_id)
  if not name:
    return []
  candidates = [name]
  if not os.path.isabs(name):
    candidates.append(os.path.join(os.getcwd(), name))
  return [path for path in candidates if os.path.isfile(path)]


def _lowpass_parameters(resolution, taper_fraction, padding):
  values = tuple(float(value) for value in (resolution, taper_fraction, padding))
  resolution, taper_fraction, padding = values
  if not all(math.isfinite(value) for value in values):
    raise ValueError("Filter settings must be finite numbers.")
  if resolution <= 0:
    raise ValueError("Resolution cutoff must be positive (Angstroms).")
  if not 0 <= taper_fraction < 1:
    raise ValueError("Cosine rolloff must be between 0 and 100% (exclusive).")
  if padding < 0:
    raise ValueError("Crop padding cannot be negative.")
  return values


def _lowpass_export(map_id, model_id, directory, padding):
  """Coot exports stay on the GUI thread; filter the current map, not a stale disk copy."""
  if not coot.is_valid_map_molecule(map_id):
    raise ValueError("Choose an open map to filter.")
  path = os.path.join(directory, "input.map")
  if model_id is None:
    result = coot.export_map(map_id, path)
  else:
    if not coot.is_valid_model_molecule(model_id):
      raise ValueError("Choose an open model for cropping.")
    np = _tq_numpy_module()
    snapshot = _model_coordinate_snapshot(model_id)
    points = np.asarray([atom[2] for record in snapshot.values() for atom in record["atoms"]], dtype=float)
    if not points.size or not np.isfinite(points).all():
      raise ValueError("The crop model contains no valid atom coordinates.")
    low, high = points.min(axis=0), points.max(axis=0)
    centre = (low+high)*0.5
    radius = float((high-low).max()*0.5+padding)
    if radius <= 0:
      raise ValueError("Crop radius must be positive; increase the padding.")
    result = coot.export_map_fragment(map_id, *map(float, centre), radius, path)
  if result != 1 or not os.path.isfile(path) or os.path.getsize(path) < 1024:
    raise RuntimeError("Coot could not export the map for filtering.")
  return dict(path=path, name=coot.molecule_name(map_id),
              difference=bool(coot.map_is_difference_map(map_id)))


def _lowpass_filter_file(input_path, output_path, resolution, taper_fraction, progress=None):
  """Pure file/FFT work: safe in a worker, no Coot or GTK calls.

  Preserve the exported box and its CCP4 placement. In particular, setup()
  would expand a fragment to the full cell, defeating cropping and changing it.
  """
  import numpy as np
  if progress is not None:
    progress("Reading map grid")
  ccp4 = gemmi.read_ccp4_map(input_path, setup=False)
  # Gemmi stores X/columns contiguously (Fortran order). Reverse the view so
  # NumPy's real FFT operates along its contiguous last axis, without copying.
  data = np.asarray(ccp4.grid).transpose(2, 1, 0)
  if not np.isfinite(data).all():
    raise ValueError("Map contains NaN or infinite voxel values.")
  axes = [ccp4.header_i32(word)-1 for word in (19, 18, 17)]
  sampling = np.asarray([ccp4.header_i32(word) for word in (8, 9, 10)], dtype=float)
  if sorted(axes) != [0, 1, 2] or np.any(sampling <= 0):
    raise ValueError("Map has invalid axis order or grid sampling.")
  if ccp4.has_skew_transformation():
    raise ValueError("Maps with a CCP4 skew transformation are not supported.")
  # Storage axes need not be XYZ. A fragment's FFT box is smaller than its
  # unit cell: derive its basis from voxel spacing, not the full cell lengths.
  direct = np.asarray(ccp4.grid.unit_cell.orth.mat.tolist(), dtype=float)
  box = direct[:, axes]*(np.asarray(data.shape)/sampling[axes])[None, :]
  inverse = np.linalg.inv(box)
  metric = inverse @ inverse.T
  if not np.isfinite(metric).all():
    raise ValueError("Map has an invalid unit cell.")
  nu, nv, nw = data.shape
  h = np.fft.fftfreq(nu)*nu
  k = np.fft.fftfreq(nv)*nv
  l = np.fft.rfftfreq(nw)*nw
  base = (metric[1, 1]*k[:, None]**2 + metric[2, 2]*l[None, :]**2 +
          2*metric[1, 2]*k[:, None]*l[None, :])
  cutoff = 1.0/resolution
  dimensions = " x ".join(map(str, data.shape))
  if progress is not None:
    progress("Forward FFT: " + dimensions)
  spectrum = np.fft.rfftn(data)
  # Bounded slabs avoid thousands of GIL handoffs to Coot's busy GTK thread.
  # Keep float64 cutoff arithmetic and cap the weight workspace at 16 MiB
  # (or one plane if larger); never allocate a full frequency-coordinate grid.
  planes = max(1, min(nu, (16*1024**2)//max(1, 8*nv*len(l))))
  for start in range(0, nu, planes):
    if progress is not None:
      progress(f"Filtering frequencies: {start}/{nu} planes")
    hi = h[start:start+planes]
    weight = np.empty((len(hi), nv, len(l)), dtype=np.float64)
    np.add(base[None, :, :], (metric[0, 0]*hi**2)[:, None, None], out=weight)
    if metric[0, 1] != 0:
      weight += (2*metric[0, 1]*hi[:, None]*k[None, :])[:, :, None]
    if metric[0, 2] != 0:
      weight += (2*metric[0, 2]*hi[:, None]*l[None, :])[:, None, :]
    np.maximum(weight, 0, out=weight)
    if taper_fraction == 0:
      weight = weight < cutoff*cutoff
    else:
      np.sqrt(weight, out=weight)
      weight -= cutoff
      weight /= -cutoff*taper_fraction
      np.clip(weight, 0, 1, out=weight)
      weight *= np.pi
      np.cos(weight, out=weight)
      weight *= -0.5
      weight += 0.5
    spectrum[start:start+len(hi)] *= weight
    del weight
  if progress is not None:
    progress("Inverse FFT: " + dimensions)
  filtered = np.fft.irfftn(spectrum, s=data.shape, axes=(0, 1, 2))
  del spectrum
  if not np.isfinite(filtered).all():
    raise ValueError("Filtering produced non-finite density values.")
  data[:] = filtered
  del filtered
  if progress is not None:
    progress("Writing filtered map")
  # update_ccp4_header() requires setup() for partial maps. Update only mode
  # and density statistics; retain sampling, starts, origin, axes and symmetry.
  ccp4.set_header_i32(4, 2)
  for word, value in ((20, data.min()), (21, data.max()),
                      (22, data.mean(dtype=np.float64)), (55, data.std(dtype=np.float64))):
    ccp4.set_header_float(word, float(value))
  ccp4.write_ccp4_map(output_path)
  return tuple(ccp4.grid.shape)


def _lowpass_import(path, source, resolution):
  existing = set(map_molecule_list())
  reader = getattr(coot, "handle_read_ccp4_map", None) or coot.read_ccp4_map
  result = reader(path, int(source["difference"]))
  if result in existing or result is None or not coot.is_valid_map_molecule(result):
    raise RuntimeError("Coot could not load the filtered map.")
  try:
    coot.set_molecule_name(result, f"{source['name']} | low-pass {resolution:g} A")
  except Exception:
    coot.close_molecule(result)
    raise
  add_status_bar_text(f"Created low-pass map #{result} ({resolution:g} A); source map unchanged")
  return result


def _lowpass_worker_main():
  """Standalone numerical worker; deliberately never import Coot or GTK."""
  import json
  import sys
  config = json.loads(sys.argv[1])
  def publish(value):
    print(json.dumps(value), flush=True)
  try:
    if list(sys.version_info[:2]) != config["version"]:
      raise ImportError("Standalone Python does not match Coot's Python version.")
    sys.path[:0] = config["module_roots"]
    global gemmi
    import gemmi
    import numpy
  except Exception as error:
    publish(dict(unavailable=str(error)))
    return
  try:
    shape = _lowpass_filter_file(config["input"], config["output"], config["resolution"], config["taper"])
    publish(dict(shape=shape))
  except Exception as error:
    publish(dict(error=str(error)))


def _lowpass_worker_source():
  """Cache source on the GUI thread rather than inspecting a large script off-thread."""
  import inspect
  functions = (_lowpass_filter_file, _lowpass_worker_main)
  cached = globals().get("_LOWPASS_WORKER_SOURCE_CACHE")
  if cached is not None and cached[0] == functions:
    return cached[1]
  source = "\n".join(inspect.getsource(f) for f in functions)+"\n_lowpass_worker_main()\n"
  globals()["_LOWPASS_WORKER_SOURCE_CACHE"] = (functions, source)
  return source


def _lowpass_filter_background(input_path, output_path, resolution, taper_fraction, progress=None):
  """Isolate FFT work from Coot's GIL; fall back if no usable Python is available."""
  import json
  import os
  from pathlib import Path
  import subprocess
  import sys
  import threading
  def local():
    if progress is not None:
      progress("Using in-process FFT")
    return _lowpass_filter_file(input_path, output_path, resolution, taper_fraction, progress=progress)
  try:
    python = _global_fit_worker_python()
    source = _lowpass_worker_source()
  except (OSError, TypeError, RuntimeError):
    return local()
  roots = []
  for module in (gemmi, _tq_numpy_module()):
    filename = getattr(module, "__file__", None)
    if filename:
      # Keep symlinks: resolving every path component adds many GIL handoffs
      # in a Coot worker, and imports work equally well through these paths.
      path = Path(os.path.abspath(filename))
      root = str(path.parent.parent if path.name == "__init__.py" else path.parent)
      if root not in roots:
        roots.append(root)
  env = dict(os.environ)
  for name in ("PYTHONHOME", "PYTHONPATH", "PYTHONSTARTUP", "DYLD_INSERT_LIBRARIES"):
    env.pop(name, None)
  for name in ("OPENBLAS_NUM_THREADS", "OMP_NUM_THREADS", "MKL_NUM_THREADS", "VECLIB_MAXIMUM_THREADS"):
    env[name] = "1"
  config = dict(input=os.path.abspath(input_path), output=os.path.abspath(output_path),
                resolution=resolution, taper=taper_fraction,
                version=list(sys.version_info[:2]), module_roots=roots)
  try:
    process = subprocess.Popen([python, "-I", "-B", "-u", "-c", source, json.dumps(config)],
                               stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                               stderr=subprocess.STDOUT, env=env)
  except OSError:
    return local()
  # One blocking pipe read releases the GIL until completion. Polling or
  # exchanging progress files would repeatedly compete with Coot's draw calls.
  deadline = threading.Timer(1800., process.kill)
  deadline.daemon = True
  deadline.start()
  try:
    if progress is not None:
      progress("Isolated FFT: reading, filtering and writing map")
    output = process.communicate()[0].decode("utf-8", errors="replace")
  finally:
    deadline.cancel()
    if process.poll() is None:
      process.terminate()
      try:
        process.wait(timeout=2.)
      except subprocess.TimeoutExpired:
        process.kill()
    process.wait()
    process.stdout.close()
  try:
    result = json.loads(output)
  except ValueError:
    raise RuntimeError("Low-pass FFT worker failed: "+output[-2000:])
  if not process.returncode and "unavailable" in result:
    return local()
  if process.returncode or "shape" not in result:
    raise RuntimeError(result.get("error", "Low-pass FFT worker did not finish."))
  return tuple(result["shape"])


def lowpass_filter_map(imol_map, resolution=4.0, taper_fraction=0.10, model_imol=None, padding=20.0):
  """Create a low-pass map (console API); optional model-centred crop with padding."""
  resolution, taper_fraction, padding = _lowpass_parameters(resolution, taper_fraction, padding)
  if gemmi is None or _tq_numpy_module() is None:
    raise RuntimeError("Low-pass filtering requires Gemmi and NumPy in Coot's Python.")
  started = time.perf_counter()
  with tempfile.TemporaryDirectory(prefix="coot-lowpass-") as directory:
    source = _lowpass_export(imol_map, model_imol, directory, padding)
    exported = time.perf_counter()
    output = os.path.join(directory, "filtered.map")
    shape = _lowpass_filter_file(source["path"], output, resolution, taper_fraction)
    filtered = time.perf_counter()
    result = _lowpass_import(output, source, resolution)
    print(f"Low-pass {shape}: export {exported-started:.2f}s, filter {filtered-exported:.2f}s, load {time.perf_counter()-filtered:.2f}s")
    return result


def lowpass_filter_map_dialog():
  """Filter a chosen map with an isolated FFT and a background-thread fallback."""
  if gemmi is None or _tq_numpy_module() is None:
    info_dialog("Low-pass filtering requires Gemmi and NumPy in Coot's embedded Python.")
    return None
  maps = list(map_molecule_list())
  if not maps:
    add_status_bar_text("Open a map before using low-pass filtering.")
    return None
  glib = _coot_gui_repository_module("GLib")
  if glib is None:
    info_dialog("The low-pass filter dialog requires GLib.")
    return None
  window = Gtk.Window(title="Low-pass filter map")
  window.set_default_size(440, -1)
  box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=10)
  for edge in ("start", "end", "top", "bottom"):
    getattr(box, "set_margin_"+edge)(12)
  window.set_child(box)
  grid = Gtk.Grid(column_spacing=10, row_spacing=8)
  box.append(grid)
  map_choice = Gtk.ComboBoxText()
  for number in maps:
    map_choice.append(str(number), f"#{number}: {coot.molecule_name(number)}")
  current = coot.scroll_wheel_map()
  map_choice.set_active(maps.index(current) if current in maps else 0)
  map_choice.set_hexpand(True)
  cutoff, rolloff, padding = Gtk.Entry(), Gtk.Entry(), Gtk.Entry()
  for widget, value in ((cutoff, "4"), (rolloff, "10"), (padding, "20")):
    widget.set_text(value)
    widget.set_width_chars(6)
    widget.set_max_width_chars(6)
  for row, (label, widget) in enumerate((("Map", map_choice), ("Resolution cutoff (A)", cutoff),
                                         ("Cosine rolloff (%)", rolloff))):
    text = Gtk.Label(label=label)
    text.set_xalign(0)
    grid.attach(text, 0, row, 1, 1)
    grid.attach(widget, 1, row, 1, 1)
  rolloff.set_tooltip_text("Width of the cosine rolloff below the cutoff, as a percentage of cutoff frequency. 0 = hard cutoff.")
  crop = Gtk.CheckButton(label="Crop around model")
  box.append(crop)
  model_choice = Gtk.ComboBoxText()
  models = list(model_molecule_list())
  for number in models:
    model_choice.append(str(number), f"#{number}: {coot.molecule_name(number)}")
  active = coot.active_residue_py()
  model_choice.set_active(models.index(active[0]) if active and active[0] in models else (0 if models else -1))
  crop.set_sensitive(bool(models))
  crop_row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
  model_choice.set_hexpand(True)
  for widget in (model_choice, Gtk.Label(label="Padding (A)"), padding):
    crop_row.append(widget)
  crop_row.set_sensitive(False)
  crop.connect("toggled", lambda widget: crop_row.set_sensitive(widget.get_active()))
  box.append(crop_row)
  status = Gtk.Label(label="Creates a new map; the source map is unchanged.")
  status.set_xalign(0)
  status.set_wrap(True)
  box.append(status)
  spinner = Gtk.Spinner()
  box.append(spinner)
  buttons = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
  apply, close = Gtk.Button(label="Filter"), Gtk.Button(label="Close")
  buttons.append(apply)
  buttons.append(close)
  box.append(buttons)
  state = dict(closed=False, running=False, finished=None, owner=None, result=None)
  def busy(running):
    state["running"] = running
    for widget in (grid, crop, crop_row, apply):
      widget.set_sensitive(not running)
    crop.set_sensitive(not running and bool(models))
    crop_row.set_sensitive(not running and crop.get_active())
    spinner.start() if running else spinner.stop()
  def cleanup():
    if state["owner"] is not None:
      state["owner"].cleanup()
      state["owner"] = None
  def poll():
    finished = state["finished"]
    if finished is None:
      if not state["closed"]:
        status.set_text(f"{state.get('phase', 'Filtering map')}... {time.perf_counter()-state['started']:.1f}s")
      return True
    try:
      if not state["closed"]:
        shape, error = finished
        if error is not None:
          raise RuntimeError(error)
        status.set_text("Loading filtered map...")
        loading = time.perf_counter()
        state["result"] = _lowpass_import(state["output"], state["source"], state["resolution"])
        state["timings"]["load"] = time.perf_counter()-loading
        state["timings"]["total"] = time.perf_counter()-state["started"]
        print("Low-pass timing: " + ", ".join(f"{key} {value:.2f}s" for key, value in state["timings"].items()))
        status.set_text(f"Created map #{state['result']} | {state['resolution']:g} A | " +
                        " x ".join(map(str, shape)) + f" | {state['timings']['total']:.2f}s")
    except Exception as error:
      status.set_text(f"Filtering failed: {error}")
    finally:
      cleanup()
      if not state["closed"]:
        busy(False)
    return False
  def start_worker():
    if state["closed"]:
      busy(False)
      return False
    try:
      try:
        _lowpass_worker_source()
      except (OSError, TypeError, RuntimeError):
        pass  # The background helper can use the in-process fallback.
      state["owner"] = tempfile.TemporaryDirectory(prefix="coot-lowpass-")
      directory = state["owner"].name
      export_started = time.perf_counter()
      source = _lowpass_export(state["map"], state["model"], directory, state["padding"])
      state["timings"]["export"] = time.perf_counter()-export_started
      output = os.path.join(directory, "filtered.map")
      state.update(source=source, output=output)
      status.set_text("Filtering map... (you can continue using Coot)")
      def worker():
        try:
          started = time.perf_counter()
          shape = _lowpass_filter_background(source["path"], output, state["resolution"], state["taper"],
              progress=lambda message: state.update(phase=message))
          state["timings"]["filter"] = time.perf_counter()-started
          state["finished"] = (shape, None)
        except Exception as error:
          # Do not retain a worker traceback containing large FFT arrays.
          state["finished"] = (None, str(error))
      import threading
      thread = threading.Thread(target=worker, name="coot-lowpass", daemon=True)
      glib.timeout_add(100, poll)
      thread.start()
    except Exception as error:
      cleanup()
      state["finished"] = (None, str(error))
      status.set_text(f"Filtering failed: {error}")
      busy(False)
    return False
  def run(*_args):
    if state["running"]:
      return
    try:
      resolution, taper, pad = _lowpass_parameters(cutoff.get_text(), float(rolloff.get_text())/100, padding.get_text())
      state.update(map=int(map_choice.get_active_id()),
                   model=int(model_choice.get_active_id()) if crop.get_active() else None,
                   resolution=resolution, taper=taper, padding=pad, finished=None, result=None,
                   started=time.perf_counter(), phase="Exporting map", timings={})
      busy(True)
      status.set_text("Exporting current map...")
      glib.idle_add(start_worker)
    except Exception as error:
      status.set_text(str(error))
      busy(False)
  def closed(*_args):
    # A running FFT cannot be interrupted; discard its result and clean up
    # when it finishes. Never delete files while the worker is using them.
    state["closed"] = True
    return False
  apply.connect("clicked", run)
  close.connect("clicked", lambda *_: window.close())
  window.connect("close-request", closed)
  window.lowpass_widgets = dict(map=map_choice, cutoff=cutoff, rolloff=rolloff, crop=crop,
                               model=model_choice, padding=padding, apply=apply, status=status, state=state)
  window.present()
  return window


def _global_multimap_schedule(start=5., finest=4., repeats=1):
  start, finest = float(start), float(finest)
  if not all(math.isfinite(v) and .5 <= v <= 200 for v in (start, finest)) or start < finest:
    raise ValueError("Use resolutions between 0.5 and 200 A, with start >= finest filtered resolution.")
  if isinstance(repeats, bool) or float(repeats) != int(float(repeats)) or not 1 <= int(float(repeats)) <= 10:
    raise ValueError("Use 1-10 passes per stage.")
  levels = [start]
  while levels[-1] > finest*(1+1e-6):
    value = levels[-1]*2/3
    levels.append(finest if value <= 1.25*finest else value)
  return [resolution for resolution in (*levels, None) for _ in range(int(float(repeats)))]


def _global_multimap_compact_crop(input_path, output_path):
  """Compact orthogonal P1 crops without moving the model or interpolating voxels.

  Keep absolute grid starts: Clipper wraps them into the smaller P1 cell, so
  density still samples correctly in the model's original Cartesian frame.
  Generous padding separates the model from the new periodic boundary.
  """
  import numpy as np
  crop = gemmi.read_ccp4_map(input_path, setup=False)
  cell = crop.grid.unit_cell
  sampling = np.array([crop.header_i32(i) for i in (8, 9, 10)], dtype=float)
  axes = np.array([crop.header_i32(i)-1 for i in (17, 18, 19)])
  if sorted(axes.tolist()) != [0, 1, 2]:
    return False
  shape = np.array(crop.grid.shape, dtype=int)[np.argsort(axes)]
  if (crop.header_i32(23) not in (0, 1) or
      any(abs(v-90.) > 1e-5 for v in (cell.alpha, cell.beta, cell.gamma)) or
      any(abs(crop.header_float(i)) > 1e-6 for i in (50, 51, 52)) or crop.has_skew_transformation() or
      (sampling <= 0).any() or not (shape < sampling).any()):
    return False
  lengths = np.array((cell.a, cell.b, cell.c))*shape/sampling
  crop.grid.set_unit_cell(gemmi.UnitCell(*map(float, lengths), 90, 90, 90))
  for word, value in zip((8, 9, 10), shape):
    crop.set_header_i32(word, int(value))
  for word, value in zip((11, 12, 13), lengths):
    crop.set_header_float(word, float(value))
  crop.set_header_i32(23, 1)
  crop.write_ccp4_map(output_path)
  return True


def _global_multimap_identity(snapshot):
  identities = {}
  for spec, record in snapshot.items():
    for atom in record["atoms"]:
      key = (*spec, record["name"], *atom[0])
      if key in identities or len(atom[2]) != 3 or not all(math.isfinite(v) for v in atom[2]):
        raise ValueError("The model has ambiguous atoms or non-finite coordinates.")
      identities[key] = repr(atom[1])
  if not identities:
    raise ValueError("The model has no atoms to refine.")
  return identities


def _global_multimap_snapshot_change(expected, current):
  """Describe actual atom changes, ignoring list order and sub-microangstrom noise."""
  if current == expected:
    return None
  if current.keys() != expected.keys():
    return "the residue list changed"
  if _global_multimap_identity(current) != _global_multimap_identity(expected):
    return "atom identities or properties changed"
  moved, maximum, worst = 0, 0., None
  for spec, before in expected.items():
    if current[spec]["name"] != before["name"]:
      return f"residue {spec} changed type"
    after = {tuple(atom[0]): atom for atom in current[spec]["atoms"]}
    for atom in before["atoms"]:
      observed = after[tuple(atom[0])]
      distance = math.sqrt(_distance_sq(atom[2], observed[2]))
      if distance > 1e-6:
        moved += 1
        if distance > maximum:
          maximum, worst = distance, (*spec, atom[0][0].strip(), atom[0][1])
  if moved:
    return f"{moved} {'atom' if moved == 1 else 'atoms'} moved (maximum {maximum:.6g} A at {worst})"
  return None


def _global_multimap_cleanup(state):
  """Remove only this run's map, after native refinement has released it."""
  errors = []
  temporary = state.get("temporary")
  try:
    if temporary is not None:
      number, name = temporary
      if coot.is_valid_map_molecule(number) and coot.molecule_name(number) == name:
        original = state.get("map")
        if original is not None and coot.is_valid_map_molecule(original):
          if coot.imol_refinement_map() == number:
            coot.set_imol_refinement_map(original)
          if coot.scroll_wheel_map() == number:
            coot.set_scroll_wheel_map(original)
        coot.close_molecule(number)
      state.pop("temporary", None)
  except Exception as error:
    errors.append(f"map {temporary}: {error}")
  owner = state.pop("owner", None)
  if owner is not None:
    try:
      owner.cleanup()
    except Exception as error:
      errors.append(str(error))
  if errors:
    raise RuntimeError("; ".join(errors))


def _global_multimap_refine(state, stage_map, estimate=None):
  """One whole-model native refinement; preserve all original extra restraints."""
  model = state["model"]
  if coot.refinement_already_ongoing_p():
    raise ValueError("Accept/cancel the other active refinement first.")
  previous = (coot.imol_refinement_map(), float(coot.matrix_state()), coot.refinement_immediate_replacement_state())
  attempted = False
  try:
    # Read statistics anew at the model's current coordinates on THIS stage map.
    estimate = estimate or estimate_local_em_map_weight(model, stage_map, apply=False, reference_map_id=state["map"],
                                                       lowpass_resolution=state.get('resolution') or 0.)
    weight = estimate["weight"]*state["multiplier"]
    if not math.isfinite(weight) or weight <= 0:
      raise ValueError("Invalid estimated stage weight.")
    if coot.set_imol_refinement_map(stage_map) != stage_map:
      raise RuntimeError("Coot could not select the stage map.")
    coot.set_matrix(weight)
    if not math.isclose(float(coot.matrix_state()), weight, rel_tol=1e-5):
      raise RuntimeError("Coot did not accept the temporary stage weight.")
    coot.set_refinement_immediate_replacement(1)
    state["phase"] = "refining"
    state["message"] = f"Pass {state['index']+1}/{len(state['schedule'])}: {state['stage_label']} | weight {weight:.4g}"
    state["notify"]()
    with _grouped_model_edit(model):
      attempted = True
      result = coot.refine_residues_py(model, state["specs"])
      if result is False or result is None:
        raise RuntimeError("Coot could not refine the whole model; check dictionaries and residue selection.")
      if coot.refinement_already_ongoing_p():
        accepted = coot.accept_moving_atoms_py()
        if accepted is False or accepted is None:
          raise RuntimeError("Coot could not accept the global refinement.")
    coot.graphics_draw()
  except Exception:
    if attempted and coot.refinement_already_ongoing_p():
      coot.clear_up_moving_atoms()
    raise
  finally:
    errors = []
    for function, args in ((coot.set_refinement_immediate_replacement, (previous[2],)),
                           (coot.set_matrix, (previous[1],)),
                           (coot.set_imol_refinement_map, (previous[0],))):
      try:
        if function is not coot.set_imol_refinement_map or coot.is_valid_map_molecule(previous[0]):
          function(*args)
      except Exception as error:
        errors.append(str(error))
    if errors:
      raise RuntimeError("Could not restore refinement settings: "+"; ".join(errors))
  # Capture the baseline after all of our native finalization/restoration calls,
  # not before them. Never refresh it on a later tick, which could hide edits.
  snapshot = _model_coordinate_snapshot(model)
  if _global_multimap_identity(snapshot) != state["identity"]:
    raise RuntimeError("Refinement unexpectedly changed atom identities/properties. Use Coot Undo to recover.")
  state["expected"] = snapshot
  state["history"].append(dict(resolution=state["resolution"], map=stage_map, weight=weight,
      sigma=estimate["sigma"], reference_sigma=estimate["reference_sigma"],
      baseline_weight=estimate["baseline_weight"], local_factor=estimate["local_factor"],
      resolution_factor=estimate.get('resolution_factor', 1.), effective_resolution=estimate.get('effective_resolution'),
      samples=estimate["samples"], cropped=state["cropped"], result=result))
  print(f"Global multimap: {state['stage_label']} | weight {weight:.6g} | original-map baseline {estimate['baseline_weight']:.6g} x contrast {estimate['local_factor']:.4g} | local sigma {estimate['sigma']:.6g}, original {estimate['reference_sigma']:.6g} | {estimate['samples']} samples")


def _global_multimap_timed_restore(state):
  native = state['native']
  errors = []
  for function, args in ((coot.set_refinement_immediate_replacement, (native['previous'][2],)),
                         (coot.set_matrix, (native['previous'][1],)),
                         (coot.set_imol_refinement_map, (native['previous'][0],))):
    try:
      if function is not coot.set_imol_refinement_map or coot.is_valid_map_molecule(args[0]):
        function(*args)
    except Exception as error:
      errors.append(str(error))
  state['native'] = None
  if errors:
    raise RuntimeError('Could not restore timed refinement settings: '+'; '.join(errors))


def _global_multimap_timed_finish(state, accept=True):
  """Stop and accept in one GUI callback, before Coot's pending cancel cleanup runs."""
  native = state['native']
  result = None
  try:
    if not coot.refinement_already_ongoing_p():
      if accept:
        raise RuntimeError('The native refinement was accepted/cancelled outside this widget.')
    else:
      coot.stop_refinement_internal()
      if accept:
        enabled = coot.backup_state(state['model'])
        try:
          coot.turn_off_backup(state['model'])
          result = coot.accept_moving_atoms_py()
          if result is False or result is None:
            raise RuntimeError('Coot could not accept the timed refinement.')
        finally:
          (coot.turn_on_backup if enabled else coot.turn_off_backup)(state['model'])
          _mark_model_changed(state['model'])
      else:
        coot.clear_up_moving_atoms()
    coot.graphics_draw()
  finally:
    _global_multimap_timed_restore(state)
  if not accept:
    return
  snapshot = _model_coordinate_snapshot(state['model'])
  if _global_multimap_identity(snapshot) != state['identity']:
    raise RuntimeError('Timed refinement changed atom identities/properties. Use Coot Undo to recover.')
  state['expected'] = snapshot
  progress = result[1] if isinstance(result, (list, tuple)) and len(result) > 1 else None
  termination = ('converged' if progress == 0 else 'no progress' if progress == 27 else
                 'stopped' if state['stop'] or state['closed'] else 'time limit')
  estimate = native['estimate']
  elapsed = time.monotonic()-native['started']
  state['history'].append(dict(resolution=state['resolution'], map=native['map'], weight=native['weight'],
      sigma=estimate['sigma'], reference_sigma=estimate['reference_sigma'],
      baseline_weight=estimate['baseline_weight'], local_factor=estimate['local_factor'],
      resolution_factor=estimate.get('resolution_factor', 1.), effective_resolution=estimate.get('effective_resolution'),
      samples=estimate['samples'], cropped=state['cropped'], result=result,
      elapsed=elapsed, termination=termination))
  print(f"Global multimap: {state['stage_label']} | weight {native['weight']:.6g} | {elapsed:.2f}s | {termination}")


def _global_multimap_timed_start(state, stage_map, estimate):
  if coot.refinement_already_ongoing_p():
    raise ValueError('Accept/cancel the other active refinement first.')
  weight = estimate['weight']*state['multiplier']
  if not math.isfinite(weight) or weight <= 0:
    raise ValueError('Invalid estimated stage weight.')
  state['native'] = dict(map=stage_map, estimate=estimate, weight=weight, started=time.monotonic(),
      previous=(coot.imol_refinement_map(), float(coot.matrix_state()), coot.refinement_immediate_replacement_state()))
  try:
    if coot.set_imol_refinement_map(stage_map) != stage_map:
      raise RuntimeError('Coot could not select the timed stage map.')
    coot.set_matrix(weight)
    coot.set_refinement_immediate_replacement(0)
    # Restore backups immediately after launching; do not leave them disabled
    # while the GUI is interactive. Acceptance uses the same single checkpoint.
    with _grouped_model_edit(state['model']):
      result = coot.refine_residues_py(state['model'], state['specs'])
      if result is False or result is None or not coot.refinement_already_ongoing_p():
        raise RuntimeError('Coot could not launch nonblocking refinement.')
    state['phase'] = 'refining'
  except Exception:
    _global_multimap_timed_finish(state, accept=False)
    raise


def start_global_multimap_refinement(model, map_id, start=5., finest=4., repeats=1,
                                    padding=30., final_crop=True, multiplier=1., on_update=None, max_seconds=20.):
  """In-place global passes with background FFTs and per-pass temporary weights.

  Timed passes use native intermediate atoms and GUI-thread stop/accept.
  A zero time budget keeps the original synchronous convergence-driven path.
  """
  import threading
  glib = _coot_gui_repository_module("GLib")
  if glib is None or gemmi is None or _tq_numpy_module() is None:
    raise ValueError("Global multimap refinement requires GLib, Gemmi and NumPy in Coot.")
  running = globals().get("_GLOBAL_MULTIMAP_JOB")
  if running is not None and running["running"]:
    raise ValueError("Another global multimap run is still active.")
  if coot.refinement_already_ongoing_p():
    raise ValueError("Accept/cancel intermediate atoms first.")
  if not coot.is_valid_model_molecule(model) or not coot.is_valid_map_molecule(map_id):
    raise ValueError("Choose an available model and refinement map.")
  if coot.map_is_difference_map(map_id):
    raise ValueError("Choose a reconstruction, not a difference map.")
  schedule = _global_multimap_schedule(start, finest, repeats)
  max_seconds = float(max_seconds)
  if not math.isfinite(max_seconds) or not 0 <= max_seconds <= 86400:
    raise ValueError('Use a stage time budget between 0 and 86400 seconds (0 = unlimited).')
  if max_seconds and not all(callable(getattr(coot, name, None)) for name in
      ('stop_refinement_internal', 'accept_moving_atoms_py', 'backup_state', 'turn_off_backup', 'turn_on_backup')):
    raise ValueError('Timed refinement is unavailable in this build. Set maximum seconds to 0 for unlimited refinement.')
  try:
    _lowpass_worker_source()
  except (OSError, TypeError, RuntimeError):
    pass
  padding, multiplier = float(padding), float(multiplier)
  if not math.isfinite(padding) or padding < 8 or not math.isfinite(multiplier) or not 0 < multiplier <= 10:
    raise ValueError("Use crop padding >= 8 A and a weight multiplier > 0 and <= 10.")
  snapshot = _model_coordinate_snapshot(model)
  identity = _global_multimap_identity(snapshot)
  points = [a[2] for r in snapshot.values() for a in r["atoms"]]
  probes = points[::max(1, len(points)//64)][:64]
  fingerprint = _register_map_fingerprint(map_id, probes)
  state = dict(model=model, model_name=coot.molecule_name(model), map=map_id,
      schedule=schedule, index=0, history=[], running=True, paused=False, stop=False, closed=False,
      expected=snapshot, identity=identity, specs=[list(s) for s, r in snapshot.items() if r["atoms"]],
      phase="prepare", message="Preparing global refinement...", padding=padding,
      final_crop=bool(final_crop), multiplier=multiplier, probes=probes, fingerprint=fingerprint,
      worker=None, prepared=None, source=None, native=None, max_seconds=max_seconds)
  def notify():
    if on_update is not None and not state["closed"]:
      try:
        on_update(state)
      except Exception as error:
        print("Global multimap GUI update failed:", error)
  state["notify"] = notify
  def finish(message, error=None):
    try:
      if state.get('native') is not None:
        _global_multimap_timed_finish(state, accept=False)
      _global_multimap_cleanup(state)
    except Exception as cleanup_error:
      message += " Cleanup failed: "+str(cleanup_error)
      error = error or str(cleanup_error)
    state.update(running=False, phase="error" if error else "finished", message=message, error=error)
    notify()
    return False
  def check():
    if not coot.is_valid_model_molecule(model):
      raise ValueError("The model was closed; completed passes remain.")
    if coot.molecule_name(model) != state["model_name"]:
      raise ValueError(f"The model name changed from {state['model_name']!r} to {coot.molecule_name(model)!r}; completed passes remain.")
    change = _global_multimap_snapshot_change(state["expected"], _model_coordinate_snapshot(model))
    if change:
      print(f"Global multimap safety check: pass {state['index']+1}, phase {state['phase']}: {change}")
      raise ValueError(f"The model no longer matches the last completed pass: {change}; completed passes remain.")
    if _register_map_fingerprint(map_id, probes) != fingerprint:
      raise ValueError("The original map changed or was closed; completed passes remain.")
    module = getattr(coot, "_trimmings_multimap_refinement", None)
    if module is not None and getattr(module, "_MULTIMAP_RUNNING", None) is not None:
      raise ValueError("Stop the other multimap job first.")
  def tick():
    try:
      worker = state["worker"]
      if worker is not None:
        if worker.is_alive():
          return True
        state["worker"] = None
      if state.get('native') is not None:
        check()
        elapsed = time.monotonic()-state['native']['started']
        if not state['stop'] and not state['closed'] and elapsed < state['max_seconds']:
          state['message'] = (f"Pass {state['index']+1}/{len(schedule)}: {state['stage_label']} | "
                              f"{elapsed:.1f}/{state['max_seconds']:g}s | weight {state['native']['weight']:.4g}")
          notify()
          return True
        _global_multimap_timed_finish(state)
        _global_multimap_cleanup(state)
        state['index'] += 1
        state.update(prepared=None, phase='settling', message=f"Completed {state['index']}/{len(schedule)} passes.")
        notify()
        return True  # Let Coot drain its pending intermediate-atoms callbacks.
      if state["stop"] or state["closed"]:
        return finish(f"Stopped after {len(state['history'])}/{len(schedule)} passes. Completed edits remain.")
      if state["paused"]:
        state["message"] = f"Paused after {len(state['history'])}/{len(schedule)} passes."
        notify()
        return True
      if state['phase'] == 'settling':
        if state['index'] == len(schedule):
          return finish(f"Finished {len(schedule)} global passes; final pass used original density. Previous refinement settings restored.")
        state['phase'] = 'prepare'
        return True
      check()
      if coot.refinement_already_ongoing_p():
        raise ValueError("Another refinement is active; completed passes remain.")
      if state["phase"] == "prepare":
        resolution = schedule[state["index"]]
        cropped = resolution is not None or state["final_crop"]
        label = f"Low-pass {resolution:g} A" if resolution is not None else "Original (cropped)" if cropped else "Original"
        state.update(resolution=resolution, cropped=cropped, stage_label=label)
        if not cropped:
          state["prepared"] = (None, None)
          state["phase"] = "ready"
        else:
          state["owner"] = tempfile.TemporaryDirectory(prefix="coot-global-multimap-")
          # Low-pass convolution needs generous margins to suppress FFT wraparound.
          margin = max(padding, 2*resolution if resolution is not None else 0.)
          source = _lowpass_export(map_id, model, state["owner"].name, margin)
          output = os.path.join(state["owner"].name, "filtered.map") if resolution is not None else source["path"]
          state["message"] = f"Preparing pass {state['index']+1}/{len(schedule)}: {label}..."
          state["phase"] = "filtering"
          notify()
          def filtering():
            try:
              compact = os.path.join(state["owner"].name, "compact.map")
              input_path = compact if _global_multimap_compact_crop(source["path"], compact) else source["path"]
              if resolution is not None:
                _lowpass_filter_background(input_path, output, resolution, .10)
              output_path = output if resolution is not None else input_path
              state["prepared"] = (output_path, None)
            except Exception as error:
              state["prepared"] = (None, str(error))
          state["worker"] = threading.Thread(target=filtering, name="coot-global-multimap-filter", daemon=True)
          state["worker"].start()
          return True
      if state["phase"] == "filtering":
        state["phase"] = "ready"
      if state["phase"] == "ready":
        path, error = state["prepared"]
        if error:
          raise RuntimeError(error)
        stage_map = map_id
        if path is not None:
          existing = set(map_molecule_list())
          scroll = coot.scroll_wheel_map()
          selected = coot.imol_refinement_map()
          try:
            stage_map = coot.handle_read_ccp4_map(path, 0)
            if stage_map in existing or not coot.is_valid_map_molecule(stage_map):
              raise RuntimeError("Could not load the temporary stage map.")
            name = f"Global multimap temporary {id(state)}: {state['stage_label']}"
            state["temporary"] = (stage_map, coot.molecule_name(stage_map))
            coot.set_molecule_name(stage_map, name)
            state["temporary"] = (stage_map, name)
            coot.set_map_displayed(stage_map, 0)
            if state["resolution"] is None:
              current_points = [a[2] for r in state["expected"].values() for a in r["atoms"]]
              current_probes = current_points[::max(1, len(current_points)//64)][:64]
              values = [coot.density_at_point(stage_map, *p) for p in current_probes]
              original = [coot.density_at_point(map_id, *p) for p in current_probes]
              if any(not math.isclose(a, b, abs_tol=1e-6, rel_tol=1e-5) for a, b in zip(values, original)):
                raise RuntimeError("Cropped final map did not reproduce original density at the model.")
          finally:
            if coot.is_valid_map_molecule(scroll):
              coot.set_scroll_wheel_map(scroll)
            if coot.is_valid_map_molecule(selected):
              coot.set_imol_refinement_map(selected)
        estimate = estimate_local_em_map_weight(model, stage_map, apply=False, reference_map_id=map_id,
                                               lowpass_resolution=state['resolution'] or 0.)
        state.update(phase="launch", stage_map=stage_map, estimate=estimate,
                     message=f"Pass {state['index']+1}/{len(schedule)}: {state['stage_label']} | temporary weight {estimate['weight']*multiplier:.4g}")
        notify()
        return True  # Let GTK paint the stage/weight before the native call.
      if state["phase"] == "launch":
        if state['max_seconds']:
          _global_multimap_timed_start(state, state['stage_map'], state.pop('estimate'))
          return True
        _global_multimap_refine(state, state["stage_map"], state.pop("estimate"))
        _global_multimap_cleanup(state)
        state["index"] += 1
        state["prepared"] = None
        if state["index"] == len(schedule):
          return finish(f"Finished {len(schedule)} global passes; final pass used original density. Previous refinement settings restored.")
        state.update(phase="prepare", message=f"Completed {state['index']}/{len(schedule)} global passes.")
        notify()
      return True
    except Exception as error:
      return finish(f"Stopped: {error}", str(error))
  state["tick"] = tick
  globals()["_GLOBAL_MULTIMAP_JOB"] = state
  try:
    state["source"] = glib.timeout_add(100, tick)
    if not state["source"]:
      raise RuntimeError("Could not schedule global refinement.")
  except Exception:
    state["running"] = False
    raise
  notify()
  return state


def global_multimap_refinement_dialog():
  """Compact coarse-to-fine global refinement using the selected refinement map."""
  glib = _coot_gui_repository_module("GLib")
  if Gtk is None or glib is None or gemmi is None or _tq_numpy_module() is None:
    info_dialog("Global multimap refinement requires GTK, Gemmi and NumPy.")
    return None
  active = _active_residue_or_status()
  models, maps = list(model_molecule_list()), [m for m in map_molecule_list() if not coot.map_is_difference_map(m)]
  if not models or not maps:
    info_dialog("Open a model and a non-difference refinement map first.")
    return None
  window = Gtk.Window(title="Global multimap refinement")
  window.set_default_size(580, -1)
  box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=8)
  for edge in ("top", "bottom", "start", "end"):
    getattr(box, "set_margin_"+edge)(12)
  window.set_child(box)
  grid = Gtk.Grid(column_spacing=12, row_spacing=7)
  box.append(grid)
  model_choice, map_choice = Gtk.ComboBoxText(), Gtk.ComboBoxText()
  for choice, numbers, selected in ((model_choice, models, active[0] if active else models[0]),
                                   (map_choice, maps, coot.imol_refinement_map())):
    for number in numbers:
      choice.append(str(number), f"#{number}: {os.path.basename(str(coot.molecule_name(number)))}")
    choice.set_active_id(str(selected if selected in numbers else numbers[0]))
    choice.set_hexpand(True)
  start, finest, repeats, padding, multiplier, max_seconds = [Gtk.Entry() for _ in range(6)]
  for field, value in zip((start, finest, repeats, padding, multiplier, max_seconds), ("5", "4", "1", "30", "1", "20")):
    field.set_text(value)
    field.set_width_chars(6)
    field.set_max_width_chars(8)
  for row, (label, field) in enumerate((("Whole model", model_choice), ("Refinement map", map_choice),
      ("Starting resolution (A)", start), ("Finest filtered resolution (A)", finest),
      ("Passes per stage", repeats), ("Crop padding (A)", padding), ("Weight multiplier", multiplier),
      ("Maximum seconds per stage", max_seconds))):
    grid.attach(Gtk.Label(label=label, xalign=0), 0, row, 1, 1)
    grid.attach(field, 1, row, 1, 1)
  max_seconds.set_tooltip_text('20 seconds by default; 0 = unlimited convergence-driven refinement. Map preparation is excluded. Stopping waits for the current minimization batch. Timed stages may wait for their budget even if Coot converges earlier; convergence is checked at acceptance.')
  final_crop = Gtk.CheckButton(label="Use cropped original map for final stage")
  final_crop.set_active(True)
  box.append(final_crop)
  schedule_label = Gtk.Label(xalign=0)
  schedule_label.set_wrap(True)
  box.append(schedule_label)
  def preview(*_args):
    try:
      stages = _global_multimap_schedule(start.get_text(), finest.get_text(), 1)
      schedule_label.set_text(" -> ".join(f"{v:.3g} A" if v is not None else "Original" for v in stages))
    except (ValueError, TypeError) as error:
      schedule_label.set_text(str(error))
  for field in (start, finest):
    field.connect("changed", preview)
  preview()
  note = Gtk.Label(label="Refines in place, preserving existing restraints. Each pass re-estimates weight near the current model, calibrated to the original map; filtered stages are down-weighted by retained contrast (heuristic). Resolution attenuation uses the value configured via Fit > Set EM refinement weight; unset values are not guessed. Timed passes accept the current result at their budget; Stop accepts early, Pause acts between passes. Do not start other model edits/refinements during a run. Coot Undo restores each accepted pass.", xalign=0)
  note.set_wrap(True)
  note.set_max_width_chars(74)
  box.append(note)
  progress = Gtk.ProgressBar()
  progress.set_show_text(True)
  box.append(progress)
  status = Gtk.Label(label="Temporary maps only; original map and global weight are retained.", xalign=0)
  status.set_wrap(True)
  status.set_max_width_chars(74)
  box.append(status)
  history_label = Gtk.Label(xalign=0)
  history_label.set_selectable(True)
  history_label.add_css_class("monospace")
  history_expander = Gtk.Expander(label="Completed passes / weights")
  history_expander.set_child(history_label)
  box.append(history_expander)
  buttons = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
  run, pause, stop, close = [Gtk.Button(label=label) for label in ("Start", "Pause", "Stop", "Close")]
  for widget in (run, pause, stop, close):
    buttons.append(widget)
  box.append(buttons)
  pause.set_sensitive(False)
  stop.set_sensitive(False)
  state = dict(job=None, closed=False)
  def update(job):
    if state["closed"]:
      return
    status.set_text(job["message"])
    progress.set_fraction(len(job["history"])/len(job["schedule"]))
    progress.set_text(f"{len(job['history'])}/{len(job['schedule'])} passes | {job['phase']}")
    history_label.set_text("\n".join(
        f"{i+1}: {h['resolution'] if h['resolution'] is not None else 'Original'} | weight {h['weight']:.4g} | original {h['baseline_weight']:.4g} x {h['local_factor']:.3g}"
        + (f" x resolution {h['resolution_factor']:.3g}" if h.get('effective_resolution') is not None else '')
        + (f" | {h['elapsed']:.1f}s, {h['termination']}" if 'elapsed' in h else '')
        for i, h in enumerate(job["history"])))
    run.set_sensitive(not job["running"])
    grid.set_sensitive(not job["running"])
    final_crop.set_sensitive(not job["running"])
    pause.set_sensitive(job["running"] and not job["stop"])
    stop.set_sensitive(job["running"] and not job["stop"])
    if not job["running"]:
      pause.set_label("Pause")
  def begin(*_args):
    try:
      state["job"] = start_global_multimap_refinement(int(model_choice.get_active_id()), int(map_choice.get_active_id()),
          start.get_text(), finest.get_text(), repeats.get_text(), padding.get_text(), final_crop.get_active(),
          multiplier.get_text(), update, max_seconds=max_seconds.get_text())
    except Exception as error:
      status.set_text(str(error))
  def toggle_pause(*_args):
    job = state["job"]
    if job and job["running"]:
      job["paused"] = not job["paused"]
      pause.set_label("Resume" if job["paused"] else "Pause")
  def request_stop(*_args):
    job = state["job"]
    if job and job["running"]:
      job["stop"] = True
      status.set_text("Stopping; completed passes remain.")
  def finish(*_args):
    state["closed"] = True
    job = state["job"]
    if job and job["running"]:
      job.update(stop=True, closed=True)
    window.destroy()
    return True
  run.connect("clicked", begin)
  pause.connect("clicked", toggle_pause)
  stop.connect("clicked", request_stop)
  close.connect("clicked", finish)
  window.connect("close-request", finish)
  state["widgets"] = dict(run=run, pause=pause, stop=stop, close=close, model=model_choice, map=map_choice,
      start=start, finest=finest, repeats=repeats, padding=padding, multiplier=multiplier, final_crop=final_crop,
      max_seconds=max_seconds,
      progress=progress, status=status)
  window.global_multimap_state = state
  window.present()
  return window


def _parse_ccp4_mrc_header(path):
  with open(path, "rb") as handle:
    header = handle.read(1024)
  if len(header) < 76:
    return None
  for endian in ("<", ">"):
    ints_10 = struct.unpack(endian + "10i", header[:40])
    mx, my, mz = ints_10[7], ints_10[8], ints_10[9]
    floats_6 = struct.unpack(endian + "6f", header[40:64])
    a, b, c, alpha, beta, gamma = floats_6
    axes = struct.unpack(endian + "3i", header[64:76])
    if (
      mx > 0 and my > 0 and mz > 0
      and a > 0.0 and b > 0.0 and c > 0.0
      and 0.0 < alpha <= 180.0
      and 0.0 < beta <= 180.0
      and 0.0 < gamma <= 180.0
      and all(axis in (1, 2, 3) for axis in axes)
    ):
      return {
        "mx": mx,
        "my": my,
        "mz": mz,
        "a": a,
        "b": b,
        "c": c,
      }
  return None


def _resample_factor_for_target_pixel_size(map_id, target_pixel_size):
  for path in _candidate_map_file_paths(map_id):
    header = _parse_ccp4_mrc_header(path)
    if not header:
      continue
    sampling_a = header["a"] / float(header["mx"])
    sampling_b = header["b"] / float(header["my"])
    sampling_c = header["c"] / float(header["mz"])
    current_pixel_size = max(sampling_a, sampling_b, sampling_c)
    return current_pixel_size / target_pixel_size, current_pixel_size
  return None, None


def _resample_plan_for_target_pixel_size(map_id, target_pixel_size):
  """Estimate the output grid that resampling would create for a target pixel size."""
  for path in _candidate_map_file_paths(map_id):
    header = _parse_ccp4_mrc_header(path)
    if not header:
      continue
    sampling_a = header["a"] / float(header["mx"])
    sampling_b = header["b"] / float(header["my"])
    sampling_c = header["c"] / float(header["mz"])
    current_pixel_size = max(sampling_a, sampling_b, sampling_c)
    resample_factor = current_pixel_size / target_pixel_size
    return {
      "resample_factor": resample_factor,
      "current_pixel_size": current_pixel_size,
      "new_grid": (
        int(math.ceil(header["mx"] * resample_factor)),
        int(math.ceil(header["my"] * resample_factor)),
        int(math.ceil(header["mz"] * resample_factor)),
      ),
    }
  return None


def style_resampled_em_map(map_id):
  """Apply the standard ambient EM-map appearance used by the restyle shortcut."""
  set_draw_map_standard_lines(map_id, 1)
  set_draw_solid_density_surface(map_id, 0)
  if not map_is_difference_map(map_id):
    set_map_colour(map_id, *EM_REFINED_MAP_COLOUR)
  for name, values in (("set_map_material_ambient", EM_MAP_AMBIENT),
                       ("set_map_material_diffuse", EM_MAP_DIFFUSE)):
    setter = getattr(coot, name, None)
    if callable(setter):
      setter(map_id, *values)
  set_map_material_specular(map_id, *EM_MAP_SPECULAR)
  set_map_fresnel_settings(map_id, *EM_MAP_FRESNEL)
  set_solid_density_surface_opacity(map_id, 1.0)
  MAP_LOCAL_APPEARANCE_STATE[map_id] = {
    "map_colour": list(map_colour_components_py(map_id)),
    "ambient": EM_MAP_AMBIENT,
    "diffuse": EM_MAP_DIFFUSE,
    "specular_strength": EM_MAP_SPECULAR[0],
    "shininess": EM_MAP_SPECULAR[1],
    "fresnel": EM_MAP_FRESNEL,
    "opacity": 1.0,
  }


def _map_appearance_map_label():
  label = Gtk.Label(label="")
  label.set_xalign(0.0)
  label.set_hexpand(True)
  label.set_ellipsize(_coot_gui_repository_module("Pango").EllipsizeMode.MIDDLE)
  label.set_max_width_chars(44)
  return label


def _update_map_appearance_map_label(label, map_id):
  if map_id is None:
    label.set_text("No active map")
    label.set_tooltip_text(None)
    return
  try:
    name = molecule_name(map_id)
  except Exception:
    name = "map"
  text = f"Active map: {name} ({map_id})"
  label.set_text(text)
  label.set_tooltip_text(text)


def show_active_map_brightness_slider():
  """Open a non-modal slider that live-updates the current active map's ambient brightness."""
  initial_map = _scrollable_map_or_status()
  if initial_map is None:
    return None

  window = Gtk.Window()
  window.set_title("Map brightness")
  window.set_default_size(420, -1)

  vbox = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=10)
  vbox.set_margin_top(12)
  vbox.set_margin_bottom(12)
  vbox.set_margin_start(12)
  vbox.set_margin_end(12)

  map_label = _map_appearance_map_label()
  value_label = Gtk.Label(label="100%")
  value_label.set_width_chars(5)

  slider_row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=10)
  adjustment = Gtk.Adjustment(value=100.0, lower=0.0, upper=200.0, step_increment=1.0, page_increment=10.0)
  slider = Gtk.Scale(orientation=Gtk.Orientation.HORIZONTAL, adjustment=adjustment)
  slider.set_hexpand(True)
  slider.set_draw_value(False)
  slider.set_digits(0)

  button_row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
  button_row.set_halign(Gtk.Align.END)
  reset_button = Gtk.Button(label="Reset to 100%")
  close_button = Gtk.Button(label="Close")

  def current_map():
    # Resolve this afresh for every update so changing the scroll-wheel/refinement
    # map while the window is open redirects the control to that map.
    map_id = scroll_wheel_map()
    if map_id != -1 and map_id in map_molecule_list():
      return map_id
    map_id = imol_refinement_map()
    if map_id != -1 and map_id in map_molecule_list():
      return map_id
    displayed = [imol for imol in map_molecule_list() if map_is_displayed(imol)]
    return displayed[0] if displayed else None

  def update_map_label(map_id):
    _update_map_appearance_map_label(map_label, map_id)

  def apply_brightness(scale):
    percent = float(scale.get_value())
    value_label.set_text("{:.0f}%".format(percent))
    map_id = current_map()
    update_map_label(map_id)
    if map_id is None:
      return
    brightness = percent / 100.0
    try:
      set_map_material_ambient(map_id, brightness, brightness, brightness, 1.0)
      state = MAP_LOCAL_APPEARANCE_STATE.setdefault(map_id, {})
      state["ambient"] = (brightness, brightness, brightness, 1.0)
    except Exception as error:
      print("WARNING:: could not set map brightness: {}".format(error))

  def reset_brightness(button):
    slider.set_value(100.0)

  slider.connect("value-changed", apply_brightness)
  reset_button.connect("clicked", reset_brightness)
  close_button.connect("clicked", lambda button: window.close())

  slider_row.append(slider)
  slider_row.append(value_label)
  button_row.append(reset_button)
  button_row.append(close_button)
  vbox.append(map_label)
  vbox.append(slider_row)
  vbox.append(button_row)
  window.set_child(vbox)
  update_map_label(initial_map)
  window.present()
  return window


def show_active_map_colour_slider():
  """Open a non-modal hue slider that live-updates the current active map colour."""
  import colorsys

  initial_map = _scrollable_map_or_status()
  if initial_map is None:
    return None

  window = Gtk.Window()
  window.set_title("Map colour")
  window.set_default_size(420, -1)

  vbox = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=10)
  vbox.set_margin_top(12)
  vbox.set_margin_bottom(12)
  vbox.set_margin_start(12)
  vbox.set_margin_end(12)

  map_label = _map_appearance_map_label()
  value_label = Gtk.Label(label="")
  value_label.set_width_chars(5)

  slider_row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=10)
  adjustment = Gtk.Adjustment(value=0.0, lower=0.0, upper=360.0, step_increment=1.0, page_increment=15.0)
  slider = Gtk.Scale(orientation=Gtk.Orientation.HORIZONTAL, adjustment=adjustment)
  slider.set_hexpand(True)
  slider.set_draw_value(False)
  slider.set_digits(0)

  button_row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
  button_row.set_halign(Gtk.Align.END)
  reset_button = Gtk.Button(label="Reset colour")
  close_button = Gtk.Button(label="Close")

  state = {"map_id": None, "saturation": 1.0, "value": 1.0, "reset_colour": None, "updating": False}

  def current_map():
    map_id = scroll_wheel_map()
    if map_id != -1 and map_id in map_molecule_list():
      return map_id
    map_id = imol_refinement_map()
    if map_id != -1 and map_id in map_molecule_list():
      return map_id
    displayed = [imol for imol in map_molecule_list() if map_is_displayed(imol)]
    return displayed[0] if displayed else None

  def update_map_label(map_id):
    _update_map_appearance_map_label(map_label, map_id)

  def sync_to_map(map_id):
    if map_id is None or map_id == state["map_id"]:
      return
    try:
      colour = tuple(float(x) for x in map_colour_components_py(map_id)[:3])
      hue, saturation, value = colorsys.rgb_to_hsv(*colour)
    except Exception as error:
      print("WARNING:: could not read map colour: {}".format(error))
      return
    state["map_id"] = map_id
    state["saturation"] = saturation
    state["value"] = value
    state["reset_colour"] = colour
    state["updating"] = True
    slider.set_value(hue * 360.0)
    state["updating"] = False
    value_label.set_text("{:.0f} deg".format(hue * 360.0))

  def apply_colour(scale):
    if state["updating"]:
      return
    map_id = current_map()
    update_map_label(map_id)
    if map_id is None:
      return
    sync_to_map(map_id)
    degrees = float(scale.get_value())
    value_label.set_text("{:.0f} deg".format(degrees))
    red, green, blue = colorsys.hsv_to_rgb(degrees / 360.0, state["saturation"], state["value"])
    try:
      set_map_colour(map_id, red, green, blue)
      local_state = MAP_LOCAL_APPEARANCE_STATE.setdefault(map_id, {})
      local_state["map_colour"] = [red, green, blue]
    except Exception as error:
      print("WARNING:: could not set map colour: {}".format(error))

  def reset_colour(button):
    map_id = current_map()
    update_map_label(map_id)
    if map_id is None:
      return
    sync_to_map(map_id)
    colour = state["reset_colour"]
    if colour is None:
      return
    try:
      set_map_colour(map_id, *colour)
      hue, saturation, value = colorsys.rgb_to_hsv(*colour)
      state["saturation"] = saturation
      state["value"] = value
      state["updating"] = True
      slider.set_value(hue * 360.0)
      state["updating"] = False
      value_label.set_text("{:.0f} deg".format(hue * 360.0))
      local_state = MAP_LOCAL_APPEARANCE_STATE.setdefault(map_id, {})
      local_state["map_colour"] = list(colour)
    except Exception as error:
      print("WARNING:: could not reset map colour: {}".format(error))

  slider.connect("value-changed", apply_colour)
  reset_button.connect("clicked", reset_colour)
  close_button.connect("clicked", lambda button: window.close())

  slider_row.append(slider)
  slider_row.append(value_label)
  button_row.append(reset_button)
  button_row.append(close_button)
  vbox.append(map_label)
  vbox.append(slider_row)
  vbox.append(button_row)
  window.set_child(vbox)
  update_map_label(initial_map)
  sync_to_map(initial_map)
  window.present()
  return window


def _restyle_active_map_without_resampling(map_id, contour_level_sigma, status_message):
  style_resampled_em_map(map_id)
  if isinstance(contour_level_sigma, (int, float)):
    set_contour_level_in_sigma(map_id, contour_level_sigma)
  set_map_displayed(map_id, 1)
  set_scroll_wheel_map(map_id)
  set_scrollable_map(map_id)
  add_status_bar_text(status_message)
  return map_id


def resample_active_map_for_em_half_angstrom(force=False, allow_large_output=False):
  map_id = _scrollable_map_or_status()
  if map_id is None:
    return None
  if map_is_difference_map(map_id):
    add_status_bar_text("Scroll-wheel map is a difference map; resample/restyle skipped")
    return None
  original_refinement_map = imol_refinement_map()
  old_map_was_refinement_map = (original_refinement_map == map_id)
  contour_level_sigma = get_contour_level_in_sigma(map_id)
  if not force and not _map_looks_em_like(map_id):
    return _restyle_active_map_without_resampling(
      map_id,
      contour_level_sigma,
      "Map is not an EM map",
    )
  resample_plan = _resample_plan_for_target_pixel_size(map_id, EM_TARGET_PIXEL_SIZE)
  if resample_plan is None:
    return _restyle_active_map_without_resampling(
      map_id,
      contour_level_sigma,
      "Grid spacing could not be determined",
    )
  resample_factor = resample_plan["resample_factor"]
  current_pixel_size = resample_plan["current_pixel_size"]
  if current_pixel_size <= EM_TARGET_PIXEL_SIZE:
    style_resampled_em_map(map_id)
    set_contour_level_in_sigma(map_id, contour_level_sigma)
    set_map_displayed(map_id, 1)
    set_scroll_wheel_map(map_id)
    set_scrollable_map(map_id)
    if old_map_was_refinement_map:
      try:
        set_imol_refinement_map(map_id)
      except Exception:
        pass
    add_status_bar_text("Map already finer than 0.5 A/pixel; restyled without resampling")
    return map_id
  new_grid = resample_plan["new_grid"]
  max_grid_dimension = max(new_grid)
  if (
    not allow_large_output
    and max_grid_dimension > EM_RESAMPLE_CONFIRM_MAX_GRID_DIMENSION
  ):
    generic_confirm_dialog(
      "Resample/restyle current map",
      "Resampling would generate a large map, which may take a while.\n\n"
      "Estimated grid: {0} x {1} x {2} (max dimension {3} > {4}).\n\n"
      "What do you want to do?".format(
        new_grid[0],
        new_grid[1],
        new_grid[2],
        max_grid_dimension,
        EM_RESAMPLE_CONFIRM_MAX_GRID_DIMENSION,
      ),
      "Just restyle - skip resampling",
      lambda: _restyle_active_map_without_resampling(
        map_id,
        contour_level_sigma,
        "Skipped resampling and just restyled current map",
      ),
      "Go ahead and resample, I'll make a cup of coffee...",
      lambda: resample_active_map_for_em_half_angstrom(force=force, allow_large_output=True),
    )
    return None
  new_map_id = sharpen_blur_map_with_resampling(map_id, 0.0, resample_factor)
  if new_map_id == -1:
    return _restyle_active_map_without_resampling(
      map_id,
      contour_level_sigma,
      "Resampling failed",
    )
  style_resampled_em_map(new_map_id)
  set_contour_level_in_sigma(new_map_id, contour_level_sigma)
  set_map_displayed(new_map_id, 1)
  set_scroll_wheel_map(new_map_id)
  set_scrollable_map(new_map_id)
  if old_map_was_refinement_map:
    try:
      set_imol_refinement_map(new_map_id)
    except Exception:
      pass
  close_molecule(map_id)
  add_status_bar_text("Created EM-style 0.5 A/pixel map")
  return new_map_id


def make_masked_map_em(skip_non_em_confirmation=False):
  """Mask the active map by the active molecule and display the result in magenta."""
  map_id = _scrollable_map_or_status()
  if map_id is None:
    return None

  if not skip_non_em_confirmation and not _map_looks_em_like(map_id):
    generic_confirm_dialog(
      "Make masked map (EM)",
      "This is not an EM map. Are you sure?",
      "Cancel",
      lambda: None,
      "Continue",
      lambda: make_masked_map_em(skip_non_em_confirmation=True),
    )
    return None

  mol_id = _active_model_molecule_for_map_tools("masked map")
  if mol_id is None:
    return None

  current_contour_absolute = abs(get_contour_level_absolute(map_id))

  previous_mask_radius = None
  try:
    previous_mask_radius = map_mask_atom_radius()
  except Exception:
    previous_mask_radius = None

  try:
    set_map_mask_atom_radius(EM_MASKED_MAP_RADIUS)
    new_map_id = _mask_map_by_all_atoms(map_id, mol_id, 0)
  finally:
    if previous_mask_radius is not None:
      set_map_mask_atom_radius(previous_mask_radius)

  if new_map_id == -1 or new_map_id not in map_molecule_list():
    info_dialog("Failed to create masked map.")
    return None

  set_map_is_difference_map(new_map_id, 0)
  set_map_colour(
    new_map_id,
    EM_MASKED_MAP_COLOUR[0],
    EM_MASKED_MAP_COLOUR[1],
    EM_MASKED_MAP_COLOUR[2],
  )
  if current_contour_absolute > 0.0:
    set_contour_level_absolute(new_map_id, current_contour_absolute)
  set_map_displayed(new_map_id, 1)
  add_status_bar_text(
    "Created masked map #{0} from map #{1} around molecule #{2}".format(
      new_map_id,
      map_id,
      mol_id,
    )
  )
  return new_map_id


def make_pseudo_diff_map_em():
  """Backward-compatible wrapper for the older pseudo-diff menu action name."""
  return make_masked_map_em()


def _map_global_extent_radius(map_id):
  cell = map_cell(map_id)
  if not cell:
    return 20.0
  try:
    return max(cell[0], cell[1], cell[2]) / 2.0
  except Exception:
    return cell[0] / 2.0


def _save_global_view_settings(map_id):
  MAP_GLOBAL_VIEW_SETTINGS[map_id] = {
    "map_radius": _current_map_radius(map_id),
    "clipping_front": get_clipping_plane_front(),
    "clipping_back": get_clipping_plane_back(),
    "map_colour": list(map_colour_components_py(map_id)),
    "opacity": get_solid_density_surface_opacity(map_id),
  }


def _restore_global_view_settings(map_id, fallback_radius):
  saved = MAP_GLOBAL_VIEW_SETTINGS.get(map_id)
  if not saved:
    _set_map_radius_both(fallback_radius, map_id)
    return
  _set_map_radius_both(saved["map_radius"], map_id)
  set_clipping_front(saved["clipping_front"])
  set_clipping_back(saved["clipping_back"])


def _set_global_view_extent(map_id):
  current_radius = max(_current_map_radius(map_id), 1.0)
  global_radius = max(_map_global_extent_radius(map_id), current_radius)
  front = get_clipping_plane_front()
  back = get_clipping_plane_back()
  scale = global_radius / current_radius
  _set_map_radius_both(global_radius, map_id)
  set_clipping_front(front * scale)
  set_clipping_back(back * scale)


def toggle_global_map_view():
  map_id = _scrollable_map_or_status()
  if map_id is None:
    return None
  default_radius=20.0
  if map_is_difference_map(map_id)!=0:
    add_status_bar_text("Global surface view is only for non-difference maps")
    return None
  if not MAP_SURFACE_DISPLAY_STATE.get(map_id, False):
    local_appearance = MAP_LOCAL_APPEARANCE_STATE.get(map_id)
    _save_global_view_settings(map_id)
    set_draw_solid_density_surface(map_id,1)
    set_draw_map_standard_lines(map_id,0)
    set_flat_shading_for_solid_density_surface(0)
    set_map_fresnel_settings(map_id,1,0.0,0.5,2.0)
    set_solid_density_surface_opacity(
      map_id,
      MAP_SURFACE_OPACITY_STATE.get(map_id, get_solid_density_surface_opacity(map_id))
    )
    _set_global_view_extent(map_id)
    MAP_SURFACE_DISPLAY_STATE[map_id] = True
  else:
    saved_settings = MAP_GLOBAL_VIEW_SETTINGS.get(map_id, {})
    saved_colour = saved_settings.get("map_colour")
    set_draw_solid_density_surface(map_id,0)
    set_draw_map_standard_lines(map_id,1)
    saved_global_opacity = get_solid_density_surface_opacity(map_id)
    MAP_SURFACE_OPACITY_STATE[map_id] = saved_global_opacity
    set_solid_density_surface_opacity(map_id, saved_settings.get("opacity", 1.0))
    set_map_material_specular(map_id, 0.0, 64.0)
    set_map_fresnel_settings(map_id, 0, 0.0, 0.5, 2.0)
    if saved_colour and len(saved_colour) >= 3:
      set_map_colour(map_id,saved_colour[0],saved_colour[1],saved_colour[2])
    _restore_global_view_settings(map_id, default_radius)
    MAP_SURFACE_DISPLAY_STATE[map_id] = False
    
  
#Go to next residue in current polymer chain.
def next_res():
  reference_residue = _navigation_reference_residue()
  if not reference_residue:
    return None
  if reference_residue["source"] == "chain_start":
    return _go_to_navigation_residue(
      reference_residue["mol_id"],
      reference_residue["chain_id"],
      reference_residue["resno"],
      reference_residue["ins_code"],
    )
  mol_id = reference_residue["mol_id"]
  ch_id = reference_residue["chain_id"]
  serial_number = reference_residue.get("serial_number")
  if serial_number is None:
    serial_number = _residue_serial_number(
      mol_id,
      ch_id,
      reference_residue["resno"],
      reference_residue["ins_code"],
    )
  if serial_number < 0:
    add_status_bar_text("Could not resolve the current residue in its chain")
    return None
  n_residues = chain_n_residues(ch_id, mol_id)
  for next_serial in range(serial_number + 1, n_residues):
    next_resno = seqnum_from_serial_number(mol_id, ch_id, next_serial)
    next_ins_code = insertion_code_from_serial_number(mol_id, ch_id, next_serial)
    if _residue_is_polymer(mol_id, ch_id, next_resno, next_ins_code):
      return _go_to_navigation_residue(mol_id, ch_id, next_resno, next_ins_code, next_serial)
  add_status_bar_text("Already at the C-terminus of the current polymer chain")
  return None

#Go to previous residue in current polymer chain.
def prev_res():
  reference_residue = _navigation_reference_residue()
  if not reference_residue:
    return None
  if reference_residue["source"] == "chain_start":
    return _go_to_navigation_residue(
      reference_residue["mol_id"],
      reference_residue["chain_id"],
      reference_residue["resno"],
      reference_residue["ins_code"],
    )
  mol_id = reference_residue["mol_id"]
  ch_id = reference_residue["chain_id"]
  serial_number = reference_residue.get("serial_number")
  if serial_number is None:
    serial_number = _residue_serial_number(
      mol_id,
      ch_id,
      reference_residue["resno"],
      reference_residue["ins_code"],
    )
  if serial_number < 0:
    add_status_bar_text("Could not resolve the current residue in its chain")
    return None
  for previous_serial in range(serial_number - 1, -1, -1):
    previous_resno = seqnum_from_serial_number(mol_id, ch_id, previous_serial)
    previous_ins_code = insertion_code_from_serial_number(mol_id, ch_id, previous_serial)
    if _residue_is_polymer(mol_id, ch_id, previous_resno, previous_ins_code):
      return _go_to_navigation_residue(mol_id, ch_id, previous_resno, previous_ins_code, previous_serial)
  add_status_bar_text("Already at the N-terminus of the current polymer chain")
  return None
  
def sequence_context():
  residue = _active_residue_or_status()
  if residue is None:
    return None

  mol_id = residue[0]
  ch_id = residue[1]
  resnum = residue[2]
  ins_code = residue[3]
  resname = residue_name(mol_id, ch_id, resnum, ins_code)

  def get_aa_code(context_resnum):
    context_resname = residue_name(mol_id, ch_id, context_resnum, ins_code)
    if not context_resname:
      return "-"
    if len(context_resname) == 1:
      return context_resname
    aa_code = three_letter_code2single_letter(context_resname)
    if context_resname != "ALA" and aa_code == "A":
      return "X"
    return aa_code

  current_res = get_aa_code(resnum)
  minus_context = ""
  for i in range(1,10):
    minus_context = str(get_aa_code(resnum - i)) + minus_context
  plus_context = ""
  for i in range(1,10):
    plus_context = plus_context + str(get_aa_code(resnum + i))
  final_string="Residue:  " + resname + "  " + str(resnum) +"  Sequence context: ..." + minus_context + "[" + current_res + "]" + plus_context + "..."
  info_dialog(final_string)
  return 1
  
#Toggle display of active map
map_disp_flag={0:0}
map_disp_flag_cycle=0
def toggle_map_display():
  global map_disp_flag
  global map_disp_flag_cycle
  if map_disp_flag_cycle==0:
    for map_id in map_molecule_list():
      disp_value=map_is_displayed(map_id)
      map_disp_flag[map_id]=disp_value
      if disp_value==1:
        set_map_displayed(map_id,0) #If any maps are displayed, undisplay them.
    map_disp_flag_cycle=1
  elif map_disp_flag_cycle==1:
    disp_counter=0 
    for map_id in map_molecule_list():
      if map_id not in map_disp_flag: #if the map wasn't present in the previous cycle, assign a disp_value for it
        disp_value=map_is_displayed(map_id)
        map_disp_flag[map_id]=disp_value
      if map_disp_flag[map_id]==1:
        set_map_displayed(map_id,1) #Redisplay any maps that were displayed on the previous cycle.
      disp_counter=disp_counter+map_disp_flag[map_id] #test
    if disp_counter==0: #If no maps were displayed in the prior cycle, display all maps.
      for map_id in map_molecule_list(): 
        set_map_displayed(map_id,1) 
    map_disp_flag_cycle=0

#Colour active segment
def colour_active_segment():
  context = _active_segment_context_or_status()
  if not context:
    return None
  mol_id = context["mol_id"]
  selected = set(context["segment_specs"])
  colour_list = [(list(spec), 34) for spec in context["segment_specs"]]
  blank_list = [(spec, 0) for spec in _all_residue_specs_for_colouring(mol_id) if tuple(spec) not in selected]
  _apply_user_defined_residue_colours(mol_id, blank_list, colour_list)


def _all_residue_specs_for_colouring(mol_id):
  if callable(getattr(coot, "python_representation_kk", None)):
    try:
      return [list(spec) for spec in _model_coordinate_snapshot(mol_id)]
    except ValueError:
      pass
  residue_specs=[]
  for residue_entry in all_residues_with_serial_numbers(mol_id) or []:
    if not isinstance(residue_entry, list) or len(residue_entry) < 4:
      continue
    residue_spec = residue_entry[1:]
    chain_id = residue_spec_to_chain_id(residue_spec)
    resno = residue_spec_to_res_no(residue_spec)
    ins_code = residue_spec_to_ins_code(residue_spec)
    if chain_id is False or resno is False or ins_code is False:
      continue
    residue_specs.append([chain_id, resno, ins_code])
  return residue_specs


# ============================================================================
# Experimental custom-colouring helpers
# ============================================================================
#
# The old base-molecule user-defined colouring path leaks into ordinary display
# modes in this Coot 1.1 build. The only same-molecule route that looks
# plausible is to create additional representations using the dedicated
# user-defined bond-colour mode, then immediately clear the molecule's stored
# colour rules. Ramachandran colouring is the current test case for that path.
#

def _active_molecule_or_status():
  residue = _active_residue_or_status()
  if not residue:
    return None
  return residue[0]


def yellowify_carbons_in_active_molecule():
  """Use Coot's live bond-colour rotation path to yellowify active-molecule carbons."""
  mol_id = _active_molecule_or_status()
  if mol_id is None:
    return None
  previous_c_only_flag = get_colour_map_rotation_on_read_pdb_c_only_flag()
  try:
    set_colour_map_rotation_on_read_pdb_c_only_flag(1)
    # In Coot's bond-colour rotation code, 21 degrees is treated as the
    # default/yellow reference rotation for standard carbon colouring.
    set_bond_colour_rotation_for_molecule(mol_id, 21.0)
  finally:
    set_colour_map_rotation_on_read_pdb_c_only_flag(previous_c_only_flag)
  add_status_bar_text("Yellowified carbons in the active molecule")
  return 1


def _active_polymer_molecule_for_colouring(action_name):
  residue=_active_residue_or_status()
  if not residue:
    return None
  if not _residue_is_polymer(residue[0], residue[1], residue[2], residue[3]):
    info_dialog(action_name+" requires the active residue to be polymer.")
    return None
  return residue[0]


def _iter_chain_serial_numbers(mol_id, ch_id):
  try:
    n_residues = int(chain_n_residues(ch_id, mol_id))
  except Exception:
    return
  for serial_number in range(max(0, n_residues)):
    yield serial_number


def _clear_custom_colour_additional_representations(mol_id, clear_user_colours=True):
  handles = CUSTOM_COLOUR_ADDITIONAL_REPRESENTATIONS.pop(mol_id, [])
  for handle in handles:
    try:
      delete_additional_representation(mol_id, handle)
    except Exception:
      pass
  if clear_user_colours:
    try:
      clear_user_defined_atom_colours(mol_id)
    except Exception:
      pass


def _direct_user_defined_blank_rows_for_molecule(mol_id, blank_colour=0):
  del mol_id
  # Coot's CID "//" selects the whole molecule. Use one native rule rather
  # than building thousands of per-residue selections for large models.
  return [("//", blank_colour)]


def _graphics_to_legacy_user_defined_representation(mol_id, colour_rows, ca_only=False):
  if _supports_direct_user_defined_colouring():
    representation = (graphics_to_user_defined_atom_colours_representation if ca_only
                      else graphics_to_user_defined_atom_colours_all_atoms_representation)
    representation(mol_id)
    cycle_rep_flag[mol_id] = _representation_sequence().index(representation)
    return
  for item in colour_rows or []:
    if not isinstance(item, (list, tuple)) or len(item) < 2:
      continue
    residue_spec = item[0]
    if not isinstance(residue_spec, (list, tuple)) or len(residue_spec) < 3:
      continue
    chain_id = residue_spec[0]
    res_no = residue_spec[1]
    ins_code = residue_spec[2] or ""
    residue_name_here = residue_name(mol_id, chain_id, res_no, ins_code)
    if str(residue_name_here or "").upper() in WATER_RESIDUE_NAMES:
      graphics_to_user_defined_atom_colours_all_atoms_representation(mol_id)
      return
  graphics_to_user_defined_atom_colours_representation(mol_id)


def _set_user_defined_atom_colour_by_residue_atoms_py(mol_id, residue_specs_colour_index_tuple_list_py):
  """Apply residue colours atom-by-atom, avoiding the fragile selection-CID parser."""
  ensure_user_defined_colour_table()
  atom_colour_list = []
  for item in residue_specs_colour_index_tuple_list_py or []:
    if not isinstance(item, (list, tuple)) or len(item) < 2:
      continue
    residue_spec = item[0]
    colour_index = item[1]
    if not isinstance(residue_spec, (list, tuple)) or len(residue_spec) < 3:
      continue
    chain_id = residue_spec[0]
    res_no = residue_spec[1]
    ins_code = residue_spec[2] or ""
    atom_info = residue_info_py(mol_id, chain_id, res_no, ins_code)
    if not isinstance(atom_info, list):
      continue
    for atom in atom_info:
      try:
        atom_name = atom[0][0]
        alt_conf = atom[0][1]
      except Exception:
        continue
      atom_spec = [mol_id, chain_id, res_no, ins_code, atom_name, alt_conf]
      atom_colour_list.append(
        (atom_spec, _legacy_user_colour_index_to_coot_index(colour_index))
      )
  if not atom_colour_list:
    return 0
  try:
    coot.set_user_defined_atom_colour_py(mol_id, atom_colour_list)
  except Exception:
    traceback.print_exc()
    return 0
  return len(atom_colour_list)


def _make_custom_colour_additional_representation(mol_id, residue_spec):
  if not isinstance(residue_spec, (list, tuple)) or len(residue_spec) < 3:
    return None
  chain_id = residue_spec[0]
  res_no = residue_spec[1]
  ins_code = residue_spec[2] or ""
  draw_hydrogens_flag = 0
  if "draw_hydrogens_state" in globals():
    try:
      draw_hydrogens_flag = draw_hydrogens_state(mol_id)
    except Exception:
      draw_hydrogens_flag = 0
  handle = additional_representation_by_attributes(
    mol_id,
    chain_id,
    res_no,
    res_no,
    ins_code,
    CUSTOM_COLOUR_ADDITIONAL_REPRESENTATION_TYPE,
    CUSTOM_COLOUR_USER_DEFINED_BONDS_BOX_TYPE,
    CUSTOM_COLOUR_ADDITIONAL_BOND_WIDTH,
    draw_hydrogens_flag,
  )
  if handle == -1:
    return None
  return handle


def clear_custom_colour_representations_for_active_molecule():
  mol_id = _active_molecule_or_status()
  if mol_id is None:
    return None
  if _supports_direct_user_defined_colouring():
    restore_representation = _last_standard_representation_function(mol_id)
    # On fixed direct-colouring builds, clearing the colour rules while the
    # user-defined all-atoms representation is still active can trigger a crash
    # during redraw. Move back to the last remembered standard representation
    # first, then tear down the user-defined state.
    _restore_last_standard_representation(mol_id, restore_representation)
    _clear_custom_colour_additional_representations(mol_id, clear_user_colours=False)
    blank_rows = _direct_user_defined_blank_rows_for_molecule(mol_id)
    if blank_rows:
      _set_user_defined_atom_colour_by_residue_rows_py(mol_id, blank_rows)
  else:
    _clear_custom_colour_additional_representations(mol_id)
  if _supports_direct_user_defined_colouring():
    # Rebuild the same standard representation once the neutral overwrite has
    # happened. Avoiding clear_user_defined_atom_colours() on the fixed direct
    # path prevents Coot from regenerating with internal -1 colour indices.
    _restore_last_standard_representation(mol_id, restore_representation)
  add_status_bar_text("Cleared custom colour representations")


def _compact_direct_colour_rows(rows):
  """Resolve last-write-wins residue rules against a single neutral baseline."""
  resolved = {}
  for item in rows:
    if not isinstance(item, (list, tuple)) or len(item) < 2:
      continue
    spec, colour = item[:2]
    if not isinstance(spec, (list, tuple)) or len(spec) != 3:
      # Arbitrary CIDs may overlap residue rules; preserve their ordering.
      return rows
    resolved[tuple(spec)] = colour
  neutral = _legacy_user_colour_index_to_coot_index(0)
  return [(list(spec), colour) for spec, colour in resolved.items()
          if _legacy_user_colour_index_to_coot_index(colour) != neutral]


def _consume_colour_steps(iterator):
  while True:
    try:
      next(iterator)
    except StopIteration as result:
      return result.value


def _iter_direct_user_defined_residue_colours(mol_id, blank_res_list, colour_list, info_message=None):
  full_colour_list = [item[:2] for item in list(blank_res_list or []) + list(colour_list or [])
                     if isinstance(item, (list, tuple)) and len(item) >= 2]
  if not full_colour_list:
    if info_message:
      info_dialog(info_message)
    return None
  epoch = _MODEL_EDIT_EPOCHS.get(mol_id, 0)
  rows = _compact_direct_colour_rows(full_colour_list)
  yield "Preparing colours", 0.05, True
  snapshot = None
  # Explicit atom addressing is faster than thousands of full-model CID scans.
  # It addresses MODEL 1 only, so ensemble/ambiguous models retain the CID path.
  if (len(rows) >= 128 and all(isinstance(spec, (list, tuple)) for spec, _ in rows)
      and callable(getattr(coot, "python_representation_kk", None))
      and callable(getattr(coot, "set_user_defined_atom_colour_py", None))):
    try:
      snapshot = _model_coordinate_snapshot(mol_id)
    except ValueError:
      pass
  atom_rows = []
  if snapshot is not None:
    for index, (spec, colour) in enumerate(rows):
      record = snapshot.get(tuple(spec))
      if record is not None:
        native_colour = _legacy_user_colour_index_to_coot_index(colour)
        for atom in record["atoms"]:
          name, alt = atom[0][:2]
          atom_rows.append(([mol_id, *spec, name, alt], native_colour))
      if (index + 1) % 200 == 0:
        yield f"Preparing residues: {index + 1}/{len(rows)}", 0.05 + 0.45*(index+1)/len(rows), True
  yield "Applying colours", 0.5, True
  if not valid_model_molecule_qm(mol_id) or _MODEL_EDIT_EPOCHS.get(mol_id, 0) != epoch:
    raise RuntimeError("The model changed while preparing colours; please try again.")
  if snapshot is not None and snapshot != _model_coordinate_snapshot(mol_id):
    raise RuntimeError("The model changed while preparing colours; please try again.")
  # Once assignments start, complete the operation rather than leaving partial colours.
  yield "Applying colours", 0.5, False
  ensure_user_defined_colour_table()
  _clear_custom_colour_additional_representations(mol_id, clear_user_colours=False)
  neutral_rows = _direct_user_defined_blank_rows_for_molecule(mol_id)
  if not _set_user_defined_atom_colour_by_residue_rows_py(mol_id, neutral_rows, palette_ready=True):
    raise RuntimeError("Failed to initialise user-defined atom colours.")
  if snapshot is not None:
    for start in range(0, len(atom_rows), 4096):
      coot.set_user_defined_atom_colour_py(mol_id, atom_rows[start:start+4096])
      count = min(start+4096, len(atom_rows))
      yield f"Colouring atoms: {count}/{len(atom_rows)}", 0.5 + 0.45*count/len(atom_rows), False
  else:
    for start in range(0, len(rows), 64):
      if not _set_user_defined_atom_colour_by_residue_rows_py(mol_id, rows[start:start+64], palette_ready=True):
        raise RuntimeError("Failed to set user-defined atom colours.")
      count = min(start+64, len(rows))
      yield f"Colouring selections: {count}/{len(rows)}", 0.5 + 0.45*count/len(rows), False
  yield "Rebuilding display", 0.98, False
  _graphics_to_legacy_user_defined_representation(mol_id, neutral_rows + rows)
  yield "Colouring complete", 1.0, False
  if info_message:
    info_dialog(info_message)
  return len(rows) + 1


def _apply_direct_user_defined_residue_colours(mol_id, blank_res_list, colour_list, info_message=None):
  return _consume_colour_steps(_iter_direct_user_defined_residue_colours(
    mol_id, blank_res_list, colour_list, info_message))


def _iter_overlay_user_defined_residue_colours(mol_id, blank_res_list, colour_list, info_message=None):
  del blank_res_list
  if not colour_list:
    if info_message:
      info_dialog(info_message)
    return None
  yield "Assigning compatible atom colours", 0.05, False
  _clear_custom_colour_additional_representations(mol_id)
  clear_user_defined_atom_colours(mol_id)
  colour_count = _set_user_defined_atom_colour_by_residue_atoms_py(mol_id, colour_list)
  if not colour_count:
    _clear_custom_colour_additional_representations(mol_id)
    info_dialog("Failed to set user-defined atom colours for the requested residues.")
    return None
  handles = []
  CUSTOM_COLOUR_ADDITIONAL_REPRESENTATIONS[mol_id] = handles
  seen_residue_specs = set()
  yield "Building compatible representations", 0.2, False
  for index, (residue_spec, _colour_index) in enumerate(colour_list):
    residue_key = tuple(residue_spec[:3])
    if residue_key in seen_residue_specs:
      continue
    seen_residue_specs.add(residue_key)
    handle = _make_custom_colour_additional_representation(mol_id, residue_spec)
    if handle is not None:
      handles.append(handle)
    if (index + 1) % 4 == 0:
      yield f"Building representations: {index+1}/{len(colour_list)}", 0.2 + 0.75*(index+1)/len(colour_list), False
  clear_user_defined_atom_colours(mol_id)
  if not handles:
    info_dialog("Failed to create a custom-colour additional representation.")
    return None
  yield "Colouring complete", 1.0, False
  if info_message:
    info_dialog(info_message)
  return handles


def _apply_overlay_user_defined_residue_colours(mol_id, blank_res_list, colour_list, info_message=None):
  return _consume_colour_steps(_iter_overlay_user_defined_residue_colours(
    mol_id, blank_res_list, colour_list, info_message))


def _apply_user_defined_residue_colours(mol_id, blank_res_list, colour_list, info_message=None, defer_apply=False):
  if not defer_apply and _USER_DEFINED_COLOUR_JOB_ACTIVE:
    add_status_bar_text("Please wait for the current colouring operation to finish.")
    return None
  if _supports_direct_user_defined_colouring():
    if defer_apply:
      return _iter_direct_user_defined_residue_colours(mol_id, blank_res_list, colour_list, info_message)
    return _apply_direct_user_defined_residue_colours(
      mol_id,
      blank_res_list,
      colour_list,
      info_message=info_message,
    )
  steps = _iter_overlay_user_defined_residue_colours(mol_id, blank_res_list, colour_list, info_message)
  return steps if defer_apply else _consume_colour_steps(steps)


_USER_DEFINED_COLOUR_JOB_ACTIVE = False


def _start_user_defined_colour_action(mol_id, action, title):
  """Keep native graphics calls on the GTK thread, yielding between batches."""
  global _USER_DEFINED_COLOUR_JOB_ACTIVE
  if _USER_DEFINED_COLOUR_JOB_ACTIVE:
    add_status_bar_text("A colouring operation is already running.")
    return None
  glib = _coot_gui_repository_module("GLib")
  if glib is None or Gtk is None:
    return action(mol_id)
  window = Gtk.Window(title=title)
  window.set_default_size(360, 110)
  box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=8)
  for side in ("top", "bottom", "start", "end"):
    getattr(box, "set_margin_"+side)(12)
  label = Gtk.Label(label="Preparing colouring...")
  bar = Gtk.ProgressBar()
  cancel = Gtk.Button(label="Cancel")
  for widget in (label, bar, cancel):
    box.append(widget)
  window.set_child(box)
  state = {"cancelled": False, "cancellable": True, "iterator": None, "finished": False,
           "applying": False}
  epoch = _MODEL_EDIT_EPOCHS.get(mol_id, 0)
  _USER_DEFINED_COLOUR_JOB_ACTIVE = True
  def cancel_job(*_args):
    if state["cancellable"]:
      state["cancelled"] = True
    return True
  cancel.connect("clicked", cancel_job)
  window.connect("close-request", cancel_job)
  def finish():
    global _USER_DEFINED_COLOUR_JOB_ACTIVE
    if state["finished"]:
      return
    state["finished"] = True
    if state["iterator"] is not None:
      state["iterator"].close()
    _USER_DEFINED_COLOUR_JOB_ACTIVE = False
    window.destroy()
  def step():
    if state["finished"]:
      return False
    if state["cancelled"]:
      finish()
      add_status_bar_text("Colouring cancelled; existing colours retained.")
      return False
    try:
      if not valid_model_molecule_qm(mol_id) or _MODEL_EDIT_EPOCHS.get(mol_id, 0) != epoch:
        raise RuntimeError("The model changed during colouring; please try again.")
      if state["iterator"] is None:
        state["cancellable"] = False
        cancel.set_sensitive(False)
        result = action(mol_id, defer_apply=True)
        if result is None:
          finish()
          return False
        state["iterator"] = iter(result)
      message, fraction, cancellable = next(state["iterator"])
      state["cancellable"] = cancellable
      state["applying"] = state["applying"] or not cancellable
      label.set_text(message)
      cancel.set_sensitive(cancellable)
      if fraction is None:
        bar.pulse()
      else:
        bar.set_fraction(fraction)
      if fraction == 1.0:
        # Dismiss before any colour-key info dialog is presented.
        window.destroy()
      return True
    except StopIteration:
      finish()
      add_status_bar_text("Colouring complete.")
    except Exception as error:
      traceback.print_exc()
      if state["applying"] and valid_model_molecule_qm(mol_id):
        try:
          if not _supports_direct_user_defined_colouring():
            _clear_custom_colour_additional_representations(mol_id)
          _restore_last_standard_representation(mol_id)
        except Exception:
          traceback.print_exc()
      finish()
      info_dialog(f"Colouring stopped: {error}")
    return False
  label.set_text("Calculating colours / scores...")
  bar.pulse()
  window.present()
  # A timed idle-sized batch allows the progress window to paint before native work.
  glib.timeout_add(30, step)
  return window


def color_by_rama_native(mol_id, defer_apply=False):
  rama_results=all_molecule_ramachandran_score(mol_id)
  if not isinstance(rama_results, list) or len(rama_results) < 6:
    info_dialog("Unable to obtain Ramachandran scores.")
    return None
  scored_residues=rama_results[5]
  blank_colour=0
  rama_allowed_colour=27
  rama_outlier_colour=31
  blank_res_list=[]
  rama_colour_list=[]
  for residue_spec in _all_residue_specs_for_colouring(mol_id):
    blank_res_list.append((residue_spec, blank_colour))
  for item in scored_residues:
    if not isinstance(item, list) or len(item) < 3:
      continue
    residue_spec = _coot_residue_spec_from_spec(item[1])
    rama_score=item[2]
    if residue_spec is None:
      continue
    if rama_score < 0.002:
      rama_colour_list.append((list(residue_spec), rama_outlier_colour))
    elif rama_score < 0.02:
      rama_colour_list.append((list(residue_spec), rama_allowed_colour))
  return _apply_user_defined_residue_colours(
    mol_id,
    blank_res_list,
    rama_colour_list,
    "Ramachandran coloring:\n\nRed = outlier (<0.2%)\n\nOrange = allowed/disfavored (<2%)",
    defer_apply=defer_apply,
  )


def color_by_rama_native_for_active_residue():
  mol_id=_active_polymer_molecule_for_colouring("Ramachandran coloring")
  if mol_id is None:
    return None
  return _start_user_defined_colour_action(mol_id, color_by_rama_native, "Ramachandran colouring")


def color_by_density_fit_native(mol_id, defer_apply=False):
  map_id=imol_refinement_map()
  if map_id==-1:
    info_dialog("You need a refinement map for density-fit coloring.")
    return None
  residue_specs=all_residues_sans_water(mol_id)
  if not residue_specs:
    info_dialog("No residues found for density-fit coloring.")
    return None
  correlation_results=map_to_model_correlation_per_residue(mol_id, residue_specs, 0, map_id)
  blank_colour=0
  blank_res_list=[]
  density_colour_list=[]
  for residue_spec in _all_residue_specs_for_colouring(mol_id):
    blank_res_list.append((residue_spec, blank_colour))
  for item in correlation_results:
    if not isinstance(item, (list, tuple)) or len(item) < 2:
      continue
    residue_spec = _coot_residue_spec_from_spec(item[0])
    score=item[1]
    if residue_spec is None:
      continue
    try:
      score=float(score)
    except Exception:
      continue
    if math.isnan(score):
      continue
    colour_index=_density_fit_score_to_colour_index(score)
    density_colour_list.append((list(residue_spec), colour_index))
  return _apply_user_defined_residue_colours(
    mol_id,
    blank_res_list,
    density_colour_list,
    "Active molecule colored by model/map correlation.\n\n"
    + _colour_band_legend_text("CC", 0.0, 1.0),
    defer_apply=defer_apply,
  )


def color_by_density_fit_native_for_active_residue():
  mol_id=_active_polymer_molecule_for_colouring("Density-fit coloring")
  if mol_id is None:
    return None
  return _start_user_defined_colour_action(mol_id, color_by_density_fit_native, "Density-fit colouring")


def _sidechain_density_records(snapshot):
  """Canonical, complete, single-conformer sidechains; retain other rows as breaks/context."""
  distal = dict(ARG="CG CD NE CZ NH1 NH2", ASN="CG OD1 ND2", ASP="CG OD1 OD2",
                CYS="SG", GLN="CG CD OE1 NE2", GLU="CG CD OE1 OE2",
                HIS="CG ND1 CD2 CE1 NE2", ILE="CG1 CG2 CD1", LEU="CG CD1 CD2",
                LYS="CG CD CE NZ", MET="CG SD CE", PHE="CG CD1 CD2 CE1 CE2 CZ",
                PRO="CG CD", SER="OG", THR="OG1 CG2",
                TRP="CG CD1 CD2 NE1 CE2 CE3 CZ2 CZ3 CH2",
                TYR="CG CD1 CD2 CE1 CE2 CZ OH", VAL="CG1 CG2")
  rows = []
  for spec, record in snapshot.items():
    xyz, alternate = {}, False
    for atom in record["atoms"]:
      name, alt = (str(value).strip() for value in atom[0])
      if name.startswith(("H", "D")) or name[:1].isdigit():
        continue
      point = tuple(float(value) for value in atom[2])
      occupancy = float(atom[1][0])
      if occupancy <= 0 or not math.isfinite(occupancy) or len(point) != 3 or not all(map(math.isfinite, point)):
        continue
      alternate = alternate or bool(alt) or name in xyz
      xyz.setdefault(name, point)
    name = str(record["name"]).strip()
    backbone = [xyz[atom] for atom in ("N", "CA", "C", "O") if atom in xyz]
    required = set(distal.get(name, "").split()) | {"CB"}
    rows.append(dict(spec=tuple(spec), name=name, xyz=xyz, backbone=backbone,
                     context=(name in distal or name in ("ALA", "GLY")) and not alternate and len(backbone) == 4,
                     eligible=(name in distal and not alternate and len(backbone) == 4
                               and required.issubset(xyz))))
  return rows


def _sidechain_density_scores(records, backbone_rows, sidechain_rows, densities,
                              window=1, backbone_cc_floor=.35, min_support=.2):
  """Regional density gates confidence; CC is a normalization, not a visibility gate."""
  try:
    width = int(window)
  except (TypeError, ValueError, OverflowError):
    raise ValueError("Window must be an integer from 1 to 25 (1 = per residue).") from None
  if isinstance(window, bool) or width != window or not 1 <= width <= 25:
    raise ValueError("Window must be an integer from 1 to 25 (1 = per residue).")
  window = width
  if not math.isfinite(backbone_cc_floor) or not 0 < backbone_cc_floor <= 1:
    raise ValueError("Backbone CC normalization floor must be greater than 0 and at most 1.")
  if not math.isfinite(min_support) or not 0 <= min_support <= 1:
    raise ValueError("Minimum relative density support must be between 0 and 1.")
  def correlation(rows):
    result = {}
    for item in rows:
      if not isinstance(item, (list, tuple)) or len(item) < 2:
        continue
      spec = _coot_residue_spec_from_spec(item[0])
      try:
        value = float(item[1])
      except (TypeError, ValueError):
        continue
      if spec is not None and math.isfinite(value) and -1.0001 <= value <= 1.0001:
        result[tuple(spec)] = max(-1., min(1., value))
    return result
  bb, sc = correlation(backbone_rows), correlation(sidechain_rows)
  canonical = set("ALA ARG ASN ASP CYS GLN GLU GLY HIS ILE LEU LYS MET PHE PRO SER THR TRP TYR VAL".split())
  values = sorted(float(densities[r["spec"]]) for r in records if r["name"] in canonical
                  and len(r["backbone"]) == 4 and r["spec"] in densities
                  and math.isfinite(densities[r["spec"]]))
  def percentile(fraction):
    if not values:
      return 0.
    position = (len(values)-1)*fraction
    lower = int(position)
    return values[lower] + (values[min(lower+1, len(values)-1)]-values[lower])*(position-lower)
  low, high = percentile(.1), percentile(.9)
  result, segment = [], 0
  previous = None
  for record in records:
    spec = record["spec"]
    # C-N connectivity plus residue ordering: never smooth across chains, gaps or ligands.
    connected = (previous is not None and previous["spec"][0] == spec[0]
                 and previous["name"] in canonical and record["name"] in canonical
                 and ((not spec[2] and not previous["spec"][2] and spec[1] == previous["spec"][1]+1)
                      or (spec[1] == previous["spec"][1] and spec[2] > previous["spec"][2]))
                 and "C" in previous["xyz"] and "N" in record["xyz"]
                 and .25 < sum((a-b)**2 for a, b in zip(previous["xyz"]["C"], record["xyz"]["N"])) <= 2.2**2)
    if not connected:
      segment += 1
    density = densities.get(spec, float("nan"))
    support = (max(0., min(1., (density-low)/(high-low)))
               if high > low and math.isfinite(density) else 0.)
    result.append(dict(spec=spec, segment=segment, backbone_cc=bb.get(spec),
                       sidechain_cc=sc.get(spec), support=support, eligible=record["eligible"],
                       context=record["context"], score=None, deficit=None, count=0,
                       residue_deficit=None, window_deficit=None, window_support=None,
                       confidence_support=None))
    previous = record
  for row in result:
    if row["eligible"] and row["sidechain_cc"] is not None:
      # A low/negative backbone CC can reflect calculated-map shape rather than
      # absent observed density. Avoid both a small denominator and hard masking.
      reference = max(backbone_cc_floor, row["backbone_cc"] or backbone_cc_floor)
      row["residue_deficit"] = max(0., min(1., 1.-row["sidechain_cc"]/reference))
  # For even widths the extra neighbor follows the central residue.
  before, after = (window-1)//2, window//2
  for i, row in enumerate(result):
    if not row["context"]:
      continue
    neighbors = [r for r in result[max(0, i-before):i+after+1]
                 if r["segment"] == row["segment"] and r["context"]]
    support = sum(r["support"] for r in neighbors)/len(neighbors)
    pairs = [r for r in neighbors if r["residue_deficit"] is not None]
    row["window_support"] = support
    row["confidence_support"] = max(row["support"], support)
    if row["confidence_support"] < min_support or not pairs:
      continue
    bb_values = [r["backbone_cc"] for r in pairs if r["backbone_cc"] is not None]
    b = sum(bb_values)/len(bb_values) if bb_values else None
    s = sum(r["sidechain_cc"] for r in pairs)/len(pairs)
    window_deficit = sum(r["residue_deficit"] for r in pairs)/len(pairs)
    # Windows can extend a warning, never conceal the central residue's defect.
    # Gly/Ala have no distal SC CC, but can inherit a genuine regional score.
    deficit = max(row["residue_deficit"] or 0., window_deficit)
    row.update(score=1.-deficit, deficit=deficit, count=len(pairs),
               window_deficit=window_deficit, window_backbone_cc=b, window_sidechain_cc=s)
  return result


def _iter_sidechain_density_colours(mol_id, map_id, window, backbone_cc_floor, min_support):
  snapshot = _model_coordinate_snapshot(mol_id)
  map_identity = _local_em_resolution_identity(map_id)
  def check_map():
    if _local_em_resolution_identity(map_id) != map_identity:
      raise RuntimeError("The refinement map was closed or replaced; please try again.")
  records = _sidechain_density_records(snapshot)
  canonical = set("ALA ARG ASN ASP CYS GLN GLU GLY HIS ILE LEU LYS MET PHE PRO SER THR TRP TYR VAL".split())
  specs = [list(r["spec"]) for r in records if len(r["backbone"]) == 4
           and r["name"] in canonical]
  if not specs:
    raise ValueError("No complete protein backbones found.")
  cache = _analysis_cc_open(map_id)
  try:
    yield "Calculating backbone correlations...", .05, True
    check_map()
    backbone = _analysis_cc_residue_scores(cache, mol_id, specs, 1)
    yield "Calculating sidechain correlations...", .35, True
    check_map()
    sidechain = _analysis_cc_residue_scores(cache, mol_id, specs, 3)
    yield "Measuring backbone density support...", .65, True
    check_map()
    points = [p for r in records for p in r["backbone"]]
    values = _analysis_density_values(map_id, points)
    densities, offset = {}, 0
    for record in records:
      count = len(record["backbone"])
      if count:
        densities[record["spec"]] = sum(values[offset:offset+count])/count
      offset += count
    scores = _sidechain_density_scores(records, backbone, sidechain, densities,
                                      window, backbone_cc_floor, min_support)
  finally:
    _analysis_cc_close(cache)
  yield "Preparing sidechain-fit colours...", .8, True
  check_map()
  if _model_coordinate_snapshot(mol_id) != snapshot or not coot.is_valid_map_molecule(map_id):
    raise RuntimeError("The model or refinement map changed; please try again.")
  blank = [(list(spec), 0) for spec in snapshot]
  colours = [(list(row["spec"]), _density_fit_score_to_colour_index(row["score"]))
             for row in scores if row["score"] is not None]
  legend = ("Sidechain density correlation, normalized to backbone support.\n\n"
            "Red = large sidechain deficit; blue = little/no deficit.\n"
            "Residue deficit = clamp(1 - sidechain CC / max(backbone CC, floor), 0, 1).\n"
            "Distal sidechains exclude C-beta. Window: %d residues; display uses the larger of the residue and window-mean deficits.\n"
            "In window mode, Gly/Ala and incomplete sidechains inherit nearby sidechain evidence.\n"
            "Gray = weak regional density, no usable sidechain evidence, alternate conformers or non-standard residues.\n"
            "Backbone CC floor (not a cutoff): %.2f; minimum regional density support: %.2f.\n"
            "Either central or window-mean backbone density can establish support.\n"
            "Support uses backbone atom density relative to this model's 10th-90th percentiles.\n\n"
            "%d/%d residues scored. This is a mismatch diagnostic, not proof of a register error."
            % (window, backbone_cc_floor, min_support, len(colours), len(scores)))
  yield from _apply_user_defined_residue_colours(mol_id, blank, colours, legend, defer_apply=True)


def color_by_sidechain_density_for_active_residue():
  mol_id = _active_polymer_molecule_for_colouring("Sidechain density-fit colouring")
  if mol_id is None:
    return None
  map_id = imol_refinement_map()
  if not coot.is_valid_map_molecule(map_id):
    info_dialog("Select a refinement map for sidechain density-fit colouring.")
    return None
  if Gtk is None:
    info_dialog("Sidechain density-fit options require GTK.")
    return None
  dialog = Gtk.Window(title="Sidechain density correlation")
  dialog.set_default_size(560, -1)
  box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=10)
  for side in ("top", "bottom", "start", "end"):
    getattr(box, "set_margin_"+side)(12)
  identifier = Gtk.Label(label="Model #%s: %s\nRefinement map #%s: %s" %
                         (mol_id, os.path.basename(coot.molecule_name(mol_id)),
                          map_id, os.path.basename(coot.molecule_name(map_id))))
  identifier.set_xalign(0.)
  identifier.set_wrap(True)
  identifier.set_max_width_chars(68)
  box.append(identifier)
  entries = {}
  for key, label, default in (("window", "Window (1-25, 1 = per residue)", "1"),
                               ("backbone", "Backbone CC normalization floor", "0.35"),
                               ("support", "Minimum regional density support", "0.2")):
    line = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=10)
    line.append(Gtk.Label(label=label))
    entry = Gtk.Entry()
    entry.set_width_chars(6)
    entry.set_max_width_chars(8)
    entry.set_text(default)
    if key == "window":
      entry.set_tooltip_text("Even windows include one extra following residue; e.g. 4 = previous, current, next two.")
    line.append(entry)
    entries[key] = entry
    box.append(line)
  help_text = Gtk.Label(label="Red: sidechains fit worse than a supported backbone. Blue: little/no deficit.\n"
                         "Windows extend highlighting without averaging away an individual mismatch.\n"
                         "Window mode includes Gly/Ala using nearby sidechains; weak regional density is gray.\n"
                         "This can flag register errors, but also incorrect rotamers and other mismatches.")
  help_text.set_xalign(0.)
  help_text.set_wrap(True)
  help_text.set_max_width_chars(68)
  box.append(help_text)
  status = Gtk.Label(label="")
  status.set_wrap(True)
  status.set_max_width_chars(68)
  box.append(status)
  buttons = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=10)
  apply_button, close = Gtk.Button(label="Colour molecule"), Gtk.Button(label="Close")
  buttons.append(apply_button)
  buttons.append(close)
  box.append(buttons)
  dialog.set_child(box)
  model_identity, map_identity = coot.molecule_name(mol_id), _local_em_resolution_identity(map_id)
  def apply(*_args):
    try:
      window = int(entries["window"].get_text())
      backbone = float(entries["backbone"].get_text())
      support = float(entries["support"].get_text())
      _sidechain_density_scores([], [], [], {}, window, backbone, support)
      if (not valid_model_molecule_qm(mol_id) or coot.molecule_name(mol_id) != model_identity
          or _local_em_resolution_identity(map_id) != map_identity):
        raise ValueError("The selected model or map was closed or replaced. Reopen this dialog.")
      def action(model, defer_apply=False):
        steps = _iter_sidechain_density_colours(model, map_id, window, backbone, support)
        return steps if defer_apply else _consume_colour_steps(steps)
      result = _start_user_defined_colour_action(mol_id, action, "Sidechain density-fit colouring")
      if result is not None:
        dialog.destroy()
    except Exception as error:
      status.set_text(str(error))
  apply_button.connect("clicked", apply)
  close.connect("clicked", lambda *_: dialog.destroy())
  dialog.sidechain_density_widgets = dict(entries=entries, apply=apply_button, status=status)
  dialog.present()
  return dialog


def _ncs_difference_scores_from_ghosts(snapshot, ghosts):
  """Mean matched-atom displacement after Coot's peer-to-master NCS transform."""
  chains = {}
  for spec, record in snapshot.items():
    chains.setdefault(spec[0], {})[spec[1:]] = record
  atom_cache = {}
  def atom_positions(spec, record):
    if spec not in atom_cache:
      positions = {}
      for atom in record["atoms"]:
        name, alt = atom[0]
        point = tuple(float(value) for value in atom[2])
        if len(point) == 3 and all(math.isfinite(value) for value in point):
          positions.setdefault((str(name).strip(), str(alt or "").strip()), point)
      atom_cache[spec] = positions
    return atom_cache[spec]
  scores = {}
  seen_pairs = set()
  for ghost in ghosts:
    if not isinstance(ghost, (list, tuple)) or len(ghost) < 4:
      raise ValueError("Coot returned an unrecognised NCS operator.")
    peer, master, operator = ghost[1:4]
    if peer == master or (peer, master) in seen_pairs:
      continue
    if not isinstance(operator, (list, tuple)) or len(operator) != 2:
      raise ValueError("Coot could not calculate an NCS operator.")
    rotation, translation = (tuple(float(v) for v in part) for part in operator)
    if len(rotation) != 9 or len(translation) != 3 or not all(
        math.isfinite(value) for value in rotation + translation):
      raise ValueError("Coot returned an invalid NCS operator.")
    seen_pairs.add((peer, master))
    target_chain = chains.get(master, {})
    for key, record in chains.get(peer, {}).items():
      target = target_chain.get(key)
      name = str(record["name"]).strip().upper()
      if target is None or name in {"HOH", "WAT", "DOD"} or name != str(target["name"]).strip().upper():
        continue
      peer_spec, target_spec = (peer, *key), (master, *key)
      positions = atom_positions(peer_spec, record)
      target_positions = atom_positions(target_spec, target)
      total, count = 0.0, 0
      for atom_key, point in positions.items():
        other = target_positions.get(atom_key)
        if other is None:
          continue
        transformed = [sum(rotation[3*axis+j]*point[j] for j in range(3)) + translation[axis]
                       for axis in range(3)]
        total += math.sqrt(sum((a-b)**2 for a, b in zip(transformed, other)))
        count += 1
      if count:
        mean = total/count
        for spec in (peer_spec, target_spec):
          scores[spec] = max(scores.get(spec, 0.0), mean)
  return scores


def color_by_ncs_difference(mol_id, defer_apply=False):
  if mol_id not in model_molecule_list():
    info_dialog("You need an active model for NCS-difference coloring.")
    return None
  try:
    # ncs_chain_differences_py still slices the old residue-spec layout in
    # recent builds, losing the residue numbers. Read operators instead.
    ghosts = coot.ncs_ghosts_py(mol_id) or []
    if ghosts and any(not ghost[3] for ghost in ghosts):
      coot.make_ncs_ghosts_maybe(mol_id)
      ghosts = coot.ncs_ghosts_py(mol_id) or []
    if not ghosts:
      info_dialog("No NCS-related chain pairs were found for the active molecule.")
      return None
    snapshot = _model_coordinate_snapshot(mol_id)
    ncs_scores = _ncs_difference_scores_from_ghosts(snapshot, ghosts)
  except Exception as error:
    print("NCS-difference coloring failed:")
    traceback.print_exc()
    info_dialog(f"Could not calculate NCS differences: {error}")
    return None
  if not ncs_scores:
    info_dialog("NCS chains were found, but no matching residues/atoms could be compared.")
    return None

  blank_res_list = [(list(spec), 0) for spec in snapshot]

  ncs_colour_list=[]
  for residue_spec, mean_diff in ncs_scores.items():
    normalized_score=mean_diff/2.0
    if normalized_score < 0.0:
      normalized_score=0.0
    if normalized_score > 1.0:
      normalized_score=1.0
    colour_index=int(normalized_score*31+2)
    ncs_colour_list.append(([residue_spec[0], residue_spec[1], residue_spec[2]], colour_index))

  return _apply_user_defined_residue_colours(
    mol_id,
    blank_res_list,
    ncs_colour_list,
    "Active molecule colored by NCS difference.\n"
    "Mean matched-atom displacement after NCS superposition; each master residue shows its largest peer difference.\n"
    "Spectral scale: blue=0.0 A, red=2.0 A or greater; gray=not compared.",
    defer_apply=defer_apply,
  )


def color_by_ncs_difference_for_active_residue():
  mol_id=_active_polymer_molecule_for_colouring("NCS-difference coloring")
  if mol_id is None:
    return None
  return _start_user_defined_colour_action(mol_id, color_by_ncs_difference, "NCS-difference colouring")


def color_by_clash_score(mol_id, defer_apply=False):
  if mol_id not in model_molecule_list():
    info_dialog("You need an active model for clash coloring.")
    return None
  try:
    overlap_data=molecule_atom_overlaps(mol_id, -1)
  except TypeError:
    try:
      overlap_data=molecule_atom_overlaps(mol_id)
    except Exception:
      overlap_data=False
  except Exception:
    overlap_data=False
  if not isinstance(overlap_data, list):
    info_dialog("No clash data were available for the active molecule.")
    return None

  blank_colour=0
  blank_res_list=[]
  max_overlap_by_residue={}

  for residue_spec in _all_residue_specs_for_colouring(mol_id):
    blank_res_list.append((residue_spec, blank_colour))

  def accumulate_overlap_from_atom_spec(atom_spec, overlap_value):
    if not isinstance(atom_spec, list):
      return
    try:
      residue_spec=atom_spec_to_residue_spec(atom_spec)
    except Exception:
      return
    if not isinstance(residue_spec, list) or len(residue_spec) < 3:
      return
    residue_key=(residue_spec_to_chain_id(residue_spec),
                 residue_spec_to_res_no(residue_spec),
                 residue_spec_to_ins_code(residue_spec))
    previous_max=max_overlap_by_residue.get(residue_key, 0.0)
    if overlap_value > previous_max:
      max_overlap_by_residue[residue_key]=overlap_value

  for overlap_item in overlap_data:
    if not isinstance(overlap_item, dict):
      continue
    try:
      overlap_value=float(overlap_item.get('overlap-volume', 0.0))
    except Exception:
      continue
    atom_spec_1=overlap_item.get('atom-1-spec')
    atom_spec_2=overlap_item.get('atom-2-spec')
    accumulate_overlap_from_atom_spec(atom_spec_1, overlap_value)
    accumulate_overlap_from_atom_spec(atom_spec_2, overlap_value)

  if not max_overlap_by_residue:
    info_dialog("No clash data were available for the active molecule.")
    return None

  clash_colour_list=[]
  for residue_spec, max_overlap in max_overlap_by_residue.items():
    normalized_score=max_overlap/2.0
    if normalized_score < 0.0:
      normalized_score=0.0
    if normalized_score > 1.0:
      normalized_score=1.0
    colour_index=_density_fit_score_to_colour_index(1.0-normalized_score)
    clash_colour_list.append(([residue_spec[0], residue_spec[1], residue_spec[2]], colour_index))

  return _apply_user_defined_residue_colours(
    mol_id,
    blank_res_list,
    clash_colour_list,
    "Active molecule colored by per-residue maximum clash overlap.\n\n"
    + _colour_band_legend_text("overlap", 0.0, 2.0, reverse=True),
    defer_apply=defer_apply,
  )


def color_by_clash_score_for_active_molecule():
  mol_id=_active_molecule_or_status()
  if mol_id is None:
    return None
  return _start_user_defined_colour_action(mol_id, color_by_clash_score, "Clash colouring")

