# Sequence-register editing groups native backups and preserves rotamer settings.
_REGISTER_AA = dict(zip("ARNDCQEGHILKMFPSTWYV", (
  "ALA", "ARG", "ASN", "ASP", "CYS", "GLN", "GLU", "GLY", "HIS", "ILE",
  "LEU", "LYS", "MET", "PHE", "PRO", "SER", "THR", "TRP", "TYR", "VAL")))
_REGISTER_PROTEIN_NAMES = set(_REGISTER_AA.values()) | {"MSE", "UNK"}


def _register_clean_sequence(text):
  lines = str(text).strip().splitlines()
  if sum(line.lstrip().startswith(">") for line in lines) > 1:
    raise ValueError("Supply one sequence, not multiple FASTA records.")
  sequence = "".join("".join(line.split()) for line in lines if not line.lstrip().startswith(">")).upper()
  if not sequence or set(sequence) - (set(_REGISTER_AA) | {"X"}):
    raise ValueError("Use a protein sequence or single FASTA record. Gaps, stop symbols and nonstandard letters are unsupported; X is allowed outside the target region.")
  return sequence


def _register_chain_snapshot(mol_id, chain_id):
  if not valid_model_molecule_qm(mol_id):
    raise ValueError("The target model is no longer available.")
  if coot.n_models(mol_id) != 1:
    raise ValueError("Register shifting currently requires a single-model molecule.")
  records = []
  for ch, number, ins in _all_residue_specs_for_colouring(mol_id):
    if ch != chain_id:
      continue
    atoms = coot.residue_info_py(mol_id, ch, number, ins) or []
    signature = tuple(sorted((a[0][0], a[0][1], tuple(float(x) for x in a[2]), repr(a[1])) for a in atoms))
    alternatives = sorted({a[0][1] for a in atoms if a[0][1]})
    preferred = max(alternatives, key=lambda alt: sum(float(a[1][0]) for a in atoms if a[0][1] == alt) /
                    sum(a[0][1] == alt for a in atoms)) if alternatives else ""
    shared = {a[0][0] for a in atoms if not a[0][1]}
    backbone = {a[0][0].strip(): tuple(float(x) for x in a[2]) for a in atoms
                if a[0][0].strip() in {"N", "CA", "C", "O"} and
                (not a[0][1] or (a[0][1] == preferred and a[0][0] not in shared))}
    records.append({"number": number, "ins": ins, "name": residue_name(mol_id, ch, number, ins).strip(),
                    "alt": any(bool(a[0][1]) for a in atoms), "backbone": backbone, "atoms": signature})
  return sorted(records, key=lambda r: (r["number"], r["ins"]))


def _register_connected(left, right):
  if (left["name"] not in _REGISTER_PROTEIN_NAMES or right["name"] not in _REGISTER_PROTEIN_NAMES
      or left["ins"] or right["ins"] or right["number"] != left["number"] + 1):
    return False
  carbon, nitrogen = left["backbone"].get("C"), right["backbone"].get("N")
  return carbon is not None and nitrogen is not None and sum((a-b)**2 for a, b in zip(carbon, nitrogen)) <= 2.2**2


def _register_plan(records, start, end, offset, sequence, sequence_start):
  """Pure preflight: trim only the nearest neighbour's overlapping terminus."""
  start, end = sorted((int(start), int(end)))
  offset, sequence_start = int(offset), int(sequence_start)
  if not offset:
    raise ValueError("Enter a nonzero register shift; +2 means residue 100 becomes 102.")
  sequence = _register_clean_sequence(sequence)
  selected = [r for r in records if start <= r["number"] <= end]
  if [r["number"] for r in selected] != list(range(start, end+1)):
    raise ValueError("The selected range must have unique consecutive residue numbers, with no missing residues or insertion codes.")
  for r in selected:
    if r["ins"] or r["name"] not in _REGISTER_PROTEIN_NAMES or set(r["backbone"]) != {"N", "CA", "C", "O"}:
      raise ValueError("The selected range requires protein residues with complete N/CA/C/O atoms and no insertion codes.")
  if any(not _register_connected(a, b) for a, b in zip(selected, selected[1:])):
    raise ValueError("The selected range crosses a backbone break. Select a single connected region.")
  first, last = start+offset, end+offset
  if first < sequence_start or last >= sequence_start+len(sequence):
    raise ValueError("The shifted region is outside the supplied sequence numbering. Check the sequence's first residue number.")
  target = sequence[first-sequence_start:last-sequence_start+1]
  if set(target) - set(_REGISTER_AA):
    raise ValueError("The target region contains X; specify those residue identities before shifting.")
  outsiders = [r for r in records if not start <= r["number"] <= end]
  trim = [r for r in outsiders if first <= r["number"] <= last]
  if trim:
    side = [r for r in records if r["number"] > end] if offset > 0 else [r for r in records if r["number"] < start]
    if offset < 0:
      side = list(reversed(side))
    neighbour = []
    for r in side:
      if neighbour:
        a, b = (neighbour[-1], r) if offset > 0 else (r, neighbour[-1])
        if not _register_connected(a, b):
          break
      neighbour.append(r)
    trimmed_numbers = {(r["number"], r["ins"]) for r in trim}
    prefix = neighbour[:len(trim)]
    if trimmed_numbers != {(r["number"], r["ins"]) for r in prefix}:
      raise ValueError("The shift collides with more than the adjacent region's terminus.")
    if len(trim) >= len(neighbour):
      raise ValueError("The shift would delete the entire neighbouring region. Use a smaller shift or handle that region separately.")
    if any(r["ins"] or r["name"] not in _REGISTER_PROTEIN_NAMES for r in trim):
      raise ValueError("Overlaps involving ligands or insertion codes cannot be trimmed automatically.")
  remaining = [r for r in outsiders if r not in trim]
  if any((r["number"] < start and r["number"] >= first) or
         (r["number"] > end and r["number"] <= last) for r in remaining):
    raise ValueError("The shift would move the region past another residue or fragment.")
  changes = []
  for r, letter in zip(selected, target):
    new_name = _REGISTER_AA[letter]
    equivalent = r["name"] == new_name or (r["name"] == "MSE" and new_name == "MET")
    changes.append((r["number"], r["number"]+offset, r["name"], r["name"] if equivalent else new_name, not equivalent or r["alt"]))
  return {"start": start, "end": end, "offset": offset, "target": target,
          "sequence": sequence, "sequence_start": sequence_start, "trim": trim, "changes": changes,
          "snapshot": records, "selected": selected}


def _register_preview_text(plan, map_id):
  reverse = {value: key for key, value in _REGISTER_AA.items()}
  old = "".join(reverse.get(r["name"], "M" if r["name"] == "MSE" else "X") for r in plan["selected"])
  first, last = plan["start"]+plan["offset"], plan["end"]+plan["offset"]
  changed = sum(c[4] for c in plan["changes"])
  text = [f"{plan['start']}-{plan['end']}  ->  {first}-{last}    ({plan['offset']:+d})", "",
          f"Before  {plan['start']}-{old}-{plan['end']}",
          f"After   {first}-{plan['target']}-{last}", "",
          f"Rebuild/fit: {changed} of {len(plan['selected'])} residues | Map #{map_id}",
          "Delete: " + (", ".join(f"{r['number']} {r['name']}" for r in plan["trim"]) or "none"),
          "", "Current rotamer/backrub settings apply.",
          "Vacated positions stay gaps. One Undo restores the whole shift."]
  collapsed = [str(r["number"]) for r in plan["selected"] if r["alt"]]
  if collapsed:
    text.insert(7, "Altlocs -> single rotamer: " + ", ".join(collapsed))
  return "\n".join(text)


def _register_collapse_alternates(mol_id, chain_id, number):
  atoms = coot.residue_info_py(mol_id, chain_id, number, "") or []
  alternatives = sorted({a[0][1] for a in atoms if a[0][1]})
  if not alternatives:
    return
  preferred = max(alternatives, key=lambda alt: sum(float(a[1][0]) for a in atoms if a[0][1] == alt) /
                  sum(a[0][1] == alt for a in atoms))
  shared = {a[0][0] for a in atoms if not a[0][1]}
  occupancy = {}
  for atom in atoms:
    occupancy[atom[0][0]] = occupancy.get(atom[0][0], 0.0) + float(atom[1][0])
  for atom in atoms:
    name, alt = atom[0]
    if alt and (alt != preferred or name in shared):
      coot.delete_atom(mol_id, chain_id, number, "", name, alt)
  for atom in atoms:
    name, alt = atom[0]
    if alt == preferred and name not in shared:
      # Native implementations can return 0 even after successfully editing.
      coot.set_atom_string_attribute(mol_id, chain_id, number, "", name, alt, "alt-conf", "")
      updated = coot.residue_info_py(mol_id, chain_id, number, "") or []
      if not any(a[0][0] == name and not a[0][1] for a in updated) or any(
          a[0][0] == name and a[0][1] == alt for a in updated):
        raise RuntimeError(f"Could not clear alternate identifier for {number}:{name}.")
      coot.set_atom_attribute(mol_id, chain_id, number, "", name, "", "occ", min(1.0, occupancy[name]))
  remaining = coot.residue_info_py(mol_id, chain_id, number, "") or []
  if any(a[0][1] for a in remaining) or len({a[0][0] for a in remaining}) != len(remaining):
    raise RuntimeError(f"Could not safely collapse alternate conformers for residue {number}.")


def _apply_register_shift(mol_id, chain_id, plan, map_id, anchor_number=None):
  global NAVIGATION_LAST_RESIDUE
  try:
    if _register_chain_snapshot(mol_id, chain_id) != plan["snapshot"]:
      raise ValueError("The chain changed after preview. Preview again before applying.")
    if map_id not in map_molecule_list():
      raise ValueError("The selected refinement map is no longer available.")
    if coot.backup_state(mol_id) != 1:
      raise ValueError("Enable Coot backups for this molecule before shifting its register.")
  except (ValueError, TypeError) as error:
    info_dialog(str(error))
    return False
  failed_fits = []
  stage = "backup preparation"
  try:
    # One native history entry covers trimming, renumbering and sidechain edits.
    coot.make_backup(mol_id)
    coot.turn_off_backup(mol_id)
    stage = "trimming"
    for r in plan["trim"]:
      coot.delete_residue(mol_id, chain_id, r["number"], r["ins"])
      if coot.residue_info_py(mol_id, chain_id, r["number"], r["ins"]):
        raise RuntimeError(f"Coot could not delete overlapping residue {r['number']}.")
    stage = "renumbering"
    if not coot.renumber_residue_range(mol_id, chain_id, plan["start"], plan["end"], plan["offset"]):
      raise RuntimeError("Coot rejected renumbering.")
    stage = "mutation/autofitting"
    for old_no, new_no, old_name, new_name, changed in plan["changes"]:
      if changed:
        _register_collapse_alternates(mol_id, chain_id, new_no)
        if not coot.mutate(mol_id, chain_id, new_no, "", new_name):
          raise RuntimeError(f"Coot could not mutate residue {new_no} to {new_name}.")
        if new_name not in {"ALA", "GLY"}:
          score = coot.auto_fit_best_rotamer(mol_id, chain_id, new_no, "", "", map_id, 1, 0.3)
          if not isinstance(score, (int, float)) or not math.isfinite(score) or score <= -999:
            failed_fits.append(new_no)
  except Exception as error:
    NAVIGATION_LAST_RESIDUE = None
    info_dialog(f"Register shift stopped during {stage}. Earlier edits remain; use Coot Undo to recover.\n\n{error}")
    return False
  finally:
    coot.turn_on_backup(mol_id)
    _mark_model_changed(mol_id)
  NAVIGATION_LAST_RESIDUE = None
  destination = (anchor_number if anchor_number is not None and plan["start"] <= anchor_number <= plan["end"] else plan["start"]) + plan["offset"]
  coot.set_go_to_atom_molecule(mol_id)
  coot.set_go_to_atom_chain_residue_atom_name_full(chain_id, destination, "", " CA ", "")
  message = f"Shifted {chain_id}:{plan['start']}-{plan['end']} by {plan['offset']:+d}; trimmed {len(plan['trim'])}, mutated {sum(c[4] for c in plan['changes'])}."
  print(message)
  add_status_bar_text(_navigation_status_bar_label(mol_id, chain_id, destination, "") + " | " + message)
  if failed_fits:
    info_dialog(message + "\n\nRotamer fitting could not complete for: " + ", ".join(map(str, failed_fits)))
  return True


def _register_sequence_origin(records, sequence):
  """Infer a numbering offset only from a strong, unique identity match."""
  sequence = _register_clean_sequence(sequence)
  reverse = {value: key for key, value in _REGISTER_AA.items()}
  reverse["MSE"] = "M"
  known = [(r["number"], reverse[r["name"]]) for r in records
           if not r["ins"] and r["name"] in reverse]
  if len(known) < 3:
    return None
  candidates = set()
  for triple in zip(known, known[1:], known[2:]):
    if triple[2][0] != triple[0][0] + 2 or triple[1][0] != triple[0][0] + 1:
      continue
    motif = "".join(letter for _, letter in triple)
    position = sequence.find(motif)
    while position >= 0:
      candidates.add(triple[0][0] - position)
      position = sequence.find(motif, position + 1)
  scores = [(sum(0 <= number-origin < len(sequence) and sequence[number-origin] == letter
                 for number, letter in known), origin) for origin in candidates]
  scores.sort(reverse=True)
  if not scores or scores[0][0] < max(3, 0.8 * len(known)):
    return None
  if len(scores) > 1 and scores[0][0] == scores[1][0]:
    return None
  return scores[0][1]


def _register_reference_sequence(mol_id, chain_id, records):
  """Prefer reference sequence; coordinates are a last-resort, numbered fallback."""
  getter = getattr(coot, "sequence_info_py", None)
  if callable(getter):
    associated = [item[1] for item in getter(mol_id) or [] if len(item) == 2 and item[0] == chain_id]
    if len(associated) == 1 and associated[0]:
      return _register_clean_sequence(associated[0]), "Chain-associated reference sequence loaded."
  path = _annotation_source_path(mol_id)
  if path:
    names = []
    with open(path, encoding="utf-8", errors="replace") as handle:
      for line in handle:
        if line.startswith("SEQRES") and line[11:12].strip() == chain_id:
          names.extend(line[19:70].split())
    if names:
      reverse = {value: key for key, value in _REGISTER_AA.items()}
      reverse["MSE"] = "M"
      return "".join(reverse.get(name, "X") for name in names), "PDB SEQRES reference sequence loaded."
  reverse = {value: key for key, value in _REGISTER_AA.items()}
  reverse["MSE"] = "M"
  numbered = {r["number"]: reverse[r["name"]] for r in records
              if not r["ins"] and r["name"] in reverse}
  if numbered and max(numbered)-min(numbered) < 100000:
    return "".join(numbered.get(i, "X") for i in range(min(numbered), max(numbered)+1)), (
      "Model-derived sequence loaded (not an independent reference). Missing positions are X; paste a reference if existing identities are wrong.")
  return "", "Paste the reference sequence or a single FASTA record."


def _register_shift_model_signature(mol_id):
  """Guard native Undo, allowing the precision of Coot's PDB backups."""
  digest = hashlib.sha256()
  def rounded(value, digits):
    value = round(float(value), digits)
    return value if value else 0.0
  def b_factor(value):
    if isinstance(value, (list, tuple)):
      # Coot represents anisotropic data as [B, U11, ...]; PDB Uij has 4 decimals.
      return tuple(rounded(v, 2 if index == 0 else 4) for index, v in enumerate(value))
    return rounded(value, 2)
  for spec, record in sorted(_model_coordinate_snapshot(mol_id).items()):
    atoms = sorted((a[0][0], a[0][1], rounded(a[1][0], 2), b_factor(a[1][1]),
                    str(a[1][2]).strip(), tuple(rounded(x, 3) for x in a[2]))
                   for a in record["atoms"])
    digest.update(repr((spec, record["name"], atoms)).encode("utf-8"))
  return digest.digest()


def _register_shift_dialog(mol_id, chain_id, start, end, anchor_number=None, selection_cleanup=None):
  required = ("n_models", "residue_info_py", "renumber_residue_range", "delete_residue", "mutate",
              "auto_fit_best_rotamer", "backup_state", "make_backup", "turn_off_backup", "turn_on_backup",
              "delete_atom", "set_atom_string_attribute",
              "set_atom_attribute", "set_go_to_atom_molecule",
              "set_go_to_atom_chain_residue_atom_name_full")
  missing = [name for name in required if not callable(getattr(coot, name, None))]
  if missing or globals().get("Gtk") is None:
    if selection_cleanup:
      selection_cleanup()
    info_dialog("Register shift is unavailable in this build. " + ", ".join(missing))
    return
  records = _register_chain_snapshot(mol_id, chain_id)
  default_sequence, sequence_message = _register_reference_sequence(mol_id, chain_id, records)
  origin = None
  if default_sequence:
    try:
      origin = _register_sequence_origin(records, default_sequence)
      if sequence_message.startswith("Model-derived"):
        origin = min(r["number"] for r in records if not r["ins"] and r["name"] in _REGISTER_PROTEIN_NAMES - {"UNK"})
    except (ValueError, TypeError):
      pass
  window = Gtk.Window()
  def close_dialog(*_args):
    if selection_cleanup:
      selection_cleanup()
    window.destroy()
  def closing(*_args):
    if selection_cleanup:
      selection_cleanup()
    return False
  window.connect("close-request", closing)
  region = {"start": min(start, end), "end": max(start, end), "anchor": anchor_number}
  history = []
  def update_title():
    window.set_title(f"Shift register: molecule #{mol_id}, {chain_id}:{region['start']}-{region['end']}")
  update_title()
  window.set_default_size(620, 440)
  box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=8)
  for side in ("start", "end", "top", "bottom"):
    getattr(box, "set_margin_" + side)(12)
  source = ("PDB SEQRES" if sequence_message.startswith("PDB") else
            "Model-derived (verify identities)" if sequence_message.startswith("Model-derived") else
            "Associated sequence" if default_sequence else "Reference sequence required")
  needs_sequence_input = not default_sequence or origin is None or sequence_message.startswith("Model-derived")
  note = Gtk.Label(label=source)
  note.set_tooltip_text(sequence_message + "\nPositive shift: 100 + 2 becomes 102.")
  note.set_wrap(True)
  note.set_xalign(0)
  box.append(note)
  entries = []
  origin_row = None
  for label, value in (("Shift (+/-)", "1"), ("Sequence starts at", str(origin) if origin is not None else "")):
    row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
    row.append(Gtk.Label(label=label))
    entry = Gtk.Entry()
    entry.set_text(value)
    row.append(entry)
    entries.append(entry)
    if label == "Sequence starts at":
      origin_row = row
    else:
      box.append(row)
  sequence_view = Gtk.TextView()
  sequence_view.set_wrap_mode(Gtk.WrapMode.WORD_CHAR)
  sequence_view.get_buffer().set_text(default_sequence)
  sequence_scroll = Gtk.ScrolledWindow()
  sequence_scroll.set_min_content_height(110)
  sequence_scroll.set_child(sequence_view)
  reference = Gtk.Expander(label="Reference sequence needs verification")
  reference.set_visible(needs_sequence_input)
  reference.set_expanded(needs_sequence_input)
  sequence_controls = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=6)
  sequence_controls.append(origin_row)
  sequence_controls.append(sequence_scroll)
  reference.set_child(sequence_controls)
  box.append(reference)
  detail = Gtk.TextView()
  detail.set_editable(False)
  detail.set_monospace(True)
  detail.set_wrap_mode(Gtk.WrapMode.NONE)
  detail_scroll = Gtk.ScrolledWindow()
  detail_scroll.set_vexpand(True)
  detail_scroll.set_child(detail)
  box.append(detail_scroll)
  buttons = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
  apply_button = Gtk.Button(label="Apply register shift")
  apply_button.set_sensitive(False)
  undo_button = Gtk.Button(label="Undo")
  undo_button.set_sensitive(False)
  preview_button = Gtk.Button(label="Preview")
  undo_available = all(callable(getattr(coot, name, None)) for name in ("set_undo_molecule", "apply_undo"))
  undo_button.set_tooltip_text("Undo the last shift in this dialog, including trimmed residues."
                               if undo_available else "Native Undo is unavailable in this Coot build.")
  state = {}
  blocked = False
  def invalidate(*_args):
    state.clear()
    apply_button.set_sensitive(False)
    detail.get_buffer().set_text("Preview required after changing sequence or numbering.")
  for entry in entries:
    entry.connect("changed", invalidate)
  sequence_view.get_buffer().connect("changed", invalidate)
  def preview(*_args):
    invalidate()
    try:
      if blocked:
        raise ValueError("Reopen the shift dialog before making further edits.")
      if history and not history[-1]["success"]:
        raise ValueError("Undo the incomplete shift before trying another register.")
      pending = getattr(coot, "get_continue_updating_refinement_atoms_state", None)
      if callable(pending) and pending():
        raise ValueError("Accept or cancel the current refinement before shifting registers.")
      buffer = sequence_view.get_buffer()
      sequence = buffer.get_text(buffer.get_start_iter(), buffer.get_end_iter(), False)
      snapshot = _register_chain_snapshot(mol_id, chain_id)
      offset = int(entries[0].get_text())
      try:
        clean = _register_clean_sequence(sequence)
        sequence_start = int(entries[1].get_text())
        first, last = region["start"]+offset, region["end"]+offset
        if first < sequence_start or last >= sequence_start+len(clean):
          raise ValueError("The shifted range is outside the reference sequence. Check the sequence and its start.")
        if set(clean[first-sequence_start:last-sequence_start+1]) - set(_REGISTER_AA):
          raise ValueError("The target sequence has unknown residues; enter their identities.")
      except (ValueError, TypeError):
        reference.set_visible(True)
        reference.set_expanded(True)
        raise
      plan = _register_plan(snapshot, region["start"], region["end"], offset, clean, sequence_start)
      map_id = imol_refinement_map()
      if map_id not in map_molecule_list():
        raise ValueError("Select a refinement map in Coot before previewing.")
      state.update(plan=plan, map_id=map_id)
      detail.get_buffer().set_text(_register_preview_text(plan, map_id))
      apply_button.set_sensitive(True)
    except (ValueError, TypeError) as error:
      detail.get_buffer().set_text(str(error))
  def apply(*_args):
    if not state:
      return
    plan, map_id = state["plan"], state["map_id"]
    invalidate()
    try:
      before = _register_shift_model_signature(mol_id)
      try:
        success = _apply_register_shift(mol_id, chain_id, plan, map_id, region["anchor"])
      except Exception as error:
        traceback.print_exc()
        success = False
        info_dialog("Register shift stopped; Undo any partial edits.\n\n" + str(error))
      after = _register_shift_model_signature(mol_id)
      if after != before:
        history.append({"before": before, "after": after, "region": dict(region), "success": success})
      undo_button.set_sensitive(bool(history) and undo_available)
      if success:
        region["start"] += plan["offset"]
        region["end"] += plan["offset"]
        if region["anchor"] is not None:
          region["anchor"] += plan["offset"]
        update_title()
        if selection_cleanup:
          selection_cleanup()
        detail.get_buffer().set_text("Applied. Undo to try from the previous register, or preview another shift.\n\n" +
                                     _register_preview_text(plan, map_id))
      else:
        detail.get_buffer().set_text("Shift not completed. Undo any partial edits before trying again.")
    except Exception as error:
      traceback.print_exc()
      detail.get_buffer().set_text(str(error))

  def undo(*_args):
    global NAVIGATION_LAST_RESIDUE
    nonlocal blocked
    if not history or not undo_available:
      return
    invalidate()
    try:
      if not valid_model_molecule_qm(mol_id):
        raise ValueError("The model has been closed.")
      displayed = getattr(coot, "mol_is_displayed", None)
      if callable(displayed) and not displayed(mol_id):
        raise ValueError("Display this model before undoing its register shift.")
      modified = getattr(coot, "have_unsaved_changes_p", None)
      if callable(modified) and modified(mol_id) != 1:
        raise ValueError("This model has no pending edits to undo.")
      pending = getattr(coot, "get_continue_updating_refinement_atoms_state", None)
      if callable(pending) and pending():
        raise ValueError("Accept or cancel the current refinement before undoing.")
      if _register_shift_model_signature(mol_id) != history[-1]["after"]:
        raise ValueError("The model changed outside this dialog. Use Coot's Undo for those edits first.")
      coot.set_undo_molecule(mol_id)
      if coot.apply_undo() != 1:
        raise ValueError("Coot could not undo this shift; check that the model is displayed and its backups are available.")
      _mark_model_changed(mol_id)
      NAVIGATION_LAST_RESIDUE = None
      restored = _register_shift_model_signature(mol_id)
      if restored != history[-1]["before"]:
        history.clear()
        blocked = True
        undo_button.set_sensitive(False)
        raise ValueError("Undo restored a different model state. Reopen the shift dialog before making further edits.")
      region.update(history.pop()["region"])
      update_title()
      undo_button.set_sensitive(bool(history))
      if selection_cleanup:
        selection_cleanup()
      destination = region["anchor"] if region["anchor"] is not None else region["start"]
      coot.set_go_to_atom_molecule(mol_id)
      coot.set_go_to_atom_chain_residue_atom_name_full(chain_id, destination, "", " CA ", "")
      add_status_bar_text(f"Undid register shift | {chain_id}:{region['start']}-{region['end']}")
      preview()
    except Exception as error:
      traceback.print_exc()
      detail.get_buffer().set_text(str(error))

  for label, action in (("Close", close_dialog), ("Preview", preview), ("Undo", undo)):
    if label == "Undo":
      button = undo_button
    elif label == "Preview":
      button = preview_button
    else:
      button = Gtk.Button(label=label)
    button.connect("clicked", action)
    buttons.append(button)
  apply_button.connect("clicked", apply)
  buttons.append(apply_button)
  box.append(buttons)
  window.set_child(box)
  window.present()
  window.register_shift_widgets = {"shift": entries[0], "origin": entries[1], "sequence": sequence_view,
                                   "reference": reference, "detail": detail, "apply": apply_button,
                                   "undo": undo_button, "preview": preview_button, "region": region}
  preview()
  return window


def shift_register_active_segment():
  active = _active_residue_or_status()
  if not active:
    return
  mol_id, chain_id, number, ins = active[:4]
  try:
    records = _register_chain_snapshot(mol_id, chain_id)
    index = next(i for i, r in enumerate(records) if r["number"] == number and r["ins"] == ins)
    left = right = index
    while left > 0 and _register_connected(records[left-1], records[left]):
      left -= 1
    while right+1 < len(records) and _register_connected(records[right], records[right+1]):
      right += 1
    _register_shift_dialog(mol_id, chain_id, records[left]["number"], records[right]["number"], number)
  except (ValueError, StopIteration) as error:
    info_dialog(f"Cannot select the active segment.\n\n{error}")


_REGISTER_SELECTION_MARKERS = []
_REGISTER_SELECTION_TOKEN = None


def _clear_register_selection_markers():
  had_markers = bool(_REGISTER_SELECTION_MARKERS)
  while _REGISTER_SELECTION_MARKERS:
    obj = _REGISTER_SELECTION_MARKERS.pop()
    try:
      coot.close_generic_object(obj)
    except Exception as error:
      print("Could not clear register endpoint marker:", error)
  draw = getattr(coot, "graphics_draw", None)
  if had_markers and callable(draw):
    draw()


def _mark_register_endpoint(spec, colour, markers=None, label="Register range endpoint"):
  markers = _REGISTER_SELECTION_MARKERS if markers is None else markers
  required = ("new_generic_object_number", "to_generic_object_add_point",
              "set_display_generic_object", "close_generic_object")
  if any(not callable(getattr(coot, name, None)) for name in required):
    return
  atoms = coot.residue_info_py(_click_spec_imol(spec), _click_spec_chain_id(spec),
                               _click_spec_res_no(spec), _click_spec_ins_code(spec)) or []
  candidates = []
  for name in ("CA", "C4'", "C4*", "P"):
    candidates = [a for a in atoms if a[0][0].strip() == name]
    if candidates:
      break
  if not candidates:
    return
  atom = max(candidates, key=lambda a: (not bool(a[0][1]), float(a[1][0])))
  obj = coot.new_generic_object_number(label)
  markers.append(obj)
  try:
    coot.to_generic_object_add_point(obj, colour, 8, *atom[2])
    coot.set_display_generic_object(obj, 1)
    draw = getattr(coot, "graphics_draw", None)
    if callable(draw):
      draw()
  except Exception as error:
    print("Could not draw register endpoint marker:", error)
    coot.close_generic_object(obj)
    markers.remove(obj)


def shift_register_clicked_range():
  global _REGISTER_SELECTION_TOKEN
  _clear_register_selection_markers()
  token = object()
  _REGISTER_SELECTION_TOKEN = token
  def cleanup():
    if _REGISTER_SELECTION_TOKEN is token:
      _clear_register_selection_markers()
  def show_click(spec, prompt):
    add_status_bar_text(_navigation_status_bar_label(
      _click_spec_imol(spec), _click_spec_chain_id(spec),
      _click_spec_res_no(spec), _click_spec_ins_code(spec)).replace("Current residue:", "Clicked residue:", 1) + " | " + prompt)
  def clicked(first, last):
    if _click_spec_ins_code(first) or _click_spec_ins_code(last):
      cleanup()
      info_dialog("Insertion-code endpoints are unsupported for register shifting.")
      return
    region = _clicked_same_chain_residue_range(first, last)
    if region:
      try:
        _register_shift_dialog(*region, anchor_number=_click_spec_res_no(first),
                               selection_cleanup=cleanup)
      except Exception:
        cleanup()
        raise
    else:
      cleanup()
  def show_endpoint(spec, index):
    show_click(spec, "Click the end residue (orange). Tab cancels." if index == 1 else "Range selected")
    _mark_register_endpoint(spec, "cyan" if index == 1 else "orange")
  _script_user_defined_click(2, clicked, on_pick=show_endpoint, cleanup=cleanup,
    prompt="Shift register: click start (cyan), then end (orange). Tab cancels.")


_REGISTER_REFERENCE_ORIGINS = {}


def _register_associate_reference(fragment, chain, sequence, origin):
  sequence = _register_clean_sequence(sequence)
  origin = int(origin) if origin is not None else None
  before = coot.sequence_info_py(fragment) or []
  # Some builds remove only the first matching association per call.
  for _ in range(max(1, sum(item[0] == chain for item in before))):
    coot.delete_sequence_by_chain_id(fragment, chain)
  fasta = getattr(coot, "assign_fasta_sequence", None)
  if callable(fasta):
    # Unlike assign_sequence_from_string(), this targets only the given chain,
    # without adding/changing associations on NCS-related chains.
    fasta(fragment, chain, ">register-reference\n"+sequence+"\n")
  else:
    coot.assign_sequence_from_string(fragment, chain, sequence)
  associated = coot.sequence_info_py(fragment) or []
  matches = [item[1] for item in associated if isinstance(item, (list, tuple)) and len(item) == 2 and item[0] == chain]
  if len(matches) != 1 or _register_clean_sequence(matches[0]) != sequence:
    raise RuntimeError("Coot did not associate the reference sequence with the fragment.")
  if origin is not None:
    _REGISTER_REFERENCE_ORIGINS[(fragment, chain)] = (sequence, origin)
  else:
    # Nonlinear author numbering needs Coot's sequence alignment, not a guessed offset.
    _REGISTER_REFERENCE_ORIGINS.pop((fragment, chain), None)


def _register_terminal_residue_type(mol_id, chain, destination):
  cached = _REGISTER_REFERENCE_ORIGINS.get((mol_id, chain))
  if cached is not None:
    sequence, origin = cached
    associated = coot.sequence_info_py(mol_id) or []
    matches = [item[1] for item in associated if isinstance(item, (list, tuple))
               and len(item) == 2 and item[0] == chain]
    if len(matches) == 1 and _register_clean_sequence(matches[0]) == sequence:
      index = destination-origin
      if 0 <= index < len(sequence) and sequence[index] in _REGISTER_AA:
        return _REGISTER_AA[sequence[index]]
      add_status_bar_text("Reference sequence has no known residue at this position; using Coot's automatic type.")
    else:
      _REGISTER_REFERENCE_ORIGINS.pop((mol_id, chain), None)
  lookup = getattr(coot, "find_terminal_residue_type_py", None)
  if callable(lookup):
    residue_type = lookup(mol_id, chain, destination)
    if isinstance(residue_type, str) and residue_type in set(_REGISTER_AA.values()):
      return residue_type
  return "auto"


def _register_comparison_targets(records, centre, sequence, origin, shift_window=5, fragment_size=9):
  sequence = _register_clean_sequence(sequence)
  origin = int(origin)
  shift_window = int(shift_window)
  if shift_window < 0:
    raise ValueError("Shift window must be a non-negative integer.")
  fragment_size = int(fragment_size)
  if fragment_size < 1:
    raise ValueError("Fragment size must be a positive integer.")
  # Even lengths place the extra residue on the C-terminal side.
  start = centre-(fragment_size-1)//2
  end = start+fragment_size-1
  selected = [r for r in records if start <= r["number"] <= end]
  if [r["number"] for r in selected] != list(range(start, end+1)):
    raise ValueError(f"The fragment needs consecutive residues {start}-{end}, without insertion codes.")
  if any(r["ins"] or r["name"] not in _REGISTER_PROTEIN_NAMES or
         set(r["backbone"]) != {"N", "CA", "C", "O"} for r in selected):
    raise ValueError("The fragment must have complete protein backbone atoms and no insertion codes.")
  if any(not _register_connected(a, b) for a, b in zip(selected, selected[1:])):
    raise ValueError("The fragment crosses a backbone break.")
  if start-shift_window < origin or end+shift_window >= origin+len(sequence):
    raise ValueError(f"The reference sequence must cover residues {start-shift_window}-{end+shift_window}.")
  targets = []
  for offset in range(-shift_window, shift_window+1):
    target = sequence[start+offset-origin:end+offset-origin+1]
    if set(target) - set(_REGISTER_AA):
      raise ValueError("All candidate identities must be known; replace X in the reference sequence.")
    targets.append((offset, target))
  return start, end, targets


def _register_fit_fixed_backbone_rotamer(fragment, chain, number, map_id):
  """Score library conformers without the residue translations used by autofit."""
  rows = coot.score_rotamers_py(fragment, chain, number, "", "", map_id, 1, 0.3) or []
  candidates = []
  clash_acceptable = []
  for row in rows:
    if not isinstance(row, (list, tuple)) or len(row) < 5:
      raise RuntimeError("Unexpected rotamer scoring result.")
    density, clash = float(row[2]), float(row[4])
    if math.isfinite(density) and math.isfinite(clash) and clash >= 0:
      candidate = (density, row[0])
      candidates.append(candidate)
      if clash < 20:
        clash_acceptable.append(candidate)
  if not candidates:
    raise RuntimeError(f"No scorable fixed-backbone rotamer for {chain}:{number}.")
  # Unfitted neighbours can clash with every conformer; do not reject a register
  # before joint refinement has had a chance to resolve those contacts.
  best = max(clash_acceptable or candidates, key=lambda candidate: candidate[0])
  if not clash_acceptable:
    print(f"Register comparison {chain}:{number}: all rotamers clash; using best density fit.")
  def backbone_coordinates():
    return {tuple(atom[0]): tuple(float(value) for value in atom[2])
            for atom in coot.residue_info_py(fragment, chain, number, "") or []
            if atom[0][0].strip() in {"N", "CA", "C", "O"}}
  before = backbone_coordinates()
  if len(before) != 4:
    raise RuntimeError(f"Incomplete backbone at {chain}:{number}.")
  if not coot.set_residue_to_rotamer_name(fragment, chain, number, "", "", best[1]):
    raise RuntimeError(f"Could not set rotamer at {chain}:{number}.")
  after = backbone_coordinates()
  if before.keys() != after.keys() or any(
      not all(math.isfinite(value) for value in after[key]) or
      _distance_sq(before[key], after[key]) > 1e-10 for key in before):
    raise RuntimeError(f"Rotamer selection moved backbone atoms at {chain}:{number}; candidate excluded.")


def _register_sidechain_correlation(fragment, specs, target, map_id, scoring_cache=None):
  """Mean residue CC beyond C-beta; Gly/Ala have no informative atoms here."""
  eligible = {tuple(spec) for spec, letter in zip(specs, target) if letter not in {"G", "A"}}
  scores = {}
  if eligible:
    # Mask 3 excludes main-chain atoms and CB in both CCP4 and Homebrew Coot.
    results = (_analysis_cc_residue_scores(scoring_cache, fragment, specs, 3) if scoring_cache is not None else
               coot.map_to_model_correlation_per_residue_py(fragment, specs, 3, map_id) or [])
    for item in results:
      if not isinstance(item, (list, tuple)) or len(item) < 2:
        continue
      spec = _coot_residue_spec_from_spec(item[0])
      if spec is None or tuple(spec) not in eligible:
        continue
      value = float(item[1])
      if math.isfinite(value) and -1 <= value <= 1:
        scores[tuple(spec)] = value
  return {"mean": sum(scores.values())/len(scores) if scores else None,
          "count": len(scores), "eligible": len(eligible)}


def _build_register_comparison_fragment(source, chain, start, end, offset, target, map_id,
                                        rigid_fit=True, scoring_cache=None, flexible=False, prepare=True):
  """Build on a disposable copy; restore global refinement settings on every path."""
  ongoing = getattr(coot, "refinement_already_ongoing_p", None)
  if callable(ongoing) and ongoing():
    raise ValueError("Accept or cancel the current refinement before comparing registers.")
  fragment = coot.new_molecule_by_atom_selection(source, _atom_selection_for_residue_range(chain, start, end))
  if fragment == source or not valid_model_molecule_qm(fragment):
    raise RuntimeError("Coot could not create an independent fragment.")
  previous_map = coot.imol_refinement_map()
  previous_replacement = coot.refinement_immediate_replacement_state()
  attempted = False
  try:
    coot.set_imol_refinement_map(map_id)
    # Optional rotamer post-refinement must auto-accept on the disposable copy.
    coot.set_refinement_immediate_replacement(1)
    coot.set_mol_displayed(fragment, 0)
    coot.set_molecule_name(fragment, f"Register {offset:+d}: {chain}:{start+offset}-{end+offset}")
    specs = [[chain, number+offset, ""] for number in range(start, end+1)]
    def fit_rotamers():
      for spec, letter in zip(specs, target):
        if _REGISTER_AA[letter] not in {"ALA", "GLY"}:
          _register_fit_fixed_backbone_rotamer(fragment, chain, spec[1], map_id)

    with _grouped_model_edit(fragment):
      if prepare and offset and not coot.renumber_residue_range(fragment, chain, start, end, offset):
        raise RuntimeError("Fragment renumbering failed.")
      if prepare:
        for spec, letter in zip(specs, target):
          _register_collapse_alternates(fragment, chain, spec[1])
          name = _REGISTER_AA[letter]
          if not coot.mutate(fragment, *spec, name):
            raise RuntimeError(f"Mutation failed at {chain}:{spec[1]}.")
      if rigid_fit:
        fit_function = getattr(coot, "rigid_body_refine_by_atom_selection", None)
        if not callable(fit_function):
          raise RuntimeError("Rigid-body fitting is unavailable in this Coot build.")
        before_fit = _rigid_fit_atom_snapshot(fragment)
        attempted = True
        fit_function(fragment, "//")
        coot.accept_regularizement()
        if _rigid_fit_atom_snapshot(fragment).keys() != before_fit.keys():
          raise RuntimeError("Rigid fitting changed fragment atom identities.")
      fit_rotamers()
      if flexible:
        for cycle in range(2):
          attempted = True
          refinement = coot.refine_residues_py(fragment, specs)
          if refinement is False or refinement is None:
            raise RuntimeError("Coot could not refine this fragment.")
          coot.accept_regularizement()
          if cycle == 0:
            fit_rotamers()
    results = (_analysis_cc_residue_scores(scoring_cache, fragment, specs, 0) if scoring_cache is not None else
               coot.map_to_model_correlation_per_residue_py(fragment, specs, 0, map_id) or [])
    scores = {}
    for item in results:
      if not isinstance(item, (list, tuple)) or len(item) < 2:
        continue
      spec = _coot_residue_spec_from_spec(item[0])
      if spec is None:
        continue
      score = float(item[1])
      if math.isfinite(score) and list(spec) in specs:
        scores[tuple(spec)] = score
    if len(scores) != len(specs):
      raise RuntimeError(f"Only {len(scores)}/{len(specs)} residues could be scored; candidate excluded.")
    try:
      sidechain = _register_sidechain_correlation(fragment, specs, target, map_id, scoring_cache)
    except Exception as error:
      print(f"Register {offset:+d}: sidechain CC unavailable: {error}")
      sidechain = {"mean": None, "count": 0, "eligible": sum(letter not in {"G", "A"} for letter in target)}
    coloured = False
    if _supports_direct_user_defined_colouring():
      rows = [(list(spec), _density_fit_score_to_colour_index(score)) for spec, score in scores.items()]
      coloured = bool(_apply_direct_user_defined_residue_colours(fragment, [], rows))
    return {"model": fragment, "offset": offset, "sequence": target,
            "mean": sum(scores.values())/len(scores), "minimum": min(scores.values()), "coloured": coloured,
            "sidechain": sidechain, "flexible": bool(flexible),
            "scores": [[list(spec), score] for spec, score in scores.items()]}
  except Exception:
    try:
      if attempted and callable(ongoing) and ongoing():
        coot.clear_up_moving_atoms()
    finally:
      coot.close_molecule(fragment)
    raise
  finally:
    coot.set_refinement_immediate_replacement(previous_replacement)
    coot.set_imol_refinement_map(previous_map)


def _refine_register_comparison_candidate(candidate, chain, start, end, map_id):
  """Refine a disposable copy of the current candidate, preserving it on failure."""
  if coot.refinement_already_ongoing_p():
    raise ValueError("Accept or cancel the current refinement first.")
  offset = candidate["offset"]
  refined = _build_register_comparison_fragment(candidate["model"], chain, start+offset, end+offset,
      0, candidate["sequence"], map_id, rigid_fit=False, flexible=True, prepare=False)
  try:
    coot.set_molecule_name(refined["model"], f"Register {offset:+d}: {chain}:{start+offset}-{end+offset} (flex)")
    refined["offset"] = offset
  except Exception:
    coot.close_molecule(refined["model"])
    raise
  return refined


def _register_merge_plan(original, fragment, chain, start, end, offset, selected_specs=None):
  """Plan same-chain replacement; trim numbering overlap and terminal backbone clashes."""
  first, last = start+offset, end+offset
  specs = [(chain, n, "") for n in range(first, last+1)] if selected_specs is None else list(selected_specs)
  if selected_specs is not None and (offset or not specs or len(set(specs)) != len(specs)
      or any(s[0] != chain or s not in original for s in specs)
      or min(s[1] for s in specs) != first or max(s[1] for s in specs) != last):
    raise ValueError("Explicit replacement requires distinct existing residues in one chain, without a numbering shift.")
  if set(fragment) != set(specs):
    raise ValueError("The candidate no longer contains exactly the tested residue range.")
  removed = {s for s in original if s[0] == chain and start <= s[1] <= end} if selected_specs is None else set(specs)
  if selected_specs is None and removed != {(chain, n, "") for n in range(start, end+1)}:
    raise ValueError("The original range is incomplete or has insertion codes; regenerate the comparison.")
  def backbone(record, require_complete=True):
    if record['name'] not in _REGISTER_PROTEIN_NAMES:
      raise ValueError("Automatic boundary trimming requires protein residues.")
    points = [(a[0][0].strip(), a[2]) for a in record['atoms']
              if a[0][0].strip() in {'N', 'CA', 'C', 'O'}]
    if require_complete and {name for name, _ in points} != {'N', 'CA', 'C', 'O'}:
      raise ValueError("Automatic merging requires complete N/CA/C/O backbone atoms.")
    if any(not all(math.isfinite(v) for v in xyz) for _, xyz in points):
      raise ValueError("Non-finite candidate or boundary coordinates.")
    return points
  candidate_atoms = [(s, name, xyz) for s in specs for name, xyz in backbone(fragment[s])]
  trim = {}
  for side in (-1, 1):
    neighbours = sorted((s for s in original if s[0] == chain and
                         (s[1] < start if side < 0 else s[1] > end)), reverse=side < 0)
    extra = 0
    previous = start if side < 0 else end
    pending = []
    for spec in neighbours:
      collision = first <= spec[1] <= last
      if spec[2]:
        if collision:
          raise ValueError("An overlapping boundary has insertion codes; trim it manually first.")
        break
      if spec[1] != previous+side:
        break
      previous = spec[1]
      if original[spec]['name'] not in _REGISTER_PROTEIN_NAMES and not collision:
        break
      points = backbone(original[spec], require_complete=False)
      clashes = False
      for name, xyz in points:
        for added, other, position in candidate_atoms:
          d2 = _distance_sq(xyz, position)
          peptide = ((added[1] == spec[1]+1 and name == 'C' and other == 'N') or
                     (spec[1] == added[1]+1 and name == 'N' and other == 'C'))
          if d2 < 1.8**2 and not (peptide and d2 >= 1.05**2):
            clashes = True
            break
        if clashes:
          break
      if not collision:
        extra += 1
        if extra > 5:
          if not clashes:
            break
          raise ValueError("Resolving the boundary clash would trim more than five extra residues on one side; adjust the candidate or trim manually.")
      pending.append((spec, collision, clashes))
      if collision or clashes:
        # A bent join can clash beyond a clear residue. Remove the continuous
        # flank through the last clash, never an isolated internal residue.
        for boundary, overlap, clash in pending:
          backbone(original[boundary])
          trim[boundary] = ('numbering overlap' if overlap else
                            'backbone clash' if clash else 'boundary continuity')
        pending.clear()
  conflicts = {s for s in original if s[0] == chain and first <= s[1] <= last} - removed - trim.keys()
  if conflicts:
    raise ValueError("Candidate numbering collides beyond the adjacent chain boundary.")
  deleted = removed | trim.keys()
  expected = {s: r for s, r in original.items() if s not in deleted}
  remaining_atoms = [(s, a[0][0].strip(), a[2]) for s, r in expected.items()
                     if r['name'] in _REGISTER_PROTEIN_NAMES for a in r['atoms']
                     if a[0][0].strip() in {'N', 'CA', 'C', 'O'}]
  index = _spatial_index(remaining_atoms, lambda item: item[2], 1.8)
  for added, name, xyz in candidate_atoms:
    for spec, other, position in _spatial_query(index, xyz, 1.8):
      peptide = (spec[0] == chain and not spec[2] and
                 ((added[1] == spec[1]+1 and name == 'N' and other == 'C') or
                  (spec[1] == added[1]+1 and name == 'C' and other == 'N')))
      if not (peptide and _distance_sq(xyz, position) >= 1.05**2):
        raise ValueError(f"Candidate backbone clashes with untrimmed residue {spec}; adjust the candidate or trim manually.")
  expected.update(fragment)
  _global_multimap_identity(expected)
  return dict(deleted=sorted(deleted), trim=trim, expected=expected, first=first, last=last)


def _apply_register_comparison_merge(source, candidate, chain, plan, source_signature, candidate_signature, reference=None,
                                     preserve_sequences=False):
  """Validate on disposable copies, then perform one native, undoable chain merge."""
  if coot.refinement_already_ongoing_p():
    raise ValueError("Accept or cancel the current refinement before merging.")
  donor = candidate['model']
  if not valid_model_molecule_qm(source) or not valid_model_molecule_qm(donor) or source == donor:
    raise ValueError("The source model or candidate is no longer available.")
  if (_register_shift_model_signature(source) != source_signature or
      _register_shift_model_signature(donor) != candidate_signature):
    raise ValueError("The source or candidate changed after the merge preview; preview again.")
  if coot.backup_state(source) != 1:
    raise ValueError("Enable Coot backups for the source model before merging.")
  reference = reference if reference is not None else (None if preserve_sequences else _REGISTER_REFERENCE_ORIGINS.get((donor, chain)))
  previous_sequences = previous_origins = None
  if reference is not None:
    sequence, origin = reference
    reference = (_register_clean_sequence(sequence), int(origin) if origin is not None else None)
    if reference[1] is not None and not 0 <= plan['first']-reference[1] <= plan['last']-reference[1] < len(reference[0]):
      raise ValueError('The full reference sequence does not cover the merged residue numbering.')
    previous_sequences = [list(item) for item in coot.sequence_info_py(source) or []]
    previous_origins = {key: value for key, value in _REGISTER_REFERENCE_ORIGINS.items() if key[0] == source}
  elif preserve_sequences:
    previous_sequences = [list(item) for item in coot.sequence_info_py(source) or []]
    previous_origins = {key: value for key, value in _REGISTER_REFERENCE_ORIGINS.items() if key[0] == source}
  deleted = set(plan['deleted'])
  links = getattr(coot, 'link_info_py', None)
  if callable(links) and any(tuple(atom[-5:-2]) in deleted
                            for link in links(source) or [] for atom in link[1:3]):
    raise ValueError('The replaced/trimmed residues have explicit LINK records. Review/remove those links first.')
  # Extra restraints are retained, but must not be left pointing at removed atoms.
  expected_atoms = {(*s, *a[0]) for s, r in plan['expected'].items() for a in r['atoms']}
  def check_restraint(value):
    if not isinstance(value, (list, tuple)):
      return
    if (len(value) >= 5 and isinstance(value[-4], int) and
        isinstance(value[-5], str) and tuple(value[-5:-2]) in deleted and
        tuple(value[-5:]) not in expected_atoms):
      raise ValueError("Extra restraints reference atoms removed by this merge. Remove those restraints first.")
    for item in value:
      check_restraint(item)
  getter = getattr(coot, 'list_extra_restraints_py', None)
  restraints = getter(source) if callable(getter) else None
  check_restraint(restraints)
  temporary = []
  def copied(model):
    existing = set(model_molecule_list())
    result = coot.copy_molecule(model)
    if result in existing or not valid_model_molecule_qm(result):
      raise RuntimeError("Could not create an independent merge-validation copy.")
    temporary.append(result)
    coot.set_mol_displayed(result, 0)
    return result
  def merge(target, fragment):
    _delete_residue_specs(target, plan['deleted'])
    before_chains = {s[0] for s in _model_coordinate_snapshot(target)}
    result = coot.merge_molecules_py([fragment], target)
    if not result or not result[0]:
      raise RuntimeError("Coot rejected the candidate merge.")
    for added_chain in result[1:]:
      if isinstance(added_chain, str) and added_chain != chain:
        if added_chain in before_chains:
          raise RuntimeError('Coot consolidated the candidate into an unrelated existing chain; merge cancelled.')
        coot.change_chain_id(target, added_chain, chain, 1, plan['first'], plan['last'])
    actual = _model_coordinate_snapshot(target)
    change = _global_multimap_snapshot_change(plan['expected'], actual)
    if change:
      missing = sorted(plan['expected'].keys()-actual.keys())
      added = sorted(actual.keys()-plan['expected'].keys())
      raise RuntimeError(f"The merged model did not match the preview: {change}; missing {missing[:5]}, unexpected {added[:5]}")
    if reference is not None:
      _register_associate_reference(target, chain, *reference)
    elif preserve_sequences:
      current = [list(item) for item in coot.sequence_info_py(target) or []]
      if sorted(current) != sorted(previous_sequences):
        for label in {item[0] for item in current+previous_sequences}:
          for _ in range(sum(item[0] == label for item in current)):
            coot.delete_sequence_by_chain_id(target, label)
        for label, sequence in previous_sequences:
          coot.assign_fasta_sequence(target, label, '>restored-reference\n'+sequence+'\n')
        if sorted(coot.sequence_info_py(target) or []) != sorted(previous_sequences):
          raise RuntimeError('Could not preserve the original sequence associations.')
  try:
    stage, fragment = copied(source), copied(donor)
    merge(stage, fragment)
    # Use a fresh donor: native merging hides/deactivates its donor model.
    fragment = copied(donor)
    attempted = False
    try:
      with _grouped_model_edit(source):
        attempted = True
        merge(source, fragment)
        if callable(getter) and getter(source) != restraints:
          raise RuntimeError("Coot unexpectedly changed the extra restraints during merging.")
    except Exception as error:
      if not attempted:
        raise RuntimeError(f'Merge stopped before editing; original unchanged. {error}') from error
      try:
        coot.set_undo_molecule(source)
        recovered = coot.apply_undo()
        if previous_sequences is not None:
          # Native coordinate Undo need not restore Coot's sequence metadata.
          current = [list(item) for item in coot.sequence_info_py(source) or []]
          for label in {item[0] for item in current+previous_sequences}:
            for _ in range(max(1, sum(item[0] == label for item in current))):
              coot.delete_sequence_by_chain_id(source, label)
          for label, sequence in previous_sequences:
            fasta = getattr(coot, 'assign_fasta_sequence', None)
            if callable(fasta):
              fasta(source, label, '>restored-reference\n'+sequence+'\n')
            else:
              coot.assign_sequence_from_string(source, label, sequence)
          if sorted(coot.sequence_info_py(source) or []) != sorted(previous_sequences):
            raise RuntimeError('Could not restore the original reference-sequence associations.')
          for key in list(_REGISTER_REFERENCE_ORIGINS):
            if key[0] == source:
              del _REGISTER_REFERENCE_ORIGINS[key]
          _REGISTER_REFERENCE_ORIGINS.update(previous_origins)
      except Exception as undo_error:
        raise RuntimeError(f'Merge failed; automatic recovery failed. Use Coot Undo before further edits. {undo_error}') from error
      if not recovered or _register_shift_model_signature(source) != source_signature:
        raise RuntimeError(f"Merge failed; recovery could not be verified. Use Coot Undo before further edits. {error}") from error
      raise RuntimeError(f"Merge failed and was undone; the candidate was retained. {error}") from error
  finally:
    for model in temporary:
      _REGISTER_REFERENCE_ORIGINS.pop((model, chain), None)
      if valid_model_molecule_qm(model):
        coot.close_molecule(model)
  return True


def _af_replace_alignment(target_seq, donor_seq):
    """Align all of target to an embedded donor region (free donor ends).

    mapping is zero-based target index -> donor index, including substitutions.
    identity is exact known-letter matches / mapped pairs; coverage is mapped
    pairs / target length. gaps reports target deletions and internal donor
    insertions, not free donor flanks. Tied optimal alignments are conservative
    confirmation requirements, never silently asserted unique correspondences.
    Use the WHOLE observed/assigned target sequence, not a short clicked range.
    """
    def clean(seq):
        seq = ''.join(str(seq).split()).upper()
        if not seq or any(c not in 'ACDEFGHIKLMNPQRSTVWYBXZJUO' for c in seq):
            raise ValueError('Supply a non-empty ungapped protein sequence.')
        return seq

    target, donor = clean(target_seq), clean(donor_seq)
    n, m = len(target), len(donor)
    # Exact embedding is common and avoids quadratic storage for long chains.
    offset = donor.find(target)
    known = set('ACDEFGHIKLMNPQRSTVWYUO')
    if offset >= 0 and set(target) <= known:
        mapping = {i: offset+i for i in range(n)}
        ambiguous = donor.find(target, offset+1) >= 0
        score = 3*n
    else:
        band = max(n, m)
        if n == m:
            mismatches = sum(a != b or a not in known for a, b in zip(target, donor))
            # The ungapped score is a lower bound. Each gap costs at least
            # five points versus the perfect score, bounding every viable path.
            band = min(m, (7*mismatches)//5+1)
        starts = [max(0, i-band) for i in range(n+1)]
        widths = [min(m, i+band)-starts[i]+1 for i in range(n+1)]
        if sum(widths) > 25000000:
            raise ValueError('Alignment exceeds 25 million cells; supply an explicit verified mapping.')
        trace = [bytearray(width) for width in widths]
        unreachable = -10*(n+m+1)
        previous = [0 if j <= band else unreachable for j in range(m+1)]
        ways = [int(j <= band) for j in range(m+1)]
        for i in range(1, n+1):
            current, counts = [unreachable]*(m+1), [0]*(m+1)
            if i <= band:
                current[0], counts[0] = -5*i, 1
            if starts[i] == 0:
                trace[i][0] = 2
            for j in range(max(1, i-band), min(m, i+band)+1):
                same = target[i-1] == donor[j-1] and target[i-1] in known
                values = (previous[j-1]+(3 if same else -4),
                          previous[j]-5, current[j-1]-5)
                best = max(values)
                current[j] = best
                trace[i][j-starts[i]] = values.index(best)+1
                counts[j] = min(2, sum(c for v, c in zip(values, (ways[j-1], ways[j], counts[j-1])) if v == best))
            previous, ways = current, counts
        score = max(previous)
        ends = [j for j, value in enumerate(previous) if value == score]
        ambiguous = sum(ways[j] for j in ends) > 1
        i, j = n, ends[0]
        mapping = {}
        while i:
            direction = trace[i][j-starts[i]]
            if direction == 1:
                mapping[i-1] = j-1
                i, j = i-1, j-1
            elif direction == 2:
                i -= 1
            else:
                j -= 1
        mapping = dict(sorted(mapping.items()))
    substitutions = [(i, j, target[i], donor[j]) for i, j in mapping.items()
                     if target[i] != donor[j] or target[i] not in known]
    used = set(mapping.values())
    first, last = (min(used), max(used)) if used else (0, -1)
    gaps = dict(target=[i for i in range(n) if i not in mapping],
                donor=[j for j in range(first, last+1) if j not in used])
    matches = len(mapping)-len(substitutions)
    return dict(mapping=mapping, identity=matches/float(len(mapping)) if mapping else 0.,
                coverage=len(mapping)/float(n), donor_coverage=len(mapping)/float(m),
                substitutions=substitutions, gaps=gaps, ambiguous=ambiguous,
                requires_confirmation=ambiguous, score=score, matches=matches,
                target_sequence=target, donor_sequence=donor,
                donor_range=(first, last) if used else None)


def _af_replace_ca(row):
    """One deterministic occupied carbon CA; preserve all donor altlocs later."""
    import math
    choices = []
    for identity, properties, xyz in row['atoms']:
        name, alt = identity[0].strip(), str(identity[1] or '').strip()
        element = str(properties[2]).strip().upper() if len(properties) > 2 else ''
        occupancy = float(properties[0])
        if name == 'CA' and element in ('', 'C') and occupancy > 0:
            point = list(map(float, xyz))
            if len(point) != 3 or not all(math.isfinite(v) for v in point):
                raise ValueError('Non-finite or invalid CA coordinates.')
            choices.append(((not alt, occupancy, alt == 'A', alt), point))
    return max(choices, key=lambda item: item[0])[1] if choices else None


def _af_replace_robust_fit(moving, target, ca_cutoff=2.0):
    """Donor -> target rigid fit, iterative pruning and local-domain seeds.

    Start with ALL selected pairs, then deterministic contiguous windows. Pick
    the largest consensus, not the smallest three-point RMSD. Report every
    distance under the final operator, including pruned points.
    """
    import math
    cutoff = float(ca_cutoff)
    if not math.isfinite(cutoff) or cutoff <= 0:
        raise ValueError('CA cutoff must be finite and positive (Angstrom).')
    moving = [list(map(float, p)) for p in moving]
    target = [list(map(float, p)) for p in target]
    n = len(moving)
    if n < 3 or n != len(target):
        raise ValueError('At least three matched CA pairs are required.')
    if any(len(p) != 3 or not all(math.isfinite(v) for v in p) for p in moving+target):
        raise ValueError('Non-finite or invalid CA coordinates.')

    def errors(operator):
        return [math.sqrt(sum((a-b)**2 for a, b in zip(_ncs_transform(operator, p), q)))
                for p, q in zip(moving, target)]

    seeds = [tuple(range(n))]
    for width in sorted({3, max(3, n//3), max(3, n//2)}):
        if width >= n:
            continue
        starts = {int(round(k*(n-width)/float(min(11, n-width)))) for k in range(min(11, n-width)+1)}
        seeds.extend(tuple(range(start, start+width)) for start in sorted(starts))
    candidates = []
    for seed in seeds:
        keep = list(seed)
        for iteration in range(n+1):
            try:
                operator = _ncs_rigid_fit([moving[i] for i in keep], [target[i] for i in keep])
            except ValueError:
                break
            distances = errors(operator)
            inliers = [i for i, d in enumerate(distances) if d <= cutoff+1e-9]
            if len(inliers) >= 3:
                rmsd = math.sqrt(sum(distances[i]**2 for i in inliers)/len(inliers))
                candidates.append((len(inliers), -rmsd, operator, inliers, distances, iteration+1))
            selected = [i for i in keep if distances[i] <= cutoff+1e-9]
            if len(selected) == len(keep):
                break
            if len(selected) < 3:
                # Large domain movements can spoil the initial all-pair fit.
                count = max(3, int(math.ceil(.8*len(keep))))
                if count == len(keep):
                    break
                selected = sorted(sorted(keep, key=lambda i: distances[i])[:count])
            keep = selected
    if not candidates:
        raise ValueError('No non-collinear core of at least three CA pairs fits the cutoff.')
    best = max(candidates, key=lambda c: c[:2])
    _, _, operator, inliers, distances, iterations = best
    # Refit the consensus; retain the seed operator if growing it loses support.
    for _ in range(10):
        fitted = _ncs_rigid_fit([moving[i] for i in inliers], [target[i] for i in inliers])
        ds = errors(fitted)
        selected = [i for i, d in enumerate(ds) if d <= cutoff+1e-9]
        rmsd = math.sqrt(sum(ds[i]**2 for i in selected)/len(selected)) if selected else float('inf')
        old_rmsd = math.sqrt(sum(distances[i]**2 for i in inliers)/len(inliers))
        if (len(selected), -rmsd) < (len(inliers), -old_rmsd-1e-10):
            break
        unchanged = selected == inliers
        operator, inliers, distances = fitted, selected, ds
        if unchanged:
            break
    rmsd = math.sqrt(sum(distances[i]**2 for i in inliers)/len(inliers))
    core_sets = {tuple(c[3]) for c in candidates if c[0] == len(inliers) and abs(-c[1]-rmsd) < .05}
    return dict(operator=operator, distances=distances, inliers=inliers,
                outliers=[i for i in range(n) if i not in set(inliers)], rmsd=rmsd,
                rmsd_all=math.sqrt(sum(d*d for d in distances)/n),
                core_fraction=len(inliers)/float(n), ambiguous_core=len(core_sets) > 1,
                iterations=iterations, seed_count=len(seeds))


def _af_replace_ca_distances(original, donor_rows, operator, target_specs=None):
    """Distances keyed by TARGET spec; absent CA/mapping yields None."""
    import math
    result = {}
    for spec in (target_specs if target_specs is not None else original):
        a = _af_replace_ca(original[spec])
        b = _af_replace_ca(donor_rows[spec]) if spec in donor_rows else None
        result[spec] = (math.sqrt(sum((x-y)**2 for x, y in zip(a, _ncs_transform(operator, b))))
                        if a is not None and b is not None else None)
    return result


def _af_replace_fragment(original, target_specs, donor_rows, mapping=None,
                         ca_cutoff=2.0, steric_hook=None, mutate_substitutions=False):
    """Build a preview, never edit a model or authorize a merge.

    donor_rows is either a target-spec -> snapshot-row dict, or an ordered list
    of snapshot rows. For a list, mapping optionally gives target-spec -> donor
    row index. Main should align the FULL observed chain once, then pass this
    mapping and only the clicked/active-chain target_specs for geometry fitting.
    Without mapping a list is aligned to the supplied target_specs sequence.

    fragment spans first..last CA-compatible records, INCLUDING internal loops
    and unsupported/unmapped records. With mutate_substitutions, differing
    residues use donor coordinates and are marked for native mutation. all_fragment covers
    the whole request for an explicit whole-chain action. Missing CA does not
    remove a residue from either fragment. Runs contain compatible consecutive
    observed records, NOT promises of contiguous integer numbering. mean_b is
    the unweighted heavy-atom mean of the ORIGINAL full requested region (all
    altlocs); every inserted atom, including H, receives this B, not pLDDT.

    steric_hook(original_copy, fragment_copy) is advisory; its return is exposed
    as steric, and its exceptions propagate. It receives no live objects.
    """
    import copy
    import math
    amino = dict(zip(('ALA ARG ASN ASP CYS GLN GLU GLY HIS ILE LEU LYS MET PHE PRO SER THR TRP TYR VAL').split(),
                    'ARNDCQEGHILKMFPSTWYV'))
    specs = [tuple(s) for s in target_specs]
    if not specs or len(set(specs)) != len(specs):
        raise ValueError('Select a non-empty set of unique target residue specs.')
    if any(len(s) != 3 or not isinstance(s[0], str) or not isinstance(s[1], int)
           or isinstance(s[1], bool) or not isinstance(s[2], str) for s in specs):
        raise ValueError('Invalid target author residue specs.')
    if len({s[0] for s in specs}) != 1:
        raise ValueError('Replacement must target one chain.')
    if specs != sorted(specs, key=lambda s: (s[1], s[2])):
        raise ValueError('Target specs must be in author residue order.')
    if any(s not in original for s in specs):
        raise ValueError('A selected residue is absent from the original snapshot.')
    # Omitting an observed residue must not turn two disjoint selections into
    # a single deletion interval. Truly unobserved numbering gaps are allowed.
    if any(s[0] == specs[0][0] and specs[0] < s < specs[-1] and s not in specs for s in original):
        raise ValueError('Selection omits observed residues inside its boundary interval.')
    cutoff = float(ca_cutoff)
    if not math.isfinite(cutoff) or cutoff <= 0:
        raise ValueError('CA cutoff must be finite and positive (Angstrom).')
    alignment = None
    if isinstance(donor_rows, dict):
        if mapping is not None:
            raise ValueError('Use either target-keyed donor rows or an explicit row-index mapping.')
        mapped = {s: donor_rows[s] for s in specs if s in donor_rows}
        mapping_result = {s: s for s in mapped}
    else:
        donor_rows = list(donor_rows)
        if mapping is None:
            alignment = _af_replace_alignment(''.join(amino.get(original[s]['name'], 'X') for s in specs),
                                               ''.join(amino.get(r['name'], 'X') for r in donor_rows))
            mapping = {specs[i]: j for i, j in alignment['mapping'].items()}
        mapping_result = {s: mapping[s] for s in specs if s in mapping}
        if any(not isinstance(j, int) or isinstance(j, bool) or not 0 <= j < len(donor_rows)
               for j in mapping_result.values()):
            raise ValueError('Donor mapping contains an invalid row index.')
        indices = list(mapping_result.values())
        if indices != sorted(set(indices)):
            raise ValueError('Donor mapping must be one-to-one and ordered.')
        mapped = {s: donor_rows[j] for s, j in mapping_result.items()}

    def validate(row):
        seen = set()
        for identity, properties, xyz in row['atoms']:
            key = (str(identity[0]).strip(), str(identity[1] or '').strip())
            if key in seen:
                raise ValueError('Duplicate atom name/altloc in a residue.')
            seen.add(key)
            if (len(xyz) != 3 or not all(math.isfinite(float(v)) for v in xyz)
                    or len(properties) < 2 or not math.isfinite(float(properties[0]))
                    or float(properties[0]) < 0):
                raise ValueError('Non-finite or invalid atom coordinates/occupancy.')

    preserved, substitutions, unsupported, unmapped = {}, [], [], []
    matching = {}
    b_values = []
    for s in specs:
        row = original[s]
        validate(row)
        for identity, properties, xyz in row['atoms']:
            element = str(properties[2]).strip().upper() if len(properties) > 2 else ''
            atom_name = str(identity[0]).strip().lstrip('0123456789').upper()
            heavy = element not in ('H', 'D', 'T') if element else not atom_name.startswith(('H', 'D'))
            if heavy:
                b = properties[1]
                if isinstance(b, (list, tuple)):
                    raise ValueError('A scalar isotropic B factor is required for original heavy atoms.')
                b = float(b)
                if not math.isfinite(b) or b < 0:
                    raise ValueError('Original heavy-atom B factors must be finite and non-negative.')
                b_values.append(b)
        if row['name'] not in amino or (s in mapped and mapped[s]['name'] not in amino):
            unsupported.append(s)
            preserved[s] = 'unsupported residue'
        elif s not in mapped:
            unmapped.append(s)
            preserved[s] = 'unmapped residue'
        elif row['name'] != mapped[s]['name']:
            substitutions.append(s)
            if mutate_substitutions and mapped[s]['atoms']:
                validate(mapped[s])
                matching[s] = mapped[s]
            else:
                preserved[s] = 'sequence substitution'
        else:
            validate(mapped[s])
            if not mapped[s]['atoms']:
                preserved[s] = 'empty donor residue'
            else:
                matching[s] = mapped[s]
    if not b_values:
        raise ValueError('The original selection has no heavy atoms for a local mean B.')
    mean_b = sum(b_values)/len(b_values)
    pairs, moving, fixed = [], [], []
    for s in specs:
        if s not in matching:
            continue
        a, b = _af_replace_ca(original[s]), _af_replace_ca(matching[s])
        if a is not None and b is not None:
            pairs.append(s)
            fixed.append(a)
            moving.append(b)
    fit = _af_replace_robust_fit(moving, fixed, cutoff)
    operator = fit['operator']
    distances = _af_replace_ca_distances(original, matching, operator, specs)
    compatible = [s for s in specs if distances[s] is not None and distances[s] <= cutoff+1e-9]
    if len(compatible) < 3:
        raise ValueError('At least three CA pairs must be compatible with the cutoff.')
    all_fragment = {}
    for s in specs:
        row = matching.get(s)
        if row is None:
            all_fragment[s] = copy.deepcopy(original[s])
        else:
            atoms = []
            for identity, properties, xyz in row['atoms']:
                properties = copy.deepcopy(list(properties))
                properties[1] = mean_b
                atoms.append([copy.deepcopy(list(identity)), properties, _ncs_transform(operator, xyz)])
            all_fragment[s] = dict(name=row['name'], atoms=atoms)
    first, last = specs.index(compatible[0]), specs.index(compatible[-1])
    recommended = specs[first:last+1]
    fragment = {s: all_fragment[s] for s in recommended}
    runs, run = [], []
    for s in specs:
        if s in compatible:
            run.append(s)
        elif run:
            runs.append(run)
            run = []
    if run:
        runs.append(run)
    skipped_gaps = [dict(left=a, right=b, missing_numbers=list(range(a[1]+1, b[1])))
                    for a, b in zip(specs, specs[1:]) if b[1] > a[1]+1]
    missing_ca = [s for s in specs if s in matching and distances[s] is None]
    clipped = specs[:first]+specs[last+1:]
    replaced = [s for s in recommended if s in matching]
    internal_outliers = [s for s in recommended if distances[s] is not None and distances[s] > cutoff+1e-9]
    steric = steric_hook(copy.deepcopy(original), copy.deepcopy(fragment)) if steric_hook is not None else None
    return dict(fragment=fragment, all_fragment=all_fragment, operator=operator,
                mapping=mapping_result, alignment=alignment, distances=distances, fit=fit,
                pair_specs=pairs, runs=runs, range=(recommended[0], recommended[-1]),
                recommended_specs=recommended, selected_specs=specs, clipped_specs=clipped,
                skipped_gaps=skipped_gaps, insertion_specs=[s for s in specs if s[2]],
                replaced_specs=replaced, all_replaced_specs=[s for s in specs if s in matching],
                preserved_specs=[s for s in specs if s in preserved], preserved_reasons=preserved,
                substitutions=substitutions, unsupported_specs=unsupported, unmapped_specs=unmapped,
                mutation_targets={s: original[s]['name'] for s in substitutions
                                  if mutate_substitutions and s in fragment and s in matching},
                missing_ca_specs=missing_ca, internal_outlier_specs=internal_outliers,
                mean_b=mean_b, ca_cutoff=cutoff, steric=steric,
                whole_chain_compatible=(len(compatible) == len(specs)),
                requires_confirmation=bool(substitutions or preserved or missing_ca or clipped or internal_outliers
                                           or skipped_gaps or any(s[2] for s in specs)
                                           or fit['ambiguous_core']
                                           or (alignment and alignment['ambiguous'])),
                requires_explicit_replace=True)


def _af_replace_read_model(path):
  if globals().get("gemmi") is None:
    raise ValueError("Replacing from AlphaFold requires Gemmi in Coot's Python environment.")
  structure = gemmi.read_structure(str(path))
  if len(structure) != 1:
    raise ValueError("Choose a single-model prediction, not an ensemble.")
  result = []
  reverse = {name: letter for letter, name in _REGISTER_AA.items()}
  for chain in structure[0]:
    rows = []
    for residue in chain:
      if residue.name not in reverse:
        continue
      # Gemmi adds the leading PDB space, but not the trailing four-column padding.
      atoms = [[[atom.padded_name().ljust(4), atom.altloc.strip("\x00 ")],
                [float(atom.occ), float(atom.b_iso), atom.element.name.rjust(2)],
                [atom.pos.x, atom.pos.y, atom.pos.z]] for atom in residue]
      if not atoms:
        continue
      rows.append(dict(name=residue.name, atoms=atoms, number=residue.seqid.num, ins=residue.seqid.icode.strip()))
    if rows:
      result.append(dict(chain=chain.name, rows=rows, sequence="".join(reverse[r["name"]] for r in rows)))
  if not result:
    raise ValueError("The donor file contains no standard protein residues.")
  return result


def _af_replace_download(record, cancel=None):
  """Cache the actual URL/version supplied by AFDB, never a guessed latest URL."""
  import urllib.request
  from urllib.parse import urlparse
  url = str(record.get("cifUrl") or record.get("pdbUrl") or "")
  parsed = urlparse(url)
  allowed = {"alphafold.ebi.ac.uk"}
  if record.get("provider") == "BFVD" and re.fullmatch(r"/pdb/[A-Z0-9]+(?:-\d+)?\.pdb", parsed.path):
    allowed.add("bfvd.steineggerlab.workers.dev")
  if parsed.scheme != "https" or parsed.hostname not in allowed or parsed.username or parsed.password:
    raise ValueError("AFDB did not provide a supported official model URL.")
  suffix = ".cif" if ".cif" in parsed.path else ".pdb"
  cache = os.path.join(os.environ.get("XDG_CACHE_HOME") or os.path.expanduser("~/.cache"), "Coot", "alphafold-replace")
  os.makedirs(cache, mode=0o700, exist_ok=True)
  path = os.path.join(cache, hashlib.sha256(url.encode()).hexdigest()+suffix)
  if os.path.isfile(path):
    try:
      _af_replace_read_model(path)
      return path
    except (ValueError, RuntimeError, OSError):
      pass
  temporary = None
  try:
    request = urllib.request.Request(url, headers={"User-Agent": "Coot-Trimmings-AlphaFold/1"})
    with urllib.request.urlopen(request, timeout=30) as response:
      if urlparse(response.geturl()).hostname != parsed.hostname:
        raise ValueError("Refusing a model download redirected outside its database host.")
      with tempfile.NamedTemporaryFile(dir=cache, suffix=suffix, delete=False) as handle:
        temporary = handle.name
        size = 0
        while True:
          if cancel is not None and cancel.is_set():
            raise RuntimeError("Download cancelled.")
          data = response.read(256*1024)
          if not data:
            break
          size += len(data)
          if size > 64*1024*1024:
            raise ValueError("The prediction exceeds the 64 MB model limit.")
          handle.write(data)
    _af_replace_read_model(temporary)
    os.replace(temporary, path)
    temporary = None
    return path
  finally:
    if temporary and os.path.exists(temporary):
      os.unlink(temporary)


def _af_replace_uniprot_json(path, limit=8*1024*1024):
  import urllib.request
  from urllib.parse import urlparse
  url = "https://rest.uniprot.org/"+path
  if urlparse(url).hostname != "rest.uniprot.org" or path.startswith(("/", "\\")):
    raise ValueError("Invalid UniProt lookup path.")
  request = urllib.request.Request(url, headers={"User-Agent": "Coot-Trimmings-AlphaFold/1", "Accept": "application/json"})
  with urllib.request.urlopen(request, timeout=10) as response:
    if urlparse(response.geturl()).hostname != "rest.uniprot.org":
      raise ValueError("UniProt redirected outside its database host.")
    data = response.read(limit+1)
  if len(data) > limit:
    raise ValueError("The UniProt response is too large.")
  return json.loads(data)


def _af_replace_uniprot_accessions(sequence):
  """Resolve sequence history too; current accession sequences are checked later."""
  from urllib.parse import urlencode
  cache = getattr(_af_replace_uniprot_accessions, "_cache", {})
  if sequence in cache and time.monotonic()-cache[sequence][0] < 3600:
    return list(cache[sequence][1])
  data = _af_replace_uniprot_json("uniparc/search?"+urlencode(dict(
      query="checksum:"+hashlib.md5(sequence.encode("ascii")).hexdigest(), format="json", size=100)))
  accessions = []
  for item in data.get("results", []):
    if item.get("sequence", {}).get("value") != sequence:
      raise ValueError("UniParc checksum lookup returned a different sequence.")
    for value in item.get("uniProtKBAccessions", []):
      accession = str(value).split(".", 1)[0]
      if re.fullmatch(r"[A-Z0-9]{6,10}", accession) and accession not in accessions:
        accessions.append(accession)
  if len(cache) >= 64:
    cache.pop(next(iter(cache)))
  cache[sequence] = (time.monotonic(), list(accessions))
  _af_replace_uniprot_accessions._cache = cache
  return accessions


def _af_replace_afdb_json(url, limit):
  import urllib.request
  from urllib.parse import urlparse
  parsed = urlparse(url)
  if parsed.scheme != "https" or parsed.hostname != "alphafold.ebi.ac.uk" or parsed.username or parsed.password:
    raise ValueError("Invalid AlphaFold DB lookup URL.")
  request = urllib.request.Request(url, headers={"User-Agent": "Coot-Trimmings-AlphaFold/1"})
  with urllib.request.urlopen(request, timeout=10) as response:
    if urlparse(response.geturl()).hostname != parsed.hostname:
      raise ValueError("AlphaFold DB redirected outside its database host.")
    data = response.read(limit+1)
  if len(data) > limit:
    raise ValueError("The AlphaFold DB response is too large.")
  return json.loads(data)


def _af_replace_bfvd_models(sequence, identifier="", progress=None, cancel=None):
  """Resolve exact UniParc checksums or a supplied UniProt ID, then probe BFVD."""
  import urllib.request
  from urllib.parse import urlencode, urlparse
  from urllib.error import HTTPError
  records = []
  identifier = str(identifier).strip().upper()
  if identifier:
    match = re.fullmatch(r"(?:BFVD-|AF-)?([A-Z0-9]{3,20}(?:-\d+)?)(?:-F\d+)?", identifier)
    if match is None:
      raise ValueError("Enter a UniProt accession, AFDB ID or BFVD ID.")
    accession = match.group(1)
    try:
      data = _af_replace_uniprot_json("uniprotkb/"+accession+".json")
    except HTTPError as error:
      if error.code in (404, 410):
        return []
      raise
    candidate_sequence = data.get("sequence", {}).get("value", "")
    records = [(str(data.get("primaryAccession") or accession), candidate_sequence)]
  else:
    if progress:
      progress("Checking UniProt accessions for an exact BFVD sequence match...")
    records = [(accession, sequence) for accession in _af_replace_uniprot_accessions(sequence)]
  from concurrent.futures import ThreadPoolExecutor, wait
  records = list(dict(records).items())
  def probe(accession, candidate_sequence):
    if not candidate_sequence:
      return None
    if cancel is not None and cancel.is_set():
      raise RuntimeError("Search cancelled.")
    url = "https://bfvd.steineggerlab.workers.dev/pdb/"+accession+".pdb"
    request = urllib.request.Request(url, method="HEAD", headers={"User-Agent": "Coot-Trimmings-AlphaFold/1"})
    try:
      with urllib.request.urlopen(request, timeout=5) as response:
        if urlparse(response.geturl()).hostname != "bfvd.steineggerlab.workers.dev":
          raise ValueError("BFVD redirected outside its database host.")
    except HTTPError as error:
      if error.code in (404, 410):
        return None
      if error.code in (403, 405, 501):
        # Some object stores refuse HEAD while allowing their public GET URL.
        request = urllib.request.Request(url, headers={"User-Agent": "Coot-Trimmings-AlphaFold/1", "Range": "bytes=0-0"})
        try:
          with urllib.request.urlopen(request, timeout=5) as response:
            if urlparse(response.geturl()).hostname != "bfvd.steineggerlab.workers.dev":
              raise ValueError("BFVD redirected outside its database host.")
            response.read(1)
        except HTTPError as missing:
          if missing.code in (404, 410):
            return None
          raise
      else:
        raise
    return dict(provider="BFVD", entryId="BFVD-"+accession, uniprotAccession=accession,
                sequence=candidate_sequence, pdbUrl=url)
  pool = ThreadPoolExecutor(max_workers=4, thread_name_prefix="coot-bfvd")
  futures = {pool.submit(probe, accession, seq): accession for accession, seq in records}
  pending, found, errors = set(futures), {}, []
  deadline = time.monotonic()+15
  try:
    while pending and time.monotonic() < deadline:
      if cancel is not None and cancel.is_set():
        raise RuntimeError("Search cancelled.")
      done, pending = wait(pending, timeout=.1)
      for future in done:
        try:
          record = future.result()
          if record is not None:
            found[futures[future]] = record
        except (OSError, ValueError) as error:
          errors.append(error)
    if pending and progress:
      progress("Some BFVD checks timed out; enter an accession to retry a specific model.")
    if not found and (errors or pending):
      raise ValueError("BFVD lookup incomplete; retry an accession. "+(str(errors[0]) if errors else "Service timed out."))
  finally:
    for future in pending:
      future.cancel()
    pool.shutdown(wait=False, cancel_futures=True)
  return [found[accession] for accession, _ in records if accession in found]


def _af_replace_find_models(sequence, identifier="", progress=None, cancel=None, include_bfvd=False):
  from urllib.parse import urlencode
  from urllib.error import HTTPError
  sequence = _register_clean_sequence(sequence)
  identifier = str(identifier).strip().upper()
  if cancel is not None and cancel.is_set():
    raise RuntimeError("Search cancelled.")
  key = (sequence, identifier, bool(include_bfvd))
  cache = getattr(_af_replace_find_models, "_cache", {})
  if key in cache and time.monotonic()-cache[key][0] < 3600:
    if progress:
      progress("Using cached prediction matches...")
    return [dict(record) for record in cache[key][1]]
  started = time.monotonic()
  warnings = []
  result, seen = [], set()
  def remember(records):
    if len(cache) >= 64:
      cache.pop(next(iter(cache)))
    cache[key] = (time.monotonic(), [dict(record) for record in records])
    _af_replace_find_models._cache = cache
    return records
  def predictions(identifiers):
    # Independent metadata lookups must not serialize dozens of network waits.
    from concurrent.futures import ThreadPoolExecutor, wait
    pool = ThreadPoolExecutor(max_workers=4, thread_name_prefix="coot-afdb-metadata")
    identifiers = list(dict.fromkeys(value for value in identifiers if re.fullmatch(
        r"(?:AF-)?[A-Z0-9]+(?:-\d+)?(?:-F\d+)?", value)))
    futures = {pool.submit(_af_replace_afdb_json,
        "https://alphafold.ebi.ac.uk/api/prediction/"+value, 8*1024*1024): value for value in identifiers}
    pending = set(futures)
    received = {}
    deadline = time.monotonic()+15
    try:
      while pending and time.monotonic() < deadline:
        if cancel is not None and cancel.is_set():
          raise RuntimeError("Search cancelled.")
        done, pending = wait(pending, timeout=.1)
        for future in done:
          value = futures[future]
          try:
            received[value] = future.result()
          except HTTPError as error:
            if error.code != 404:
              warnings.append(f"AFDB HTTP {error.code}")
          except (OSError, ValueError) as error:
            warnings.append(str(error))
      if pending:
        warnings.append("Some AFDB metadata requests timed out")
    finally:
      for future in pending:
        future.cancel()
      pool.shutdown(wait=False, cancel_futures=True)
    for value in identifiers:
      for record in received.get(value, []):
        entry = str(record.get("entryId") or record.get("modelEntityId") or "")
        if (entry in seen or not (record.get("cifUrl") or record.get("pdbUrl"))
            or (value.startswith("AF-") and entry != value)):
          continue
        seen.add(entry)
        result.append(record)
  bfvd_only = str(identifier).strip().upper().startswith("BFVD-")
  def bfvd_lookup():
    try:
      return _af_replace_bfvd_models(sequence, identifier, progress, cancel)
    except Exception as error:
      if bfvd_only or (cancel is not None and cancel.is_set()):
        raise
      warnings.append("BFVD: "+str(error))
      return []
  if bfvd_only:
    bfvd = bfvd_lookup()
    if not bfvd:
      raise ValueError("No BFVD model is available for this UniProt accession.")
    return remember(bfvd)
  if not identifier.strip() and (len(sequence) < 20 or set(sequence)-set(_REGISTER_AA)):
    raise ValueError("Sequence lookup needs at least 20 known residues. Supply an accession or a local prediction.")
  identifiers = []
  if identifier.strip():
    identifier = identifier.strip().upper()
    if not re.fullmatch(r"(?:AF-)?[A-Z0-9]{3,20}(?:-\d+)?(?:-F\d+)?", identifier):
      raise ValueError("Enter a UniProt accession or AFDB ID, or leave it blank to search by sequence.")
    identifiers.append(identifier)
  else:
    if progress:
      progress("Looking for an exact sequence match...")
    try:
      data = _af_replace_afdb_json("https://alphafold.ebi.ac.uk/api/sequence/summary?"+
          urlencode(dict(id=hashlib.md5(sequence.encode("ascii")).hexdigest(), type="md5", rows=1000)), 8*1024*1024)
    except HTTPError as error:
      if error.code != 404:
        warnings.append(f"AFDB exact lookup HTTP {error.code}")
      data = {}
    except OSError as error:
      warnings.append("AFDB exact lookup: "+str(error))
      data = {}
    if data and data.get("entry", {}).get("sequence") != sequence:
      raise ValueError("AFDB's exact sequence response did not match the query.")
    for item in data.get("structures", []):
      identifier = item.get("summary", {}).get("model_identifier", "")
      if re.fullmatch(r"AF-[A-Z0-9]+(?:-\d+)?-F\d+", str(identifier)):
        identifiers.append(str(identifier))
    predictions(identifiers)
    if result:
      return remember(result)
    if progress:
      progress("Resolving UniProt accessions by sequence checksum...")
    try:
      identifiers = _af_replace_uniprot_accessions(sequence)
    except (OSError, ValueError) as error:
      warnings.append("UniParc: "+str(error))
      identifiers = []
    predictions(identifiers)
    if result:
      return remember(result)
    if include_bfvd:
      bfvd = bfvd_lookup()
      if bfvd:
        return remember(bfvd)
    if not result:
      if progress:
        progress("Searching AFDB for close sequences (up to 30 seconds)...")
      url = "https://alphafold.ebi.ac.uk/api/search?"+urlencode(dict(q=sequence, type="sequence", start=0, rows=50))
      deadline = time.monotonic()+30
      while True:
        if cancel is not None and cancel.is_set():
          raise RuntimeError("Search cancelled.")
        try:
          data = _af_replace_afdb_json(url, 16*1024*1024)
        except (OSError, ValueError) as error:
          raise ValueError("AFDB sequence search is unavailable. Enter a UniProt accession or use a local prediction. "
                           "Details: "+str(error)) from error
        if not str(data.get("message", "")).startswith(("Job for sequence", "Search in progress")):
          break
        if time.monotonic() >= deadline:
          raise RuntimeError("AFDB is still searching. Retry shortly to use its cached result, or enter a UniProt accession.")
        if cancel is not None:
          cancel.wait(2)
        else:
          time.sleep(2)
      identifiers = [str(r.get("entryId") or r.get("modelEntityId") or r.get("uniprotAccession") or "")
                     for r in data.get("docs", []) if not r.get("isComplex")]
      if int(data.get("numFound", 0) or 0) > 50 and progress:
        progress("Checking the first 50 AFDB hits. Use an accession if the desired model is not listed.")
  predictions(identifiers)
  if not result and include_bfvd and identifier:
    result = bfvd_lookup()
  if not result:
    detail = " ("+warnings[-1]+")" if warnings else ""
    raise ValueError("No prediction found. Try a UniProt accession or a local prediction."+detail)
  if progress:
    progress(f"Found {len(result)} prediction(s) in {time.monotonic()-started:.1f}s.")
  return remember(result)


def _af_replace_target(model, chain, specs=None):
  _ncs_require_idle(model)
  if coot.n_models(model) != 1:
    raise ValueError("Choose a single-model molecule, not an ensemble.")
  snapshot = _model_coordinate_snapshot(model)
  reverse = {name: letter for letter, name in _REGISTER_AA.items()}
  reverse["MSE"] = "M"
  ordered = sorted(s for s, row in snapshot.items() if s[0] == chain and row["name"] in reverse)
  selected = ordered if specs is None else sorted(tuple(s) for s in specs)
  if not selected or len(set(selected)) != len(selected) or any(s not in ordered for s in selected):
    raise ValueError("Select protein residues with assigned identities in one chain.")
  numbered = [dict(number=s[1], ins=s[2], name=snapshot[s]["name"]) for s in ordered]
  sequence = "".join(reverse[snapshot[s]["name"]] for s in ordered)
  reference, description = _register_reference_sequence(model, chain, numbered)
  if description.startswith("Model-derived"):
    try:
      full = _pae_reference_sequences(model, snapshot).get(chain)
      if full:
        reference, description = full, "mmCIF reference sequence loaded."
    except (ValueError, OSError, RuntimeError):
      pass
  row_map = {spec: i for i, spec in enumerate(ordered)}
  alignment_sequence = sequence
  if reference and not set(reference)-set(_REGISTER_AA) and not description.startswith("Model-derived"):
    try:
      mapped, changes = _pae_sequence_rows([dict(spec=s, letter=reverse[snapshot[s]["name"]]) for s in ordered], reference)
      row_map = dict(zip(ordered, mapped))
      alignment_sequence = reference
    except ValueError:
      pass
  query = reference if reference and not set(reference)-set(_REGISTER_AA) else sequence
  if query == sequence and any(b[1] != a[1]+1 or a[2] or b[2] for a, b in zip(ordered, ordered[1:])):
    runs = [[]]
    for spec in ordered:
      if runs[-1] and (spec[1] != runs[-1][-1][1]+1 or spec[2] or runs[-1][-1][2]):
        runs.append([])
      runs[-1].append(spec)
    run = max(runs, key=lambda row: (len(set(row).intersection(selected)), len(row)))
    query = "".join(reverse[snapshot[s]["name"]] for s in run)
  return dict(model=model, chain=chain, specs=selected, ordered=ordered, sequence=sequence, query=query,
              snapshot=snapshot, signature=_register_shift_model_signature(model), name=coot.molecule_name(model),
              description=description, alignment_sequence=alignment_sequence, row_map=row_map,
              has_reference=bool(reference and not description.startswith("Model-derived") and alignment_sequence == reference),
              sequences=[list(item) for item in coot.sequence_info_py(model) or []])


def _af_replace_assess(target, sequence):
  alignment = _af_replace_alignment(target.get("alignment_sequence", target["sequence"]), sequence)
  if alignment["ambiguous"]:
    raise ValueError("Sequence mapping is ambiguous. Use a complete reference sequence or a larger unique region.")
  mapping = alignment["mapping"]
  indices = {spec: i for i, spec in enumerate(target["ordered"])}
  selected = [(spec, indices[spec]) for spec in target["specs"]]
  row_map = target.get("row_map", indices)
  covered = [(spec, i, mapping[row_map[spec]]) for spec, i in selected if row_map[spec] in mapping]
  if not covered:
    raise ValueError("The prediction does not cover the selected residues.")
  changes = [(spec, target["sequence"][i], sequence[j]) for spec, i, j in covered
             if target["sequence"][i] != sequence[j]]
  identity = 1.-len(changes)/len(covered)
  coverage = len(covered)/len(selected)
  close_enough = identity >= .99-1e-10 or len(changes) <= 2
  if not close_enough or coverage < 1.-1e-10:
    raise ValueError("A match must cover every selected residue and have at least 99% identity or at most two substitutions.")
  return dict(identity=identity, coverage=coverage, changes=changes, alignment=alignment,
              mapping={spec: mapping[row_map[spec]] for spec, i in selected if row_map[spec] in mapping})


def _af_replace_prepare(target, donors, cutoff=2.):
  candidates = []
  errors = []
  for donor in donors:
    try:
      assessed = _af_replace_assess(target, donor["sequence"])
      result = _af_replace_fragment(target["snapshot"], target["specs"], donor["rows"],
                                    mapping=assessed["mapping"], ca_cutoff=float(cutoff), mutate_substitutions=True)
      result["rmsd"], result["b_factor"] = result["fit"]["rmsd"], result["mean_b"]
      if result["fit"]["core_fraction"] < .5:
        raise ValueError("Less than half the selected C-alpha sites agree. Select a smaller domain or adjust the cutoff.")
      if result["fit"]["ambiguous_core"]:
        raise ValueError("Several structural cores match equally well. Select a smaller region.")
      candidates.append((result, assessed, donor))
    except ValueError as error:
      errors.append(str(error))
  if not candidates:
    raise ValueError(errors[0] if errors else "No usable donor chain found.")
  candidates.sort(key=lambda item: (-len(item[0]["fragment"]), item[0]["rmsd"]))
  if len(candidates) > 1 and len(candidates[0][0]["fragment"]) == len(candidates[1][0]["fragment"]) and abs(candidates[0][0]["rmsd"]-candidates[1][0]["rmsd"]) < .05:
    raise ValueError("Several donor chains match equally well. Supply a single-chain prediction.")
  result, assessed, donor = candidates[0]
  result.update(assessment=assessed, donor_chain=donor["chain"], donor_sequence=donor["sequence"])
  result["source"] = os.path.basename(donor["source_path"])+" / "+donor["chain"] if donor.get("source_path") else "prediction chain "+donor["chain"]
  return result


def _af_replace_provenance(hit):
  record = hit.get("record")
  if record is None:
    return str(hit.get("label") or "local prediction")
  entry = str(record.get("entryId") or record.get("modelEntityId") or hit.get("label") or "prediction")
  accession = str(record.get("uniprotAccession") or "")
  if not accession:
    match = re.fullmatch(r"(?:AF-|BFVD-)([A-Z0-9]+(?:-\d+)?)(?:-F\d+)?", entry)
    accession = match.group(1) if match else ""
  version = record.get("latestVersion")
  downloaded_version = re.search(r"_v(\d+)\.(?:cif|pdb)(?:\.gz)?(?:$|\?)", str(record.get("cifUrl") or record.get("pdbUrl") or ""))
  if downloaded_version:
    version = downloaded_version.group(1)
  if version is not None:
    entry += " v"+str(version)
  return entry+(" (UniProt "+accession+")" if accession else "")


def _af_replace_reference(target, result):
  """Full target sequence, overlaying every observed identity, never donor mutations."""
  ordered = target["ordered"]
  if target.get("has_reference"):
    sequence = target["alignment_sequence"]
    positions = dict(target["row_map"])
  else:
    sequence = result.get("reference_sequence") or result.get("donor_sequence") or ""
    aligned = _af_replace_alignment(target["sequence"], sequence) if sequence else None
    if (aligned and not aligned["ambiguous"] and aligned["coverage"] == 1.
        and (aligned["identity"] >= .99-1e-10 or
             len(aligned["substitutions"]) <= 2)):
      positions = {spec: aligned["mapping"][i] for i, spec in enumerate(ordered)}
    else:
      # Keep known target identities and unknown-numbered gaps, rather than inventing them.
      if any(spec[2] for spec in ordered):
        sequence = target["sequence"]
        positions = {spec: i for i, spec in enumerate(ordered)}
      else:
        first, last = min(s[1] for s in ordered), max(s[1] for s in ordered)
        if last-first >= 100000:
          raise ValueError("Target numbering is too sparse for a safe sequence association.")
        sequence = "X"*(last-first+1)
        positions = {spec: spec[1]-first for spec in ordered}
  letters = list(_register_clean_sequence(sequence))
  if len(set(positions.values())) != len(positions) or set(positions) != set(ordered):
    raise ValueError("Cannot associate the target sequence with an ambiguous residue mapping.")
  for index, spec in enumerate(ordered):
    position = positions[spec]
    if not isinstance(position, int) or not 0 <= position < len(letters):
      raise ValueError("Target sequence mapping lies outside its reference.")
    letters[position] = target["sequence"][index]
  origins = {spec[1]-position for spec, position in positions.items() if not spec[2]}
  origin = next(iter(origins)) if len(origins) == 1 else None
  return "".join(letters), origin


def _af_replace_validate_atoms(fragment, dictionaries=None):
  """Check exact native dictionary identifiers before any source-model edit."""
  dictionaries = {} if dictionaries is None else dictionaries
  getter = getattr(coot, "monomer_restraints_py", None)
  if not callable(getter):
    raise ValueError("This Coot build cannot validate prediction atom names safely.")
  for spec, residue in fragment.items():
    name = residue["name"]
    if name not in dictionaries:
      restraints = getter(name)
      rows = restraints.get("_chem_comp_atom", []) if isinstance(restraints, dict) else []
      dictionaries[name] = {row[0]: str(row[1]).strip().upper() for row in rows}
      if not dictionaries[name]:
        raise ValueError("No atom dictionary available for "+name+"; original unchanged.")
    expected = dictionaries[name]
    for identity, properties, _xyz in residue["atoms"]:
      atom_name = identity[0]
      if atom_name not in expected:
        raise ValueError(f"Prediction atom {spec} {name} {atom_name!r} does not match Coot's dictionary; original unchanged.")
      if str(properties[2]).strip().upper() != expected[atom_name]:
        raise ValueError(f"Prediction atom {spec} {atom_name!r} has the wrong element; original unchanged.")
  return dictionaries


def _af_replace_mutate_candidate(candidate, mutations, b_factor):
  if not mutations:
    return
  before = _model_coordinate_snapshot(candidate)
  for spec, name in mutations.items():
    if spec not in before or name not in set(_REGISTER_AA.values()):
      raise ValueError("Invalid target residue for prediction mutation.")
    if coot.mutate(candidate, *spec, name) != 1:
      raise ValueError(f"Could not mutate prediction residue {spec} to {name}; original unchanged.")
  after = _model_coordinate_snapshot(candidate)
  changes = []
  for spec, name in mutations.items():
    row = after.get(spec)
    if row is None or row["name"] != name:
      raise ValueError("Prediction mutation did not produce the target residue type.")
    old_atoms = {tuple(a[0]): a for a in before[spec]["atoms"]}
    new_atoms = {tuple(a[0]): a for a in row["atoms"]}
    for identity, atom in old_atoms.items():
      if identity[0].strip() in {"N", "CA", "C", "O"}:
        updated = new_atoms.get(identity)
        if updated is None or max(abs(a-b) for a, b in zip(atom[2], updated[2])) > 1e-5:
          raise ValueError("Mutation changed the prediction backbone; original unchanged.")
    changes.extend([candidate, *spec, *atom[0], "B", float(b_factor)] for atom in row["atoms"])
  coot.set_atom_attributes_py(changes)


def _af_replace_apply(target, result, rigid_map=None):
  model, chain = target["model"], target["chain"]
  _ncs_require_idle(model)
  if coot.molecule_name(model) != target["name"] or _model_coordinate_snapshot(model) != target["snapshot"]:
    raise ValueError("The original model changed. Close this tool and select the region again.")
  if "sequences" in target and sorted(coot.sequence_info_py(model) or []) != sorted(target["sequences"]):
    raise ValueError("The model's sequence association changed. Close this tool and select the region again.")
  if coot.backup_state(model) != 1:
    raise ValueError("Enable Coot backups before replacing coordinates.")
  if any(len(s[0]) > 1 for s in target["snapshot"]) and not target["name"].endswith((".cif", ".mmcif", ".mmCIF")):
    raise ValueError("Save the target as mmCIF and reopen this tool first. PDB backups cannot safely preserve multi-character chain IDs.")
  reference = _af_replace_reference(target, result)
  fragment = result["fragment"]
  dictionaries = _af_replace_validate_atoms(fragment)
  expression, _ = _ncs_symmetry_expression(fragment, dict(groups=[], missing=[]))
  view = _capture_view_state()
  candidate = coot.add_molecule_py(expression, "AlphaFold replacement (temporary).cif")
  _restore_view_state(view)
  if candidate == model or not valid_model_molecule_qm(candidate):
    raise RuntimeError("Could not create the replacement fragment.")
  try:
    coot.set_mol_displayed(candidate, 0)
    mutations = result.get("mutation_targets", {})
    _af_replace_mutate_candidate(candidate, mutations, result["b_factor"])
    if rigid_map is not None:
      if not coot.is_valid_map_molecule(rigid_map):
        raise ValueError("The refinement map was closed. Disable rigid fitting or reopen the tool.")
      previous_map = coot.imol_refinement_map()
      previous_replacement = coot.refinement_immediate_replacement_state()
      try:
        coot.set_imol_refinement_map(rigid_map)
        coot.set_refinement_immediate_replacement(1)
        coot.rigid_body_refine_by_atom_selection(candidate, "//")
        coot.accept_regularizement()
      finally:
        if coot.refinement_already_ongoing_p():
          coot.clear_up_moving_atoms()
        coot.set_imol_refinement_map(previous_map)
        coot.set_refinement_immediate_replacement(previous_replacement)
    actual = _model_coordinate_snapshot(candidate)
    _af_replace_validate_atoms(actual, dictionaries)
    if rigid_map is not None:
      # Unsupported or unmapped residues retain their original coordinates.
      for spec in result.get("preserved_specs", []):
        if spec in actual:
          original_row = fragment[spec]
          for atom in original_row["atoms"]:
            coot.set_atom_attributes_py([[candidate, *spec, *atom[0], axis, atom[2][i]] for i, axis in enumerate("xyz")])
      actual = _model_coordinate_snapshot(candidate)
    if actual.keys() != fragment.keys() or any(actual[s]["name"] != mutations.get(s, fragment[s]["name"]) for s in actual):
      raise ValueError("The replacement fragment's residue identities changed unexpectedly.")
    specs = sorted(actual)
    plan = _register_merge_plan(target["snapshot"], actual, chain, specs[0][1], specs[-1][1], 0,
                                selected_specs=specs)
    _apply_register_comparison_merge(model, dict(model=candidate), chain, plan, target["signature"],
                                     _register_shift_model_signature(candidate), reference=reference, preserve_sequences=True)
    kept = len(set(specs).intersection(result.get("preserved_specs", [])))
    return dict(replaced=len(specs), donor_replaced=len(specs)-kept, kept=kept, trimmed=len(plan["trim"]),
                first=specs[0], last=specs[-1], b_factor=result["b_factor"], source=result.get("source", "prediction"),
                sequence_associated=True, sequence_origin=reference[1], mutated=len(mutations))
  finally:
    if valid_model_molecule_qm(candidate):
      coot.close_molecule(candidate)


def _af_replace_wire(value, decode=False):
  """JSON-only IPC, preserving author-spec tuple keys without executable data."""
  if decode:
    if isinstance(value, list):
      return [_af_replace_wire(v, True) for v in value]
    if isinstance(value, dict):
      if "tuple" in value:
        return tuple(_af_replace_wire(v, True) for v in value["tuple"])
      return {_af_replace_wire(k, True): _af_replace_wire(v, True) for k, v in value["dict"]}
    return value
  if isinstance(value, dict):
    return {"dict": [[_af_replace_wire(k), _af_replace_wire(v)] for k, v in value.items()]}
  if isinstance(value, tuple):
    return {"tuple": [_af_replace_wire(v) for v in value]}
  if isinstance(value, list):
    return [_af_replace_wire(v) for v in value]
  return value


def _af_replace_job(operation, payload, progress=None):
  target = payload["target"]
  if operation == "find":
    records = _af_replace_find_models(target["query"], payload["identifier"], progress,
                                      include_bfvd=payload["include_bfvd"])
    hits = []
    for record in records:
      sequence = str(record.get("sequence") or record.get("uniprotSequence") or "").upper()
      try:
        assessed = _af_replace_assess(target, sequence)
      except ValueError:
        continue
      hits.append(dict(label=str(record.get("entryId") or record.get("modelEntityId")),
                       record=record, assessment=assessed))
    return sorted(hits, key=lambda h: (-h["assessment"]["identity"], h["label"]))
  if operation == "local":
    path = payload["path"]
    if os.path.getsize(path) > 64*1024*1024:
      raise ValueError("Choose a prediction smaller than 64 MB.")
    hits = []
    for donor in _af_replace_read_model(path):
      try:
        assessed = _af_replace_assess(target, donor["sequence"])
      except ValueError:
        continue
      hits.append(dict(label=f"{os.path.basename(path)} / {donor['chain']}", donor=donor, assessment=assessed))
    return hits
  if operation != "prepare":
    raise ValueError("Unknown prediction task.")
  hit = payload["hit"]
  source = _af_replace_provenance(hit)
  started = time.monotonic()
  if "donor" in hit:
    donors = [hit["donor"]]
  else:
    if progress:
      progress("Downloading "+source+"...")
    path = _af_replace_download(hit["record"])
    if progress:
      progress("Reading "+source+"...")
    donors = _af_replace_read_model(path)
  downloaded = time.monotonic()
  if progress:
    progress("Aligning "+source+"...")
  result = _af_replace_prepare(target, donors, payload["cutoff"])
  result["source"] = source
  record = hit.get("record", {})
  result["reference_sequence"] = record.get("sequence") or record.get("uniprotSequence") or result["donor_sequence"]
  result["timings"] = dict(download_and_read=downloaded-started, alignment=time.monotonic()-downloaded)
  if result["assessment"]["identity"] < 1.-1e-10 and not payload["accepted_close"]:
    raise ValueError("The downloaded model has substitutions. Confirm the close match before replacing.")
  return result


def _af_replace_worker_main():
  import sys
  with open(sys.argv[1]) as handle:
    request = _af_replace_wire(json.load(handle), True)
  def progress(message):
    print(json.dumps(dict(progress=str(message))), flush=True)
  try:
    value = _af_replace_job(request["operation"], request["payload"], progress)
    response = dict(result=_af_replace_wire(value))
  except Exception as error:
    response = dict(error=str(error))
  with open(sys.argv[2], "w") as handle:
    json.dump(response, handle)


def _af_replace_start_job(operation, payload):
  """No Python worker thread: Coot's native GTK loop can starve its interpreter."""
  import inspect
  import shutil
  import subprocess
  import sys
  names = ("_register_clean_sequence", "_ncs_operator", "_ncs_transform", "_ncs_rigid_fit",
           "_af_replace_alignment", "_af_replace_ca", "_af_replace_robust_fit", "_af_replace_ca_distances",
           "_af_replace_fragment", "_af_replace_read_model", "_af_replace_download",
           "_af_replace_uniprot_json", "_af_replace_uniprot_accessions", "_af_replace_afdb_json",
           "_af_replace_bfvd_models", "_af_replace_find_models", "_af_replace_assess", "_af_replace_prepare",
           "_af_replace_provenance", "_af_replace_wire", "_af_replace_job", "_af_replace_worker_main")
  source = "import copy, hashlib, json, math, os, re, tempfile, time\nimport gemmi\n"
  source += "_REGISTER_AA = "+repr(_REGISTER_AA)+"\n"
  source += "\n\n".join(inspect.getsource(globals()[name]) for name in names)
  source += "\n_af_replace_worker_main()\n"
  version = f"python{sys.version_info.major}.{sys.version_info.minor}"
  candidates = [os.path.join(prefix, "bin", name) for prefix in (sys.prefix, sys.base_prefix)
                for name in (version, "python3")]
  candidates.extend((shutil.which(version), shutil.which("python3")))
  python = next((p for p in candidates if p and os.path.isfile(p) and os.access(p, os.X_OK)), None)
  if python is None:
    raise ValueError("No standalone Python found for prediction lookup.")
  directory = tempfile.TemporaryDirectory(prefix="coot-alphafold-task-")
  folder = directory.name
  request, response, log_path = [os.path.join(folder, name) for name in ("request.json", "result.json", "progress.jsonl")]
  log = reader = process = None
  try:
    with open(request, "w") as handle:
      json.dump(_af_replace_wire(dict(operation=operation, payload=payload)), handle)
    log = open(log_path, "w")
    reader = open(log_path)
    env = dict(os.environ, PYTHONDONTWRITEBYTECODE="1")
    for name in ("PYTHONHOME", "PYTHONPATH", "PYTHONSTARTUP", "PYTHONUSERBASE"):
      env.pop(name, None)
    process = subprocess.Popen([python, "-u", "-c", source, request, response],
        stdin=subprocess.DEVNULL, stdout=log, stderr=log, env=env)
    return dict(process=process, directory=directory, log=log, reader=reader, response=response,
                deadline=time.monotonic()+(90 if operation == "find" else 60), tail="")
  except Exception:
    if process is not None:
      process.kill()
      process.wait()
    for handle in (log, reader):
      if handle is not None:
        handle.close()
    directory.cleanup()
    raise


def _af_replace_stop_job(job):
  if job is None:
    return
  process = job.get("process")
  if process is not None and process.poll() is None:
    process.kill()
    process.wait()
  for name in ("reader", "log"):
    if job.get(name) is not None:
      job[name].close()
  if job.get("directory") is not None:
    job["directory"].cleanup()


def _af_replace_dialog(model, chain, specs=None):
  try:
    if globals().get("gemmi") is None:
      raise ValueError("Gemmi is required to read AlphaFold predictions.")
    target = _af_replace_target(model, chain, specs)
  except Exception as error:
    info_dialog(str(error))
    return None
  previous = getattr(coot, "_trimmings_af_replace_window", None)
  if previous is not None:
    previous._af_cancel()
  glib = _coot_gui_repository_module("GLib")
  title = "Replace chain from AlphaFold" if specs is None else "Replace region from AlphaFold"
  window = Gtk.Window(title=title)
  window.set_default_size(620, 300)
  box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=10)
  for side in ("top", "bottom", "start", "end"):
    getattr(box, "set_margin_"+side)(12)
  window.set_child(box)
  first, last = target["specs"][0], target["specs"][-1]
  label = Gtk.Label(label=f"#{model} {os.path.basename(target['name'])}\n{chain}:{first[1]}{first[2]}-{last[1]}{last[2]} ({len(target['specs'])} residues)", xalign=0)
  label.set_wrap(True)
  box.append(label)
  query_row = Gtk.Box(spacing=8)
  accession = Gtk.Entry()
  accession.set_placeholder_text("UniProt / AFDB / BFVD ID (optional)")
  accession.set_hexpand(True)
  query_row.append(accession)
  search = Gtk.Button(label="Find model")
  search.set_tooltip_text("Looks up AFDB by sequence and BFVD via UniProt accessions. Exact UniParc lookup sends a sequence checksum, not coordinates. AFDB similarity discovery checks up to 50 hits.")
  query_row.append(search)
  box.append(query_row)
  choices = Gtk.ComboBoxText()
  choices.set_hexpand(True)
  box.append(choices)
  differences = Gtk.CheckButton(label="Use close match; mutate prediction to model sequence")
  differences.set_visible(False)
  box.append(differences)
  advanced = Gtk.Expander(label="Options / local prediction")
  grid = Gtk.Grid(column_spacing=10, row_spacing=8)
  advanced.set_child(grid)
  grid.attach(Gtk.Label(label="C-alpha cutoff (A)", xalign=0), 0, 0, 1, 1)
  cutoff = Gtk.Entry()
  cutoff.set_text("2")
  cutoff.set_tooltip_text("The fitted C-alpha overlap sets the outer graft boundaries. Internal divergent loops can still be replaced. New atoms use the original region's mean B factor.")
  grid.attach(cutoff, 1, 0, 1, 1)
  rigid = Gtk.CheckButton(label="Quick rigid fit to refinement map")
  map_id = coot.imol_refinement_map()
  rigid.set_sensitive(coot.is_valid_map_molecule(map_id) and callable(getattr(coot, "rigid_body_refine_by_atom_selection", None)))
  grid.attach(rigid, 0, 1, 2, 1)
  bfvd = Gtk.CheckButton(label="Try BFVD if no AFDB model is found")
  bfvd.set_active(True)
  bfvd.set_tooltip_text("Exact full-sequence checksum -> UniProt accessions -> available BFVD models. An accession can also be entered directly. Partial/near-match discovery still uses AFDB.")
  grid.attach(bfvd, 0, 2, 2, 1)
  local = Gtk.Button(label="Use local prediction...")
  local.set_tooltip_text("Choose an AlphaFold, BFVD or other PDB/mmCIF prediction.")
  grid.attach(local, 0, 3, 2, 1)
  box.append(advanced)
  status = Gtk.Label(label="Find a model or choose a local prediction.", xalign=0)
  status.set_wrap(True)
  box.append(status)
  actions = Gtk.Box(spacing=8)
  replace = Gtk.Button(label="Replace")
  replace.set_tooltip_text("Automatically align, cut and merge with one Coot Undo. The register tool's safeguards may trim up to five adjacent residues per end; joins are not rebuilt or flexibly refined.")
  replace.set_sensitive(False)
  actions.append(replace)
  close_button = Gtk.Button(label="Close")
  actions.append(close_button)
  box.append(actions)
  search_cache = getattr(_af_replace_dialog, "_search_cache", {})
  _af_replace_dialog._search_cache = search_cache
  state = dict(closed=False, busy=False, job=0, worker=None, hits=[], completed=False,
               started=0., message="", chooser=None, applying=False, search_cache=search_cache)
  def show_message(message):
    state["message"] = str(message)
    status.set_text(str(message))
  def selected():
    index = choices.get_active_id()
    return state["hits"][int(index)] if index is not None else None
  def update(*_):
    hit = selected()
    close_match = hit is not None and hit["assessment"]["identity"] < 1.-1e-10
    differences.set_visible(close_match)
    differences.set_tooltip_text("\n".join(f"{s[0]}:{s[1]}{s[2]} {a} -> {b}" for s, a, b in hit["assessment"]["changes"]) if hit else "")
    replace.set_sensitive(not state["busy"] and not state["completed"] and hit is not None
                          and (not close_match or differences.get_active()))
  def choose(*_):
    differences.set_active(False)
    update()
  choices.connect("changed", choose)
  differences.connect("toggled", update)
  def background(operation, payload, finished):
    _af_replace_stop_job(state["worker"])
    state.update(worker=None, busy=True, job=state["job"]+1, started=time.monotonic())
    token = state["job"]
    for widget in (search, accession, choices, local, cutoff, rigid, bfvd, differences):
      widget.set_sensitive(False)
    update()
    def complete(value, error):
      if state["closed"] or state["job"] != token:
        return False
      if error is not None:
        show_message(str(error))
      else:
        try:
          finished(value)
        except Exception as problem:
          show_message(str(problem))
      state["busy"] = False
      for widget in (search, accession, choices, local, cutoff, bfvd, differences):
        widget.set_sensitive(not state["completed"])
      rigid.set_sensitive(not state["completed"] and coot.is_valid_map_molecule(map_id))
      update()
      return False
    try:
      keys = ("query", "ordered", "specs", "sequence", "alignment_sequence", "row_map")
      worker_target = {key: target[key] for key in keys if key in target}
      if operation == "prepare":
        worker_target["snapshot"] = target["snapshot"]
      state["worker"] = _af_replace_start_job(operation, dict(payload, target=worker_target))
    except Exception as error:
      complete(None, error)
      return
    def tick():
      if state["closed"] or not state["busy"] or state["job"] != token:
        return False
      job = state["worker"]
      try:
        if "value" in job:
          value, error, done = job["value"], None, True
        else:
          job["tail"] = (job["tail"]+job["reader"].read())[-16000:]
          for line in job["tail"].splitlines():
            try:
              event = json.loads(line)
              if "progress" in event:
                show_message(event["progress"])
            except (ValueError, TypeError):
              pass
          done = job["process"].poll() is not None
          if not done and time.monotonic() > job["deadline"]:
            raise RuntimeError("Prediction task timed out. Retry or use a local prediction.")
          if done:
            if not os.path.isfile(job["response"]):
              raise RuntimeError("Prediction worker failed: "+job["tail"][-1500:])
            with open(job["response"]) as handle:
              response = json.load(handle)
            error = response.get("error")
            value = _af_replace_wire(response["result"], True) if error is None else None
        if done:
          _af_replace_stop_job(job)
          state["worker"] = None
          return complete(value, error)
      except Exception as error:
        _af_replace_stop_job(job)
        state["worker"] = None
        return complete(None, error)
      status.set_text(f"{state['message']} ({time.monotonic()-state['started']:.0f}s)")
      return True
    glib.timeout_add(50, tick)
  def accept_hits(hits):
    state["hits"] = hits
    choices.remove_all()
    for index, hit in enumerate(hits):
      identity = 100.*hit["assessment"]["identity"]
      choices.append(str(index), f"{hit['label']} | {identity:.2f}% identity")
    if hits:
      choices.set_active(0)
      show_message("Select a prediction, then Replace. Merging and boundary trimming are automatic.")
    else:
      show_message("No qualifying match in the returned hits. Try an accession or a local prediction.")
  def find(*_):
    if state["busy"] or state["completed"]:
      return
    identifier = accession.get_text().strip()
    include_bfvd = bfvd.get_active()
    key = (identifier, include_bfvd, target["query"], target["sequence"],
           target["alignment_sequence"], tuple(target["ordered"]), tuple(target["specs"]),
           tuple(sorted(target["row_map"].items())))
    cached = state["search_cache"].get(key)
    if cached is not None and time.monotonic()-cached[0] < 3600:
      accept_hits(cached[1])
      return
    def found(hits):
      if hits:
        if len(state["search_cache"]) >= 32:
          state["search_cache"].pop(next(iter(state["search_cache"])))
        state["search_cache"][key] = (time.monotonic(), hits)
      accept_hits(hits)
    show_message("Finding predictions...")
    background("find", dict(identifier=identifier, include_bfvd=include_bfvd), found)
  def local_file(*_):
    if state["busy"] or state["completed"]:
      return
    chooser = Gtk.FileChooserNative.new("Choose prediction", window, Gtk.FileChooserAction.OPEN, "Open", "Cancel")
    state["chooser"] = chooser
    def response(dialog, response_id):
      path = dialog.get_file().get_path() if response_id == Gtk.ResponseType.ACCEPT else None
      dialog.destroy()
      state["chooser"] = None
      if path is None or state["closed"]:
        return
      show_message("Reading local prediction...")
      background("local", dict(path=path), accept_hits)
    chooser.connect("response", response)
    chooser.show()
  def apply(*_):
    if state["busy"] or state["completed"] or selected() is None:
      return
    hit = selected()
    accepted_close = differences.get_active()
    cutoff_text, fit_map = cutoff.get_text(), map_id if rigid.get_active() else None
    def finished(result):
      state["applying"] = True
      close_button.set_sensitive(False)
      show_message("Merging replacement...")
      merge_started = time.monotonic()
      try:
        outcome = _af_replace_apply(target, result, fit_map)
      finally:
        state["applying"] = False
        close_button.set_sensitive(True)
      state["completed"] = True
      for widget in (search, accession, choices, local, cutoff, rigid, bfvd, differences):
        widget.set_sensitive(False)
      a, b = outcome["first"], outcome["last"]
      show_message(f"Used {outcome['source']}.\nReplaced {outcome['donor_replaced']}/{len(target['specs'])} residues at {chain}:{a[1]}{a[2]}-{b[1]}{b[2]}; "
                   f"trimmed {outcome['trimmed']}. B = {outcome['b_factor']:.2f}. Sequence associated. Undo available.")
      state["outcome"] = outcome
      print("AlphaFold replacement timings:", dict(result.get("timings", {}), merge=time.monotonic()-merge_started))
      print("AlphaFold replacement:", state["message"].replace("\n", " "))
      add_status_bar_text(state["message"])
    show_message("Preparing replacement...")
    background("prepare", dict(hit=hit, cutoff=cutoff_text, accepted_close=accepted_close), finished)
  def close(*_):
    if state["closed"]:
      return True
    if state["applying"]:
      show_message("Finishing replacement...")
      return True
    state["closed"] = True
    _af_replace_stop_job(state["worker"])
    state["worker"] = None
    if state["chooser"] is not None:
      state["chooser"].destroy()
    if getattr(coot, "_trimmings_af_replace_window", None) is window:
      coot._trimmings_af_replace_window = None
    window.destroy()
    return True
  search.connect("clicked", find)
  local.connect("clicked", local_file)
  replace.connect("clicked", apply)
  close_button.connect("clicked", close)
  window.connect("close-request", close)
  window._af_cancel = close
  window.af_replace_state = state
  state["widgets"] = dict(search=search, accession=accession, choices=choices, differences=differences,
                          cutoff=cutoff, rigid=rigid, replace=replace, status=status, close=close_button)
  coot._trimmings_af_replace_window = window
  window.present()
  return window


def replace_chain_from_alphafold():
  context = _active_chain_context_or_status()
  if context:
    return _af_replace_dialog(context["mol_id"], context["chain_id"])


def replace_region_from_alphafold():
  markers = []
  def clear():
    while markers:
      coot.close_generic_object(markers.pop())
  def picked(spec, count):
    _mark_register_endpoint(spec, "cyan" if count == 1 else "orange", markers, "AlphaFold replacement endpoint")
  def selected(first, last):
    try:
      if _clicked_same_chain_residue_range(first, last) is not None:
        specs = _clicked_residue_specs(first, last)
        if specs:
          return _af_replace_dialog(_click_spec_imol(first), _click_spec_chain_id(first), specs)
    finally:
      clear()
  return _script_user_defined_click(2, selected, on_pick=picked, cleanup=clear,
      prompt="Replace region from AlphaFold: click start (cyan), then end (orange). Tab cancels.")


def _register_worker_settings():
  """Only public, readable settings; setters without getters retain worker defaults."""
  pairs = (("get_cryo_em_refinement", "set_cryo_em_refinement"),
           ("matrix_state", "set_matrix"),
           ("secondary_structure_restraints_type", "set_secondary_structure_restraints_type"),
           ("refine_ramachandran_angles_state", "set_refine_ramachandran_angles"),
           ("refine_ramachandran_restraints_weight", "set_refine_ramachandran_restraints_weight"),
           ("refine_with_torsion_restraints_state", "set_refine_with_torsion_restraints"),
           ("get_refinement_geman_mcclure_alpha", "set_refinement_geman_mcclure_alpha"),
           ("get_refine_use_noughties_physics_state", "set_refine_use_noughties_physics"),
           ("refinement_move_atoms_with_zero_occupancy_state", "set_refinement_move_atoms_with_zero_occupancy"),
           ("rotamer_search_mode_state", "set_rotamer_search_mode"),
           ("rotamer_auto_fit_do_post_refine_state", "set_rotamer_auto_fit_do_post_refine"),
           ("use_only_extra_torsion_restraints_for_torsions_state", "set_use_only_extra_torsion_restraints_for_torsions"))
  settings = []
  for getter, setter in pairs:
    if callable(getattr(coot, getter, None)) and callable(getattr(coot, setter, None)):
      value = getattr(coot, getter)()
      if not isinstance(value, (int, float, bool)) or not math.isfinite(value):
        raise ValueError(f"Cannot transfer refinement setting {getter}.")
      settings.append([setter, [value], getter])
  if callable(getattr(coot, "planar_peptide_restraints_state", None)):
    enabled = coot.planar_peptide_restraints_state()
    settings.append(["add_planar_peptide_restraints" if enabled else "remove_planar_peptide_restraints", [], None])
  return settings


def _register_worker_launcher():
  # Prefer this Coot installation over another executable earlier on PATH.
  module = os.path.realpath(getattr(coot, "__file__", ""))
  parent = os.path.dirname(module)
  while parent and parent != os.path.dirname(parent):
    candidate = os.path.join(parent, "bin", "coot")
    if os.path.isfile(candidate) and os.access(candidate, os.X_OK):
      return candidate
    parent = os.path.dirname(parent)
  candidate = shutil.which("coot")
  if candidate:
    return candidate
  raise RuntimeError("Cannot locate a Coot launcher for isolated refinement.")


def _register_worker_limit(map_bytes, jobs, cpu_count=None, memory_bytes=None):
  """Reserve CPU capacity and a conservative per-process map/FFT memory budget."""
  cpus = _global_fit_worker_count() if cpu_count is None else max(1, int(cpu_count)-1)
  if memory_bytes is None:
    try:
      memory_bytes = os.sysconf("SC_PHYS_PAGES")*os.sysconf("SC_PAGE_SIZE")
    except (ValueError, OSError, AttributeError):
      memory_bytes = 2*1024**3
  per_worker = 256*1024**2 + 16*max(0, int(map_bytes))
  memory_limit = max(1, int(memory_bytes*.25)//per_worker)
  return max(1, min(int(jobs), cpus, memory_limit))


def _register_map_fingerprint(map_id, points):
  if not coot.is_valid_map_molecule(map_id):
    raise ValueError("The comparison map was closed.")
  values = [float(coot.density_at_point(map_id, *point)) for point in points]
  if not all(math.isfinite(v) for v in values):
    raise ValueError("Comparison map contains non-finite density.")
  return [coot.molecule_name(map_id), list(coot.cell_py(map_id)), coot.space_group_py(map_id), values]


def _register_worker_atom_snapshot(model):
  """Headless-safe equivalent of the graphical rigid-fit identity check."""
  result = {}
  for entry in coot.python_representation_kk(model):
    for chain, residues in entry:
      for number, ins, name, atoms in residues:
        for atom in atoms:
          key = (chain, number, ins, name, *atom[0], repr(atom[1]))
          xyz = tuple(atom[2])
          if key in result or len(xyz) != 3 or not all(math.isfinite(v) for v in xyz):
            raise ValueError("Invalid worker atom identities/coordinates.")
          result[key] = xyz
  if not result:
    raise ValueError("Empty worker fragment.")
  return result


def _register_worker_main():
  """Headless Coot entry; every native call runs on this process's main thread."""
  config = json.load(open(os.environ["COOT_REGISTER_CONFIG"]))
  folder = os.path.dirname(os.environ["COOT_REGISTER_CONFIG"])
  def publish(index, result):
    path = os.path.join(folder, f"result-{index}.json")
    with open(path+".tmp", "w") as handle:
      json.dump(result, handle, allow_nan=False)
    os.replace(path+".tmp", path)
  try:
    if coot.coot_version() != config["version"]:
      raise RuntimeError("Worker and interactive Coot versions differ.")
    model = coot.add_molecule_py(config["representation"], "Register worker input")
    map_id = coot.handle_read_ccp4_map(config["map_path"], 0)
    if not coot.is_valid_model_molecule(model) or not coot.is_valid_map_molecule(map_id):
      raise RuntimeError("Coot could not load the exported fragment or map.")
    coot.set_imol_refinement_map(map_id)
    values = [float(coot.density_at_point(map_id, *p)) for p in config["probes"]]
    if any(not math.isclose(a, b, abs_tol=1e-6, rel_tol=1e-5) for a, b in zip(values, config["probe_values"])):
      raise RuntimeError("Exported map does not reproduce the current refinement-map density.")
    coot.turn_off_backup(model)
    for name, dictionary in config["dictionaries"].items():
      if not coot.set_monomer_restraints_py(name, dictionary):
        raise RuntimeError(f"Could not transfer {name} geometry dictionary.")
    for setter, args, getter in config["settings"]:
      getattr(coot, setter)(*args)
      if getter and not math.isclose(float(getattr(coot, getter)()), float(args[0]), rel_tol=1e-5):
        raise RuntimeError(f"Worker did not accept {setter}.")
    for job in config["jobs"]:
      candidate = None
      try:
        candidate = _build_register_comparison_fragment(model, config["chain"], config["start"], config["end"],
            job["shift"], job["sequence"], map_id, rigid_fit=config["rigid_fit"], flexible=True,
            prepare=config["prepare"])
        candidate["representation"] = coot.python_representation_kk(candidate.pop("model"))
        candidate["offset"] = job["offset"]
        publish(job["index"], dict(index=job["index"], candidate=candidate))
      except Exception as error:
        publish(job["index"], dict(index=job["index"], error=str(error)))
      finally:
        # The worker is disposable, but retain one source/map across its jobs.
        for number in range(coot.graphics_n_molecules()):
          if number not in (model, map_id) and coot.is_valid_model_molecule(number):
            coot.close_molecule(number)
    coot.coot_no_state_real_exit(0)
  except Exception as error:
    for job in config["jobs"]:
      publish(job["index"], dict(index=job["index"], error="Worker setup failed: "+str(error)))
    coot.coot_no_state_real_exit(1)


def _make_register_worker_source():
  import inspect
  functions = (_coot_text_arg, _coot_int_arg, _coot_residue_spec_tuple, _coot_residue_spec_from_spec,
      _distance_sq, _grouped_model_edit, _mark_model_changed, _atom_selection_for_residue_range,
      _register_collapse_alternates, _register_fit_fixed_backbone_rotamer, _register_sidechain_correlation,
      _build_register_comparison_fragment, _register_worker_atom_snapshot, _register_worker_main)
  header = ("import math, os, re, json\nimport coot\nfrom contextlib import contextmanager\n"
            "from coot_utils import residue_spec_to_chain_id, residue_spec_to_res_no, residue_spec_to_ins_code\n"
            "valid_model_molecule_qm = coot.is_valid_model_molecule\n"
            "_MODEL_EDIT_EPOCHS = {}\n_supports_direct_user_defined_colouring = lambda: False\n")
  return (header+"_REGISTER_AA = "+repr(_REGISTER_AA)+"\n"+
          "\n".join(inspect.getsource(f) for f in functions)+
          "\n_rigid_fit_atom_snapshot = _register_worker_atom_snapshot\n_register_worker_main()\n")


try:
  # inspect uses on-disk line numbers. Freeze while file and loaded code match,
  # not after an installed-script update during a long-running Coot session.
  _REGISTER_WORKER_SOURCE_AT_LOAD = _make_register_worker_source()
except (OSError, TypeError):
  _REGISTER_WORKER_SOURCE_AT_LOAD = None


def _register_worker_source():
  source = globals().get("_REGISTER_WORKER_SOURCE_AT_LOAD")
  return source if source is not None else _make_register_worker_source()


def _register_worker_stop_process(process):
  """Coot launchers may be shells: stop their private group, not just the shell."""
  import signal
  import subprocess
  try:
    if os.name == "posix":
      try:
        os.killpg(process.pid, signal.SIGTERM)
      except ProcessLookupError:
        pass
    elif process.poll() is None:
      process.terminate()
    try:
      process.wait(timeout=1.)
    except subprocess.TimeoutExpired:
      pass
  finally:
    if os.name == "posix":
      try:
        os.killpg(process.pid, signal.SIGKILL)
      except ProcessLookupError:
        pass
    elif process.poll() is None:
      process.kill()
    process.wait(timeout=5.)


def _register_workers_monitor(pool):
  """Only filesystem/process operations here. Never call Coot or GTK off-thread."""
  import subprocess
  processes = []
  seen = set()
  failures = {}
  def missing_result(process, log, home, started, timed_out):
    elapsed = time.monotonic()-started
    code = process.poll()
    if timed_out:
      reason = f"Coot worker timed out after {elapsed:.1f}s"
    elif code is not None and code < 0:
      import signal
      try:
        label = signal.Signals(-code).name
      except ValueError:
        label = str(-code)
      reason = f"Coot worker terminated by {label} after {elapsed:.1f}s"
    else:
      reason = f"Coot worker exited with status {code} after {elapsed:.1f}s"
    log.flush()
    try:
      with open(os.path.join(home, "worker.log"), "rb") as handle:
        handle.seek(0, os.SEEK_END)
        handle.seek(max(0, handle.tell()-8192))
        tail = handle.read().decode("utf-8", errors="replace").strip()
    except OSError as error:
      tail = f"Could not read worker log: {error}"
    import tempfile
    details = dict(reason=reason, returncode=code, elapsed=elapsed, log=tail)
    try:
      with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", prefix="coot-register-worker-failure-",
                                       suffix=".log", delete=False) as handle:
        handle.write(reason+"; no candidate returned.\n\n"+tail+"\n")
        details["path"] = handle.name
    except OSError:
      pass
    pool.setdefault("diagnostics", []).append(details)
    print(reason+"; no candidate returned.\n"+tail)
    last = tail.splitlines()[-1][:240] if tail else "No worker log output."
    return reason+"; no candidate returned. "+last+(" Details: "+details["path"] if "path" in details else "")
  try:
    for path, jobs in pool["configs"]:
      if pool["cancel"].is_set():
        break
      home = os.path.dirname(path)
      environment = dict(os.environ, HOME=home, XDG_CONFIG_HOME=home+"/config", XDG_STATE_HOME=home+"/state",
          XDG_CACHE_HOME=home+"/cache", COOT_REGISTER_CONFIG=path, COOT_N_THREADS="1",
          OPENBLAS_NUM_THREADS="1", OMP_NUM_THREADS="1", VECLIB_MAXIMUM_THREADS="1", PYTHONDONTWRITEBYTECODE="1")
      for key in ("PYTHONHOME", "PYTHONPATH", "PYTHONSTARTUP", "PYTHONUSERBASE"):
        environment.pop(key, None)
      log = open(os.path.join(home, "worker.log"), "w")
      try:
        process = subprocess.Popen([pool["launcher"], "--no-graphics", "--no-startup-scripts", "--no-state-script",
                                   "--no-guano", "--script", pool["script"]], cwd=home, env=environment,
                                   stdin=subprocess.DEVNULL, stdout=log, stderr=subprocess.STDOUT,
                                   start_new_session=os.name == "posix")
      except Exception:
        log.close()
        raise
      processes.append((process, log, home, jobs, time.monotonic()))
    pool["events"].put(("started", len(processes)))
    while processes and not pool["cancel"].is_set():
      active = False
      for process, log, home, jobs, started in processes:
        running = process.poll() is None
        timed_out = running and time.monotonic()-started > pool.get("timeout", 120+180*len(jobs))
        if timed_out:
          _register_worker_stop_process(process)
          running = False
        active |= running
        for job in jobs:
          index = job["index"]
          if index in seen:
            continue
          path = os.path.join(home, f"result-{index}.json")
          if os.path.isfile(path):
            if os.path.getsize(path) > 32*1024**2:
              raise RuntimeError("Worker result exceeded the safety limit.")
            with open(path) as handle:
              result = json.load(handle)
            if result.get("index") != index:
              raise RuntimeError("Worker returned the wrong job identifier.")
            seen.add(index)
            pool["events"].put(("result", result))
          elif not running:
            seen.add(index)
            if home not in failures:
              failures[home] = missing_result(process, log, home, started, timed_out)
            message = failures[home]
            pool["events"].put(("result", dict(index=index, error=message)))
      if not active or len(seen) == len(pool["jobs"]):
        break
      pool["cancel"].wait(.05)
  except Exception as error:
    pool["events"].put(("error", str(error)))
  finally:
    for process, log, _home, _jobs, _started in processes:
      try:
        if process.poll() is None or pool["cancel"].is_set():
          _register_worker_stop_process(process)
        else:
          process.wait(timeout=1.)
      except (OSError, subprocess.TimeoutExpired):
        pass
      log.close()
    try:
      pool["owner"].cleanup()
    except Exception as error:
      pool["events"].put(("error", "Could not remove worker temporary files: "+str(error)))
    finally:
      pool["done"].set()
      pool["events"].put(("done", pool["cancel"].is_set()))


def _register_workers_start(source, chain, start, end, targets, map_id, rigid_fit=False, prepare=True):
  """Snapshot native state on the GUI thread; start only pure orchestration off-thread."""
  import queue
  import threading
  required = ("export_map", "python_representation_kk", "add_molecule_py", "set_monomer_restraints_py",
              "monomer_restraints_py", "coot_version", "density_at_point", "cell_py", "space_group_py",
              "matrix_state", "set_matrix", "secondary_structure_restraints_type", "set_secondary_structure_restraints_type")
  if any(not callable(getattr(coot, name, None)) for name in required):
    raise RuntimeError("This Coot build lacks the safe isolated-refinement export/import APIs.")
  if coot.refinement_already_ongoing_p():
    raise ValueError("Accept/cancel current refinement before starting workers.")
  snapshot = _model_coordinate_snapshot(source)
  selected = [[number, ins, record["name"], record["atoms"]] for (ch, number, ins), record in snapshot.items()
              if ch == chain and start <= number <= end and record["atoms"]]
  if len(selected) != end-start+1:
    raise ValueError("The worker input range is incomplete.")
  representation = [[[chain, selected]]]
  points = [atom[2] for _n, _i, _name, atoms in selected for atom in atoms]
  # Bounded local probes detect changed/replaced target density before import.
  anchors = points[::max(1, len(points)//32)][:32]
  probes = [[float(p[i])+(2. if i == axis else 0.) for i in range(3)] for p in anchors for axis in range(3)]
  fingerprint = _register_map_fingerprint(map_id, probes)
  names = {row[2] for row in selected} | {_REGISTER_AA[letter] for _offset, sequence in targets for letter in sequence}
  dictionaries = {}
  for name in sorted(names):
    getter = getattr(coot, "monomer_restraints_for_molecule_py", None)
    dictionary = getter(name, source) if callable(getter) else coot.monomer_restraints_py(name)
    if not isinstance(dictionary, dict) or not dictionary.get("_chem_comp_atom"):
      raise ValueError(f"No transferable geometry dictionary for {name}.")
    dictionaries[name] = dictionary
  owner = tempfile.TemporaryDirectory(prefix="coot-register-workers-")
  try:
    map_path = os.path.join(owner.name, "refinement.map")
    coot.export_map(map_id, map_path)
    if not os.path.isfile(map_path) or os.path.getsize(map_path) < 1024:
      raise RuntimeError("Coot could not export the current refinement map.")
    if _register_map_fingerprint(map_id, probes) != fingerprint:
      raise RuntimeError("The refinement map changed while it was being exported.")
    launcher = _register_worker_launcher()
    settings = _register_worker_settings()
    script = os.path.join(owner.name, "register_worker.py")
    with open(script, "w") as handle:
      handle.write(_register_worker_source())
    jobs = [dict(index=i, offset=offset, shift=offset if prepare else 0, sequence=sequence)
            for i, (offset, sequence) in enumerate(targets)]
    count = _register_worker_limit(os.path.getsize(map_path), len(jobs))
    configs = []
    for index in range(count):
      home = os.path.join(owner.name, str(index))
      os.mkdir(home)
      path = os.path.join(home, "config.json")
      assigned = jobs[index::count]
      config = dict(representation=representation, chain=chain, start=start, end=end,
          map_path=map_path, dictionaries=dictionaries, settings=settings, jobs=assigned,
          version=coot.coot_version(), rigid_fit=bool(rigid_fit), prepare=bool(prepare),
          probes=probes, probe_values=fingerprint[-1])
      with open(path, "w") as handle:
        json.dump(config, handle, allow_nan=False)
      configs.append((path, assigned))
    pool = dict(owner=owner, configs=configs, jobs=jobs, script=script, launcher=launcher,
                events=queue.Queue(), cancel=threading.Event(), done=threading.Event(),
                count=count, probes=probes, fingerprint=fingerprint,
                source=source, source_name=coot.molecule_name(source), source_snapshot=snapshot,
                map=map_id, chain=chain, start=start, end=end, prepare=prepare)
    threading.Thread(target=_register_workers_monitor, args=(pool,), name="coot-register-workers", daemon=True).start()
    return pool
  except Exception:
    owner.cleanup()
    raise


def _register_validate_worker_result(candidate, job, chain, start, end):
  """Validate coordinates, identities and score coverage before creating a GUI model."""
  if candidate.get("offset") != job["offset"] or candidate.get("sequence") != job["sequence"] or candidate.get("flexible") is not True:
    raise ValueError("Worker returned the wrong register/sequence.")
  representation = candidate["representation"]
  if len(representation) != 1 or len(representation[0]) != 1 or representation[0][0][0] != chain:
    raise ValueError("Worker returned unexpected models/chains.")
  residues = representation[0][0][1]
  expected = [(chain, n+job["shift"], "") for n in range(start, end+1)]
  if len(residues) != len(expected):
    raise ValueError("Worker returned an incomplete fragment.")
  atoms = {}
  for residue, spec, letter in zip(residues, expected, job["sequence"]):
    number, ins, name, rows = residue
    if (chain, number, ins) != spec or name != _REGISTER_AA[letter]:
      raise ValueError("Worker changed residue identifiers or types.")
    names = set()
    for atom in rows:
      atom_name, alt = atom[0]
      key = (*spec, name, atom_name, alt)
      if (key in atoms or alt or len(atom[2]) != 3 or len(atom[1]) < 3 or
          not all(math.isfinite(v) for v in (*atom[2], *atom[1][:2]))):
        raise ValueError("Worker returned invalid/ambiguous atoms.")
      atoms[key] = atom[2]
      names.add(atom_name.strip())
    if not {"N", "CA", "C", "O"} <= names:
      raise ValueError("Worker removed backbone atoms.")
  scores = {tuple(spec): float(value) for spec, value in candidate["scores"]}
  if (len(candidate["scores"]) != len(expected) or set(scores) != set(expected) or
      any(not math.isfinite(v) or not -1. <= v <= 1. for v in scores.values())):
    raise ValueError("Worker returned invalid/incomplete density scores.")
  if (not math.isclose(candidate["mean"], sum(scores.values())/len(scores), abs_tol=1e-7) or
      not math.isclose(candidate["minimum"], min(scores.values()), abs_tol=1e-7)):
    raise ValueError("Worker density-score summary is inconsistent.")
  sidechain = candidate["sidechain"]
  eligible = sum(letter not in {"G", "A"} for letter in job["sequence"])
  value = sidechain["mean"]
  if (sidechain["eligible"] != eligible or not 0 <= sidechain["count"] <= eligible or
      (value is None) != (sidechain["count"] == 0) or
      value is not None and (not math.isfinite(value) or not -1 <= value <= 1)):
    raise ValueError("Worker returned invalid sidechain scores.")
  return atoms


def _register_import_worker_candidate(pool, result):
  job = pool["jobs"][result["index"]]
  candidate = dict(result["candidate"])
  expected = _register_validate_worker_result(candidate, job, pool["chain"], pool["start"], pool["end"])
  properties = {(ch, n, ins, name, *atom[0]): atom[1][:3] for entry in candidate["representation"]
                for ch, residues in entry for n, ins, name, atoms in residues for atom in atoms}
  source = pool["source"]
  if (not valid_model_molecule_qm(source) or coot.molecule_name(source) != pool["source_name"] or
      _model_coordinate_snapshot(source) != pool["source_snapshot"]):
    raise ValueError("The source changed or was closed; worker results were not imported.")
  if not pool.get("prepare", True):
    identities = {(*spec, record["name"], *atom[0]) for spec, record in pool["source_snapshot"].items()
                  for atom in record["atoms"]}
    if expected.keys() != identities:
      raise ValueError("Selected refinement changed atom identities; previous candidate retained.")
  if _register_map_fingerprint(pool["map"], pool["probes"]) != pool["fingerprint"]:
    raise ValueError("The target map changed; worker results were not imported.")
  existing = set(model_molecule_list())
  model = coot.add_molecule_py(candidate.pop("representation"),
      f"Register {job['offset']:+d}: {pool['chain']} (flex)")
  if model in existing or not valid_model_molecule_qm(model):
    raise RuntimeError("Coot could not create an independent result model.")
  try:
    coot.set_mol_displayed(model, 0)
    imported_snapshot = _model_coordinate_snapshot(model)
    actual = {(*spec, record["name"], *atom[0]): atom[2]
              for spec, record in imported_snapshot.items() for atom in record["atoms"]}
    if actual.keys() != expected.keys() or any(_distance_sq(actual[k], expected[k]) > 1e-8 for k in actual):
      raise RuntimeError("Imported coordinates did not reproduce the worker result.")
    for spec, record in imported_snapshot.items():
      for atom in record["atoms"]:
        original = properties[(*spec, record["name"], *atom[0])]
        if (str(atom[1][2]).strip() != str(original[2]).strip() or
            any(not math.isclose(float(a), float(b), abs_tol=1e-5, rel_tol=1e-5)
                for a, b in zip(atom[1][:2], original[:2]))):
          raise RuntimeError("Imported occupancies/B-factors did not reproduce the worker result.")
    candidate.update(model=model, coloured=False)
    if _supports_direct_user_defined_colouring():
      rows = [(spec, _density_fit_score_to_colour_index(score)) for spec, score in candidate["scores"]]
      candidate["coloured"] = bool(_apply_direct_user_defined_residue_colours(model, [], rows))
    return candidate
  except Exception:
    coot.close_molecule(model)
    raise


def _register_result_grid(values, groups):
  """Use the same bounded, size-grouped columns in result and header buttons."""
  grid = Gtk.Grid(column_spacing=10)
  grid.set_halign(Gtk.Align.START)
  cells = []
  for index, value in enumerate(values):
    cell = Gtk.Label(label=value)
    cell.add_css_class("monospace")
    cell.set_xalign(1 if index in (0, 2, 3, 4) else 0)
    cell.set_width_chars((5, 32, 8, 8, 15, 6)[index])
    if index == 1:
      cell.set_max_width_chars(32)
      cell.set_ellipsize(_coot_gui_repository_module("Pango").EllipsizeMode.END)
      cell.set_tooltip_text(value)
    groups[index].add_widget(cell)
    grid.attach(cell, index, 0, 1, 1)
    cells.append(cell)
  grid.register_result_cells = cells
  return grid


def _register_center_result_row(scroller, button):
  """Center a direct child of the results box, clamping at the list ends."""
  allocation = button.get_allocation()
  adjustment = scroller.get_vadjustment()
  page = adjustment.get_page_size()
  if allocation.height <= 0 or page <= 0:
    return False
  lower = adjustment.get_lower()
  upper = adjustment.get_upper()
  if upper < allocation.y+allocation.height:
    return False
  target = allocation.y+allocation.height/2.-page/2.
  adjustment.set_value(max(lower, min(max(lower, upper-page), target)))
  return True


def compare_local_sequence_registers():
  active = _active_residue_or_status()
  if not active:
    return
  source, chain, centre, ins = active[:4]
  required = ("new_molecule_by_atom_selection", "renumber_residue_range", "mutate",
              "score_rotamers_py", "set_residue_to_rotamer_name", "refine_residues_py", "accept_regularizement",
              "map_to_model_correlation_per_residue_py", "set_imol_refinement_map",
              "refinement_immediate_replacement_state", "set_refinement_immediate_replacement",
              "set_mol_displayed", "mol_is_displayed", "close_molecule", "set_molecule_name",
              "delete_sequence_by_chain_id", "assign_sequence_from_string", "sequence_info_py")
  missing = [name for name in required if not callable(getattr(coot, name, None))]
  try:
    glib = _coot_gui_repository_module("GLib")
  except Exception:
    glib = None
  if missing or globals().get("Gtk") is None or glib is None:
    info_dialog("Register comparison requires the GTK interface and compatible editing APIs. " + ", ".join(missing))
    return
  if ins:
    info_dialog("Register comparison does not support an insertion-code centre.")
    return
  map_id = coot.imol_refinement_map()
  if map_id not in map_molecule_list() or map_is_difference_map(map_id):
    info_dialog("Choose a non-difference refinement map for register comparison.")
    return
  try:
    records = _register_chain_snapshot(source, chain)
    sequence, message = _register_reference_sequence(source, chain, records)
    origin = _register_sequence_origin(records, sequence) if sequence else None
    if message.startswith("Model-derived"):
      origin = min(r["number"] for r in records if not r["ins"] and r["name"] in _REGISTER_PROTEIN_NAMES - {"UNK"})
  except (ValueError, TypeError) as error:
    info_dialog(str(error))
    return
  centre_name = next((r["name"] for r in records if r["number"] == centre and r["ins"] == ins), "")
  needs_sequence_input = not sequence or origin is None or message.startswith("Model-derived")
  if not needs_sequence_input:
    try:
      _register_comparison_targets(records, centre, sequence, origin, 5, 9)
    except (ValueError, TypeError):
      needs_sequence_input = True
  centre_label = f"{chain}:{centre} {centre_name}".strip()
  window = Gtk.Window(title=f"Compare registers: #{source} | Centre {centre_label}")
  window.set_default_size(650, 480)
  box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=6)
  for side in ("start", "end", "top", "bottom"):
    getattr(box, "set_margin_"+side)(8)
  label = Gtk.Label(label=f"Centre: {centre_label} | Model #{source}\n"
                         f"Region {chain}:{centre-4}-{centre+4} | Map #{map_id}")
  label.set_xalign(0)
  box.append(label)
  row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
  origin_row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
  origin_row.append(Gtk.Label(label="Sequence start"))
  origin_entry = Gtk.Entry()
  origin_entry.set_width_chars(7)
  origin_entry.set_max_width_chars(9)
  origin_entry.set_text(str(origin) if origin is not None else "")
  origin_row.append(origin_entry)
  row.append(Gtk.Label(label="Shift +/-"))
  shift_entry = Gtk.Entry()
  shift_entry.set_width_chars(3)
  shift_entry.set_max_width_chars(5)
  shift_entry.set_text("5")
  shift_entry.set_tooltip_text("Test every integer shift from -N to +N; 0 tests the original register only.")
  row.append(shift_entry)
  generate = Gtk.Button(label="Generate")
  row.append(generate)
  box.append(row)
  size_row = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
  size_row.append(Gtk.Label(label="Fragment size"))
  size_entry = Gtk.Entry()
  size_entry.set_width_chars(3)
  size_entry.set_max_width_chars(5)
  size_entry.set_text("9")
  size_entry.set_tooltip_text("Consecutive residues centred on the active residue. Even lengths extend one extra residue towards the C terminus.")
  size_row.append(size_entry)
  box.append(size_row)
  reference = Gtk.Expander(label="Reference sequence needs verification")
  reference.set_visible(needs_sequence_input)
  reference.set_expanded(needs_sequence_input)
  sequence_view = Gtk.TextView()
  sequence_view.set_wrap_mode(Gtk.WrapMode.WORD_CHAR)
  sequence_view.get_buffer().set_text(sequence)
  sequence_view.set_tooltip_text(message)
  sequence_scroll = Gtk.ScrolledWindow()
  sequence_scroll.set_min_content_height(70)
  sequence_scroll.set_child(sequence_view)
  sequence_controls = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=6)
  sequence_controls.append(origin_row)
  sequence_controls.append(sequence_scroll)
  reference.set_child(sequence_controls)
  box.append(reference)
  rigid_fit_option = Gtk.CheckButton(label="Rigid-body fit")
  rigid_fit_available = callable(getattr(coot, "rigid_body_refine_by_atom_selection", None))
  rigid_fit_option.set_active(rigid_fit_available)
  rigid_fit_option.set_sensitive(rigid_fit_available)
  rigid_fit_option.set_tooltip_text(
    "Fit the entire fragment as one rigid body, then select fixed-backbone rotamers."
    if rigid_fit_available else "Rigid-body fitting is unavailable in this Coot build.")
  box.append(rigid_fit_option)
  flexible_option = Gtk.CheckButton(label="Flexibly refine all candidates (slower)")
  flexible_option.set_active(False)
  flexible_option.set_tooltip_text("Two flexible refinement rounds with rotamer selection between them. Otherwise use fast rigid fitting and rotamer selection only.")
  flexible_option.set_tooltip_text("Two flexible refinement rounds in isolated workers using the current map, geometry dictionaries and readable refinement settings. Native settings without getters use worker defaults.")
  box.append(flexible_option)
  worker_note = Gtk.Label(label="Flexible fitting: current map/weight and readable settings are copied; other native settings use worker defaults.", xalign=0)
  worker_note.set_wrap(True)
  worker_note.set_max_width_chars(72)
  worker_note.set_visible(False)
  flexible_option.connect("toggled", lambda *_: worker_note.set_visible(flexible_option.get_active()))
  box.append(worker_note)
  progress = Gtk.Label(label="Fast rigid fit + rotamers. Flexible refinement is optional; CC is a guide.")
  progress.set_wrap(True)
  progress.set_max_width_chars(76)
  progress.set_xalign(0)
  box.append(progress)
  column_groups = [Gtk.SizeGroup(mode=Gtk.SizeGroupMode.HORIZONTAL) for _ in range(6)]
  headings = Gtk.Button()
  headings.add_css_class("flat")
  headings.set_focusable(False)
  headings.set_can_target(False)
  headings.set_child(_register_result_grid(("Shift", "Sequence", "Mean CC", "Min CC", "SC CC (n)", "Fit"), column_groups))
  headings.get_child().register_result_cells[4].set_tooltip_text(
      "SC CC: correlation beyond C-beta; scored/eligible residues in parentheses. Gly/Ala excluded.")
  box.append(headings)
  rows = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=2)
  scroll = Gtk.ScrolledWindow()
  scroll.set_vexpand(True)
  scroll.set_child(rows)
  box.append(scroll)
  legend = Gtk.Label(label=_colour_band_legend_text("CC", 0.0, 1.0) if _supports_direct_user_defined_colouring()
                     else "Density-fit colouring unavailable in this build; scores still available.")
  legend.set_wrap(True)
  legend.set_xalign(0)
  legend_expander = Gtk.Expander(label="Density-fit colour scale")
  legend_expander.set_child(legend)
  box.append(legend_expander)
  buttons = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=8)
  previous = Gtk.Button(label="Previous")
  next_button = Gtk.Button(label="Next")
  previous.set_sensitive(False)
  next_button.set_sensitive(False)
  buttons.append(previous)
  buttons.append(next_button)
  keep = Gtk.Button(label="Keep selected")
  keep.set_tooltip_text("Keep this fragment as a separate model; discard the other candidates.")
  keep.set_sensitive(False)
  merge_selected = Gtk.Button(label="Merge selected")
  merge_available = all(callable(getattr(coot, name, None)) for name in
      ("copy_molecule", "merge_molecules_py", "change_chain_id", "delete_residue", "set_undo_molecule", "apply_undo"))
  merge_selected.set_sensitive(False)
  merge_selected.set_tooltip_text("Replace the original range in its chain, trimming overlapping adjacent boundaries. Preview required; one Coot Undo restores the merge."
                                  if merge_available else "Native merge/Undo APIs are unavailable in this build.")
  refine_selected = Gtk.Button(label="Flexibly refine selected")
  refine_selected.set_sensitive(False)
  refine_selected.set_tooltip_text("Refine a copy in an isolated worker, then update its scores and colouring. Preserve the candidate if refinement fails. Current map/weight and readable settings are copied; parameters without getters use worker defaults.")
  discard = Gtk.Button(label="Discard all")
  buttons.append(keep)
  buttons.append(merge_selected)
  buttons.append(discard)
  box.append(buttons)
  box.append(refine_selected)
  stop = Gtk.Button(label="Stop")
  stop.set_sensitive(False)
  buttons.append(stop)
  state = {"closed": False, "candidates": [], "selected": None, "idle": None,
           "hidden_original": False, "index": 0, "targets": [], "snapshot": None, "buttons": [],
           "rigid_fit": True, "flexible": False, "scoring_cache": None, "refining": False,
           "pool": None, "pending_rows": {}, "failures": [], "merging": False,
           "scroll_tick": None}
  def cancel_scroll():
    pending = state["scroll_tick"]
    state["scroll_tick"] = None
    if pending is not None:
      pending[0].remove_tick_callback(pending[1])
  def center_button(button, candidate):
    cancel_scroll()
    frames = 0
    def after_layout(widget, _clock):
      nonlocal frames
      frames += 1
      if state["closed"] or state["selected"] is not candidate:
        state["scroll_tick"] = None
        return False
      # Tick callbacks precede layout; the second frame sees the new row sizes.
      if frames < 2:
        return True
      if _register_center_result_row(scroll, widget) or frames >= 8:
        state["scroll_tick"] = None
        return False
      return True
    tick = button.add_tick_callback(after_layout)
    if tick:
      state["scroll_tick"] = (button, tick)
  def choose(candidate):
    if state["closed"] or state["refining"] or state["merging"] or not valid_model_molecule_qm(candidate["model"]):
      return
    for other in state["candidates"]:
      if valid_model_molecule_qm(other["model"]):
        coot.set_mol_displayed(other["model"], int(other is candidate))
    state["selected"] = candidate
    for button, other in state["buttons"]:
      if other is candidate:
        button.add_css_class("suggested-action")
        center_button(button, candidate)
      else:
        button.remove_css_class("suggested-action")
    keep.set_sensitive(state["idle"] is None)
    merge_selected.set_sensitive(merge_available and state["idle"] is None)
    refine_selected.set_sensitive(state["idle"] is None)
    add_status_bar_text(f"Register {candidate['offset']:+d} | mean CC {candidate['mean']:.3f} | min CC {candidate['minimum']:.3f}")
  def navigate(direction):
    available = [c for c in state["candidates"] if valid_model_molecule_qm(c["model"])]
    if state["closed"] or not available:
      return
    index = next((i for i, c in enumerate(available) if c is state["selected"]), None)
    destination = (index + direction) % len(available) if index is not None else (0 if direction > 0 else -1)
    choose(available[destination])
  previous.connect("clicked", lambda *_: navigate(-1))
  next_button.connect("clicked", lambda *_: navigate(1))
  def finish(keep_selected=False):
    if state["closed"]:
      return
    state["closed"] = True
    cancel_scroll()
    if state["pool"] is not None:
      state["pool"]["cancel"].set()
    if state["idle"] is not None:
      glib.source_remove(state["idle"])
      state["idle"] = None
    chosen = state["selected"] if keep_selected else None
    _analysis_cc_close(state["scoring_cache"])
    state["scoring_cache"] = None
    for candidate in state["candidates"]:
      if candidate is not chosen and valid_model_molecule_qm(candidate["model"]):
        _REGISTER_REFERENCE_ORIGINS.pop((candidate["model"], chain), None)
        coot.close_molecule(candidate["model"])
    if state["hidden_original"] and valid_model_molecule_qm(source):
      coot.set_mol_displayed(source, 1)
    window.destroy()
  def update_button(button, candidate):
    sidechain = candidate["sidechain"]
    sidechain_text = f"{sidechain['mean']:.3f}" if sidechain["mean"] is not None else "n/a"
    values = (f"{candidate['offset']:+d}", candidate['sequence'], f"{candidate['mean']:.3f}",
              f"{candidate['minimum']:.3f}", f"{sidechain_text} ({sidechain['count']}/{sidechain['eligible']})",
              "Flex" if candidate.get("flexible") else "Rigid")
    cells = vars(button).get("register_result_cells")
    if cells is not None:
      for index, (cell, value) in enumerate(zip(cells, values)):
        cell.set_text(value)
        if index == 1:
          cell.set_tooltip_text(value)
    else:
      grid = _register_result_grid(values, column_groups)
      button.register_result_cells = grid.register_result_cells
      button.set_child(grid)
    button.set_tooltip_text(f"Centre {chain}:{centre+candidate['offset']} | " +
                            ("Coloured by density fit" if candidate["coloured"] else "Density-fit colouring unavailable"))
  def add_row(widget, index):
    placeholder = state["pending_rows"].pop(index, None)
    if placeholder is None:
      rows.append(widget)
    else:
      rows.insert_child_after(widget, placeholder)
      rows.remove(placeholder)
  def add_candidate(candidate, index):
    try:
      _register_associate_reference(candidate["model"], chain, state["reference_sequence"], state["reference_origin"])
    except Exception:
      _REGISTER_REFERENCE_ORIGINS.pop((candidate["model"], chain), None)
      coot.close_molecule(candidate["model"])
      raise
    state["candidates"].append(candidate)
    state["candidates"].sort(key=lambda c: c["offset"])
    button = Gtk.Button()
    update_button(button, candidate)
    button.connect("clicked", lambda *_args, candidate=candidate: choose(candidate))
    add_row(button, index)
    state["buttons"].append((button, candidate))
    previous.set_sensitive(True)
    next_button.set_sensitive(True)
    if state["selected"] is None:
      choose(candidate)
  def failed_row(index, message):
    offset = state["targets"][index][0]
    state["failures"].append((offset, message))
    widget = Gtk.Label(label=f"{offset:+d}  Failed: {message}")
    widget.set_wrap(True)
    widget.set_xalign(0)
    add_row(widget, index)
    print(f"Register comparison {offset:+d}: {message}")
  def finish_generation(stopped=False):
    _analysis_cc_close(state["scoring_cache"])
    state["scoring_cache"] = None
    state["idle"] = None
    stop.set_sensitive(False)
    keep.set_sensitive(state["selected"] is not None)
    available = [c for c in state["candidates"] if valid_model_molecule_qm(c["model"])]
    sidechain_available = [c for c in available if c["sidechain"]["mean"] is not None]
    best = max(sidechain_available or available,
               key=lambda c: (c["sidechain"]["mean"], c["mean"]) if sidechain_available else (c["mean"],), default=None)
    if best is not None:
      choose(best)
    metric_label = "SC CC" if sidechain_available else "mean CC"
    score = best["sidechain"]["mean"] if sidechain_available else (best["mean"] if best else None)
    progress.set_text(("Stopped. " if stopped else "")+
        (f"{len(available)}/{len(state['targets'])} built. Highest {metric_label}: {best['offset']:+d} ({score:.3f})."
         if best else "No candidates succeeded; inspect the failed rows."))
    for index, widget in list(state["pending_rows"].items()):
      widget.set_text(f"{state['targets'][index][0]:+d}  Not completed")
    state["pending_rows"].clear()
  def stop_workers(*_args):
    if state["pool"] is not None:
      state["pool"]["cancel"].set()
      stop.set_sensitive(False)
      progress.set_text("Stopping workers; completed candidates will be retained.")
  stop.connect("clicked", stop_workers)
  def start_workers(selected=None):
    import queue
    if state["closed"]:
      return
    state.pop("worker_message", None)
    mode = "selected" if selected is not None else "all"
    if selected is None:
      args = (source, chain, state["start"], state["end"], state["targets"], map_id)
    else:
      offset = selected["offset"]
      args = (selected["model"], chain, state["start"]+offset, state["end"]+offset,
              [(offset, selected["sequence"])], map_id)
    pool = _register_workers_start(*args, rigid_fit=state["rigid_fit"] if selected is None else False,
                                    prepare=selected is None)
    if state["closed"]:
      pool["cancel"].set()
      return
    state["pool"] = pool
    state["worker_diagnostics"] = pool.setdefault("diagnostics", [])
    state["worker_count"] = pool["count"]
    stop.set_sensitive(True)
    progress.set_text(f"Refining in {pool['count']} isolated Coot worker(s)...")
    def poll_workers():
      if state["closed"]:
        pool["cancel"].set()
        return False
      try:
        event, payload = pool["events"].get_nowait()
      except queue.Empty:
        return True
      if event == "result" and not pool["cancel"].is_set():
        imported = None
        try:
          if "error" in payload:
            raise RuntimeError(payload["error"])
          imported = _register_import_worker_candidate(pool, payload)
          if state["closed"]:
            _REGISTER_REFERENCE_ORIGINS.pop((imported["model"], chain), None)
            if valid_model_molecule_qm(imported["model"]):
              coot.close_molecule(imported["model"])
            return False
          if mode == "all":
            add_candidate(imported, payload["index"])
          else:
            _register_associate_reference(imported["model"], chain, state["reference_sequence"], state["reference_origin"])
            old = selected["model"]
            coot.close_molecule(old)
            _REGISTER_REFERENCE_ORIGINS.pop((old, chain), None)
            selected.update(imported)
            for button, candidate in state["buttons"]:
              if candidate is selected:
                update_button(button, candidate)
            state["worker_message"] = f"Refined register {selected['offset']:+d}; scores updated. Other candidates unchanged."
        except Exception as error:
          if imported is not None and (mode == "all" and imported not in state["candidates"] or
                                      mode == "selected" and imported["model"] != selected["model"]):
            _REGISTER_REFERENCE_ORIGINS.pop((imported["model"], chain), None)
            if valid_model_molecule_qm(imported["model"]):
              coot.close_molecule(imported["model"])
          if mode == "all":
            failed_row(payload["index"], str(error))
          else:
            state["worker_message"] = f"Refinement failed; previous candidate retained: {error}"
        if mode == "all":
          state["index"] += 1
          progress.set_text(f"Completed {state['index']}/{len(state['targets'])} | {pool['count']} workers")
      elif event == "error":
        state["worker_message"] = "Workers failed: "+payload
        progress.set_text(state["worker_message"])
      elif event == "done":
        state["pool"] = None
        state["idle"] = None
        stop.set_sensitive(False)
        if mode == "all":
          finish_generation(stopped=payload)
          if state.get("worker_message"):
            progress.set_text(state["worker_message"])
        else:
          state["refining"] = False
          previous.set_sensitive(True)
          next_button.set_sensitive(True)
          choose(selected)
          progress.set_text("Stopped; previous candidate retained." if payload else
                            state.pop("worker_message", "Refinement finished."))
        return False
      return True
    try:
      state["idle"] = glib.timeout_add(50, poll_workers)
      if not state["idle"]:
        raise RuntimeError("Could not schedule worker progress polling.")
    except Exception:
      pool["cancel"].set()
      state["pool"] = None
      raise
  def refine_chosen(*_args):
    candidate = state["selected"]
    if state["closed"] or state["idle"] is not None or candidate is None:
      return
    state["refining"] = True
    for widget in (keep, merge_selected, refine_selected, previous, next_button):
      widget.set_sensitive(False)
    progress.set_text(f"Flexibly refining register {candidate['offset']:+d}...")
    def run():
      if state["closed"]:
        return False
      try:
        if map_id not in map_molecule_list() or not valid_model_molecule_qm(candidate["model"]):
          raise ValueError("Candidate or refinement map is no longer available.")
        start_workers(candidate)
      except Exception as error:
        progress.set_text(f"Refinement failed; previous candidate retained: {error}")
        state["refining"] = False
        state["idle"] = None
        for widget in (previous, next_button):
          widget.set_sensitive(True)
        choose(candidate)
      return False
    state["idle"] = glib.idle_add(run)
  refine_selected.connect("clicked", refine_chosen)
  def step():
    if state["closed"]:
      return False
    index = state["index"]
    offset, target = state["targets"][index]
    try:
      if map_id not in map_molecule_list() or _register_chain_snapshot(source, chain) != state["snapshot"]:
        raise ValueError("Source model or map changed; discard and restart the comparison.")
      candidate = _build_register_comparison_fragment(
        source, chain, state["start"], state["end"], offset, target, map_id,
        rigid_fit=state["rigid_fit"], scoring_cache=state["scoring_cache"], flexible=state["flexible"])
      if state["closed"]:
        coot.close_molecule(candidate["model"])
        return False
      add_candidate(candidate, index)
    except Exception as error:
      if state["closed"]:
        return False
      failed_row(index, str(error))
    state["index"] += 1
    total = len(state["targets"])
    if state["index"] == total:
      finish_generation()
      return False
    progress.set_text(f"Built {state['index']}/{total}; next shift {state['targets'][state['index']][0]:+d}")
    return True
  def begin(*_args, confirmed_size=None):
    if state["closed"] or state["idle"] is not None:
      return
    try:
      if map_id not in map_molecule_list():
        raise ValueError("The selected refinement map is no longer available.")
      pending_refinement = getattr(coot, "get_continue_updating_refinement_atoms_state", None)
      if callable(pending_refinement) and pending_refinement():
        raise ValueError("Accept or cancel the current refinement before comparing registers.")
      ongoing = getattr(coot, "refinement_already_ongoing_p", None)
      if callable(ongoing) and ongoing():
        raise ValueError("Accept or cancel the current refinement before comparing registers.")
      buffer = sequence_view.get_buffer()
      reference_sequence = buffer.get_text(buffer.get_start_iter(), buffer.get_end_iter(), False)
      snapshot = _register_chain_snapshot(source, chain)
      try:
        start, end, targets = _register_comparison_targets(
          snapshot, centre, reference_sequence, origin_entry.get_text(), shift_entry.get_text(), size_entry.get_text())
      except (ValueError, TypeError):
        reference.set_visible(True)
        reference.set_expanded(True)
        raise
    except (ValueError, TypeError) as error:
      progress.set_text(str(error))
      return
    fragment_size = end-start+1
    flexible = bool(flexible_option.get_active())
    warning_limit = 12 if flexible else 30
    confirmation = (fragment_size, flexible)
    if fragment_size > warning_limit and confirmed_size != confirmation:
      generate.set_sensitive(False)
      def cancel_generation():
        if not state["closed"]:
          generate.set_sensitive(True)
      def confirm_generation():
        if not state["closed"]:
          generate.set_sensitive(True)
          begin(confirmed_size=confirmation)
      generic_confirm_dialog(
        "Generate large register fragments?",
        f"Fit {len(targets)} fragments of {fragment_size} residues each?\n" +
        ("Flexible refinement of fragments longer than 12 residues may take a while."
         if flexible else "Rigid fitting and rotamer testing of fragments longer than 30 residues may take a while."),
        "Cancel", cancel_generation, "Generate", confirm_generation,
        handle_close_function=cancel_generation,
      )
      return
    state.update(start=start, end=end, targets=targets, snapshot=snapshot,
                 reference_sequence=_register_clean_sequence(reference_sequence), reference_origin=int(origin_entry.get_text()),
                 rigid_fit=rigid_fit_available and bool(rigid_fit_option.get_active()),
                 flexible=bool(flexible_option.get_active()))
    state["scoring_cache"] = _analysis_cc_open(map_id)
    state["hidden_original"] = bool(coot.mol_is_displayed(source))
    if state["hidden_original"]:
      coot.set_mol_displayed(source, 0)
    generate.set_sensitive(False)
    origin_entry.set_sensitive(False)
    shift_entry.set_sensitive(False)
    size_entry.set_sensitive(False)
    label.set_text(f"Centre: {centre_label} | Model #{source}\nRegion {chain}:{start}-{end} | Map #{map_id}")
    sequence_view.set_editable(False)
    rigid_fit_option.set_sensitive(False)
    flexible_option.set_sensitive(False)
    progress.set_text(f"Building register {targets[0][0]:+d}...")
    if state["flexible"]:
      for index, (offset, _target) in enumerate(targets):
        widget = Gtk.Label(label=f"{offset:+d}  Waiting...")
        widget.set_xalign(0)
        rows.append(widget)
        state["pending_rows"][index] = widget
      def launch():
        if state["closed"]:
          return False
        try:
          start_workers()
        except Exception as error:
          for index in list(state["pending_rows"]):
            failed_row(index, str(error))
          finish_generation()
          progress.set_text("Cannot start isolated refinement: "+str(error))
        return False
      state["idle"] = glib.idle_add(launch)
    else:
      state["idle"] = glib.idle_add(step)
  generate.connect("clicked", begin)
  def merge_chosen(*_args):
    candidate = state['selected']
    if state['closed'] or state['idle'] is not None or state['refining'] or state['merging'] or candidate is None:
      return
    try:
      if _register_chain_snapshot(source, chain) != state['snapshot']:
        raise ValueError("The original chain changed; discard and regenerate the comparison before merging.")
      original = _model_coordinate_snapshot(source)
      fragment = _model_coordinate_snapshot(candidate['model'])
      plan = _register_merge_plan(original, fragment, chain, state['start'], state['end'], candidate['offset'])
      link_getter = getattr(coot, 'link_info_py', None)
      if callable(link_getter) and any(_links_containing_residue(source, s) for s in plan['deleted']):
        raise ValueError("The replaced/trimmed residues have explicit LINK records. Review/remove those links before merging.")
      source_signature = _register_shift_model_signature(source)
      candidate_signature = _register_shift_model_signature(candidate['model'])
    except Exception as error:
      info_dialog(f"Cannot merge selected candidate; original unchanged.\n\n{error}")
      return
    state['merging'] = True
    for widget in (keep, merge_selected, refine_selected, previous, next_button):
      widget.set_sensitive(False)
    def cancel():
      state['merging'] = False
      if not state['closed']:
        previous.set_sensitive(True)
        next_button.set_sensitive(True)
        choose(candidate)
    def apply():
      if state['closed']:
        return
      try:
        _apply_register_comparison_merge(source, candidate, chain, plan, source_signature, candidate_signature,
            reference=(state['reference_sequence'], state['reference_origin']))
      except Exception as error:
        cancel()
        info_dialog(str(error))
        return
      finish(False)
      coot.set_mol_displayed(source, 1)
      add_status_bar_text(f"Merged register {candidate['offset']:+d} into #{source} {chain}:{plan['first']}-{plan['last']}; trimmed {len(plan['trim'])} boundary residues. Coot Undo restores the merge.")
    trimmed = ', '.join(f"{s[1]}{s[2]} ({reason})" for s, reason in sorted(plan['trim'].items())) or 'none'
    generic_confirm_dialog("Merge selected register?",
        f"Replace #{source} {chain}:{state['start']}-{state['end']} with the selected candidate\n"
        f"at {chain}:{plan['first']}-{plan['last']}.\n\nAdditional boundary residues to delete: {trimmed}.\n\n"
        "Vacated residue numbers remain gaps. Joins are not automatically rebuilt or refined.\n"
        "One Coot Undo restores the operation.",
        "Cancel", cancel, "Merge selected", apply, handle_close_function=cancel)
  merge_selected.connect("clicked", merge_chosen)
  keep.connect("clicked", lambda *_: finish(True))
  discard.connect("clicked", lambda *_: finish(False))
  window.connect("close-request", lambda *_: finish(False) or True)
  window.set_child(box)
  window.register_comparison_state = state
  state["widgets"] = dict(generate=generate, rigid=rigid_fit_option, flexible=flexible_option,
      refine_selected=refine_selected, progress=progress, shift=shift_entry, discard=discard, keep=keep, merge=merge_selected,
      size=size_entry, stop=stop, scroll=scroll, rows=rows, headings=headings, previous=previous, next=next_button)
  window.present()
  return window


